#@title deep thinking
def think_deeply(question):
    has_hinglish = any(w in question.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'kaise', 'kyun',
        'mujhe', 'samjhao', 'btao', 'toh', 'aur', 'mai'
    ])
    lang_rule = "REPLY IN HINGLISH (Hindi+English mix like a dost)" if has_hinglish else "REPLY IN ENGLISH"

    cot_prompt = f"""<|system|>
{SYSTEM_PROMPT}
LANGUAGE RULE: {lang_rule}
<|end|>
<|user|>
{question}
<|end|>
<|assistant|>
Bhai, """

    output = llm(cot_prompt, max_tokens=600, temperature=0.7)
    return "Bhai, " + output['choices'][0]['text'].strip()

print("✅ Deep thinking function ready!")

#@title Master chat function
def chat_with_mkai(user_message):
    global conversation_history

    # Emotion detect karo
    emotion = detect_emotion(user_message)
    emotion_instruction = get_emotion_instruction(emotion)

    # Memory
    memory_context = get_memory_context()
    extract_and_save_facts(user_message)

    # Language detect
    has_hinglish = any(w in user_message.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'nahi', 'haan', 'mera',
        'tera', 'karo', 'toh', 'aur', 'bata', 'ho', 'mai',
        'mujhe', 'samajh', 'yrr', 'accha', 'theek', 'chal',
        'kr', 'de', 'le', 'ja', 'aa', 'tha', 'thi', 'hun'
    ])
    hindi_chars = any('\u0900' <= c <= '\u097F' for c in user_message)

    if hindi_chars:
        lang_rule = "REPLY IN HINDI SCRIPT ONLY."
    elif has_hinglish:
        lang_rule = "REPLY IN HINGLISH — mix Hindi and English casually like a smart dost. Example style: 'Bhai ye bilkul sahi hai, aise kaam karega...'"
    else:
        lang_rule = "REPLY IN ENGLISH ONLY."

    # Complex ya simple?
    if is_complex_question(user_message) and len(user_message) > 30:
        print("🧠 Deep thinking mode...")
        response = think_deeply(user_message)
    else:
        # Normal fast response
        full_system = (SYSTEM_PROMPT + memory_context +
                      f"\nEMOTION: {emotion}" +
                      f"\nEMOTION RULE: {emotion_instruction}" +
                      f"\nLANGUAGE RULE: {lang_rule}")

        prompt = f"<|system|>\n{full_system}<|end|>\n"

        for msg in conversation_history[-6:]:
            prompt += f"<|{msg['role']}|>\n{msg['content']}<|end|>\n"

        prompt += f"<|user|>\n{user_message}<|end|>\n<|assistant|>\n"

        output = llm(
            prompt,
            max_tokens=600,
            stop=["<|end|>", "<|user|>"],
            temperature=0.75,
            top_p=0.95,
            repeat_penalty=1.1  # Repeat nahi karega
        )
        response = output['choices'][0]['text'].strip()

    # History save
    conversation_history.append({"role": "user", "content": user_message})
    conversation_history.append({"role": "assistant", "content": response})

    print(f"🎭 Emotion: {emotion}")
    print(f"🌐 Language: {'Hinglish' if has_hinglish else 'English'}")
    print(f"🤖 MK-AI: {response}\n")

    return response

conversation_history = []
print("✅ Master chat function ready!")

#@title Emotion Detector Fix
def detect_emotion(text):
    text_lower = text.lower()
    sad_words = ['sad', 'dukhi', 'rona', 'bura', 'depressed', 'akela', 'lonely', 'hurt', 'pain', 'cry']
    happy_words = ['khush', 'happy', 'excited', 'great', 'amazing', 'awesome', 'mast', 'zabardast', 'woah']
    frustrated_words = ['frustrated', 'kaam nahi', 'nahi chal', 'problem', 'error', 'stuck', 'help']
    angry_words = ['bakwaas', 'bekar', 'stupid', 'angry', 'gussa', 'worst', 'hate', 'irritating']
    confused_words = ['samajh nahi', 'confused', 'kya matlab', 'explain', 'kaise', 'kyun', 'what', 'how']

    if any(w in text_lower for w in sad_words): return 'sad'
    elif any(w in text_lower for w in angry_words): return 'angry'
    elif any(w in text_lower for w in frustrated_words): return 'frustrated'
    elif any(w in text_lower for w in happy_words): return 'happy'
    elif any(w in text_lower for w in confused_words): return 'confused'
    else: return 'neutral'

def get_emotion_instruction(emotion):
    instructions = {
        'sad': "User is feeling sad. Be warm and supportive.",
        'angry': "User is angry. Be calm and patient.",
        'frustrated': "User is frustrated. Be solution-focused.",
        'happy': "User is happy. Match their energy!",
        'confused': "User is confused. Be clear and simple.",
        'neutral': "Normal conversation. Be helpful and friendly."
    }
    return instructions.get(emotion, instructions['neutral'])

print("✅ Emotion detector ready!")

#@title Memory system
import json, os, time

# User ki facts yaad rakhega
USER_FACTS_FILE = '/content/drive/MyDrive/MK-AI-Models/user_facts.json'

def load_user_facts():
    if os.path.exists(USER_FACTS_FILE):
        with open(USER_FACTS_FILE, 'r') as f:
            return json.load(f)
    return {}

def save_user_fact(key, value):
    facts = load_user_facts()
    facts[key] = value
    with open(USER_FACTS_FILE, 'w') as f:
        json.dump(facts, f, indent=2)
    print(f"✅ Yaad kar liya: {key} = {value}")

def extract_and_save_facts(user_message):
    msg = user_message.lower()

    # Naam yaad karna
    if 'mera naam' in msg or 'my name is' in msg or 'main hun' in msg:
        words = user_message.split()
        for i, word in enumerate(words):
            if word.lower() in ['naam', 'name', 'hun', 'is'] and i+1 < len(words):
                save_user_fact('user_name', words[i+1])
                break

    # City yaad karna
    if 'mera city' in msg or 'main rehta' in msg or 'i live in' in msg or 'i am from' in msg:
        save_user_fact('mentioned_location', user_message)

def get_memory_context():
    facts = load_user_facts()
    if not facts:
        return ""
    facts_str = "\n".join([f"- {k}: {v}" for k, v in facts.items()])
    return f"\nUSER KE BAARE MEIN PATA HAI:\n{facts_str}\n"

# Conversation history
conversation_history = []

print("✅ Memory system ready!")

