def is_complex_question(question):
    complex_keywords = [
        'explain', 'why', 'how does', 'difference between', 'compare',
        'analyze', 'kaise', 'kyun', 'samjhao', 'difference', 'better',
        'should i', 'what happens', 'kya hoga', 'best way', 'pros cons'
    ]
    return any(k in question.lower() for k in complex_keywords)

