#@title ocr pdf ready
import fitz
import pytesseract
from PIL import Image
import io

def read_pdf(pdf_path):
    doc = fitz.open(pdf_path)
    full_text = ""
    total_pages = len(doc)

    print(f"⏳ {total_pages} pages padh raha hun...")

    for page_num in range(total_pages):
        page = doc.load_page(page_num)

        # Pehle normal text try karo
        text = page.get_text()

        # Agar text kam hai toh OCR use karo
        if len(text.strip()) < 50:
            pix = page.get_pixmap(matrix=fitz.Matrix(2, 2))
            img = Image.open(io.BytesIO(pix.tobytes("png")))
            text = pytesseract.image_to_string(img, lang='eng+hin')

        full_text += f"\n--- Page {page_num + 1} ---\n{text}"

        if (page_num + 1) % 10 == 0:
            print(f"✅ {page_num + 1}/{total_pages} pages done...")

    doc.close()
    print(f"✅ PDF padh liya! Total: {len(full_text)} characters")
    return full_text

print("✅ OCR wala PDF reader ready!")

#@title Vector Database ready
import chromadb
from sentence_transformers import SentenceTransformer

# Embedding model load karo (PDF ko numbers mein convert karta hai)
print("⏳ Embedding model load ho raha hai...")
embedder = SentenceTransformer('all-MiniLM-L6-v2')
print("✅ Embedding model ready!")

# ChromaDB setup
chroma_client = chromadb.Client()

def create_pdf_database(pdf_path, collection_name="mk_ai_docs"):
    """PDF ko database mein save karo"""

    # Pehle old collection delete karo agar hai
    try:
        chroma_client.delete_collection(collection_name)
    except:
        pass

    collection = chroma_client.create_collection(collection_name)

    # PDF padho
    print(f"📖 PDF padh raha hun: {pdf_path}")
    text = read_pdf(pdf_path)

    # Chunks banao
    chunks = split_into_chunks(text)

    # Embeddings banao aur save karo
    print("⏳ PDF ko database mein save kar raha hun...")

    for i, chunk in enumerate(chunks):
        embedding = embedder.encode(chunk).tolist()
        collection.add(
            documents=[chunk],
            embeddings=[embedding],
            ids=[f"chunk_{i}"]
        )

    print(f"✅ PDF database mein save ho gaya! {len(chunks)} chunks stored.")
    return collection

print("✅ Vector database ready!")

#@title Chunking ready
def split_into_chunks(text, chunk_size=200, overlap=50):
    words = text.split()
    chunks = []
    for i in range(0, len(words), chunk_size - overlap):
        chunk = " ".join(words[i:i + chunk_size])
        if chunk.strip() and len(chunk.strip()) > 30:
            chunks.append(chunk)
    print(f"✅ {len(chunks)} chunks bane!")
    return chunks

print("✅ Chunking ready!")

#@title English rag ready
def ask_pdf(question, collection_name="mk_ai_docs", top_k=4):
    try:
        collection = chroma_client.get_collection(collection_name)
    except:
        print("❌ Pehle PDF upload karo!")
        return

    question_embedding = embedder.encode(question).tolist()
    results = collection.query(
        query_embeddings=[question_embedding],
        n_results=top_k
    )

    relevant_chunks = "\n\n".join(results['documents'][0])
    relevant_chunks = relevant_chunks[:1500]

    rag_prompt = f"""<|system|>
You are MK-AI. Reply in English only. Answer from document only. Be clear and detailed.
<|end|>
<|user|>
Document:
{relevant_chunks}

Question: {question}
<|end|>
<|assistant|>
"""

    output = llm(rag_prompt, max_tokens=400, temperature=0.3)
    answer = output['choices'][0]['text'].strip()

    print(f"\n🤖 MK-AI: {answer}\n")
    return answer

print("✅ English RAG ready!")

