#@title Voice to text
import whisper
import sounddevice as sd
import numpy as np
import scipy.io.wavfile as wav
import tempfile
import os

print("⏳ Whisper load ho raha hai...")
whisper_model = whisper.load_model("tiny")
print("✅ Whisper ready!")

def record_audio(seconds=5, sample_rate=16000):
    print(f"🎤 Bol bhai... ({seconds} seconds)")
    audio = sd.rec(
        int(seconds * sample_rate),
        samplerate=sample_rate,
        channels=1,
        dtype='float32'
    )
    sd.wait()
    print("✅ Recording complete!")
    return audio, sample_rate

def voice_to_text(seconds=5):
    audio, sr = record_audio(seconds)

    with tempfile.NamedTemporaryFile(suffix='.wav', delete=False) as f:
        wav.write(f.name, sr, (audio * 32767).astype(np.int16))
        temp_path = f.name

    # Language auto detect
    result = whisper_model.transcribe(temp_path)
    text = result['text'].strip()
    detected_lang = result['language']  # 'hi' ya 'en'

    os.unlink(temp_path)

    print(f"🗣️ Tune bola: {text}")
    print(f"🌐 Language detected: {detected_lang}")
    return text, detected_lang

print("✅ Voice to text ready!")

