#@title Text to voice
from gtts import gTTS
from IPython.display import Audio, display
import os, re

def text_to_voice(text):
    if not text or len(text.strip()) < 3:
        return
    output_path = '/content/response.mp3'
    hindi_chars = any('\u0900' <= c <= '\u097F' for c in text)
    tts_lang = 'hi' if hindi_chars else 'en'
    try:
        tts = gTTS(text=text, lang=tts_lang, slow=False)
        tts.save(output_path)
        with open(output_path, 'rb') as f:
            audio_data = f.read()
        display(Audio(data=audio_data, autoplay=True))
        print(f"🔊 MK-AI bol raha hai...")
    except Exception as e:
        print(f"⚠️ Voice error: {e}")

print("✅ text_to_voice ready!")

#@title Voice Chat Ready
def voice_chat():
    print("🎤 Voice Chat shuru! 'band karo' bolo rokne ke liye\n")

    while True:
        try:
            # User ki awaaz suno
            user_text = voice_to_text(seconds=6)

            if not user_text:
                continue

            # Band karne ka command
            if any(w in user_text.lower() for w in ['band karo', 'stop', 'bye', 'exit']):
                text_to_voice("Theek hai bhai, milte hain phir!")
                print("👋 Voice chat band ho gaya!")
                break

            # MK-AI se jawab lo
            print("🤔 MK-AI soch raha hai...")
            response = chat_with_mkai(user_text)

            # Awaaz mein bolo
            text_to_voice(response)

        except KeyboardInterrupt:
            print("\n👋 Voice chat band!")
            break

print("✅ Voice chat ready!")

