#@title Theme Engine Ready

from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor, white, black
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
from reportlab.lib.units import inch, cm
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_JUSTIFY
import io, os, re, json

def get_pdf_theme(topic):
    topic_lower = topic.lower()
    if any(w in topic_lower for w in ['science', 'physics', 'chemistry', 'electrical']):
        return {'primary': '#003580', 'accent': '#0096FF', 'light': '#E8F4FF'}
    elif any(w in topic_lower for w in ['business', 'marketing', 'finance']):
        return {'primary': '#1B4332', 'accent': '#40916C', 'light': '#D8F3DC'}
    elif any(w in topic_lower for w in ['tech', 'ai', 'computer', 'coding']):
        return {'primary': '#10002B', 'accent': '#9600FF', 'light': '#E8CCFF'}
    elif any(w in topic_lower for w in ['health', 'medical', 'doctor']):
        return {'primary': '#003049', 'accent': '#00B4D8', 'light': '#CAF0F8'}
    elif any(w in topic_lower for w in ['history', 'ancient', 'war']):
        return {'primary': '#3D1A00', 'accent': '#C8963E', 'light': '#FFF3E0'}
    else:
        return {'primary': '#1A1A2E', 'accent': '#6464FF', 'light': '#EEEEFF'}

print("✅ PDF theme engine ready!")

#@title PDF Content Generator
def generate_pdf_content(topic, content_type="document"):
    print(f"🤔 AI content bana raha hai: {topic}")

    prompt = f"""<|system|>
You are an expert document writer. Generate detailed document content in JSON format only. No extra text.
<|end|>
<|user|>
Create a professional {content_type} on: {topic}

Return ONLY this JSON:
{{
  "title": "Document title",
  "subtitle": "One line description",
  "author": "MK-AI",
  "sections": [
    {{
      "heading": "Section heading",
      "content": "Detailed paragraph content here. At least 3-4 sentences explaining the topic thoroughly.",
      "points": ["Key point 1", "Key point 2", "Key point 3"]
    }}
  ],
  "conclusion": "Final concluding paragraph"
}}

Rules:
- Minimum 4 sections
- Each section = detailed paragraph + 3-4 bullet points
- Professional tone
- Comprehensive coverage
<|end|>
<|assistant|>
"""

    output = llm(prompt, max_tokens=2000, temperature=0.7)
    response = output['choices'][0]['text'].strip()

    try:
        json_match = re.search(r'\{.*\}', response, re.DOTALL)
        if json_match:
            content = json.loads(json_match.group())
            print(f"✅ {len(content['sections'])} sections ready!")
            return content
    except:
        pass

    print("⚠️ Fallback content...")
    return {
        "title": topic,
        "subtitle": f"A comprehensive document on {topic}",
        "author": "MK-AI",
        "sections": [
            {
                "heading": "Introduction",
                "content": f"This document provides a comprehensive overview of {topic}. It covers all the essential aspects and key concepts that are important to understand.",
                "points": ["Overview of the topic", "Importance and relevance", "Scope of this document"]
            },
            {
                "heading": "Key Concepts",
                "content": f"The fundamental concepts of {topic} are essential for a thorough understanding. These concepts form the foundation of all related theories and applications.",
                "points": ["Core principle 1", "Core principle 2", "Core principle 3", "Practical applications"]
            },
            {
                "heading": "Detailed Analysis",
                "content": f"An in-depth analysis of {topic} reveals several important insights. Understanding these details helps in practical application and problem-solving.",
                "points": ["Analysis point 1", "Analysis point 2", "Important findings", "Real world implications"]
            },
            {
                "heading": "Summary",
                "content": f"This section summarizes the key findings and insights about {topic}.",
                "points": ["Key takeaway 1", "Key takeaway 2", "Future scope"]
            }
        ],
        "conclusion": f"In conclusion, {topic} is an important subject that requires careful study and understanding."
    }

print("✅ PDF content generator ready!")

#@title PDF Builder Ready
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
from reportlab.lib.colors import HexColor
from google.colab import files

def build_pdf(content, topic, save_path=None):
    if not save_path:
        save_path = f'/content/{topic[:20].replace(" ", "_")}_MK-AI.pdf'

    theme = get_pdf_theme(topic)

    doc = SimpleDocTemplate(
        save_path,
        pagesize=A4,
        rightMargin=2*cm,
        leftMargin=2*cm,
        topMargin=2.5*cm,
        bottomMargin=2*cm
    )

    # Styles
    styles = getSampleStyleSheet()

    title_style = ParagraphStyle(
        'CustomTitle',
        fontSize=28,
        textColor=HexColor(theme['primary']),
        spaceAfter=8,
        spaceBefore=0,
        fontName='Helvetica-Bold',
        alignment=TA_CENTER
    )

    subtitle_style = ParagraphStyle(
        'CustomSubtitle',
        fontSize=14,
        textColor=HexColor(theme['accent']),
        spaceAfter=6,
        fontName='Helvetica',
        alignment=TA_CENTER
    )

    heading_style = ParagraphStyle(
        'CustomHeading',
        fontSize=16,
        textColor=HexColor(theme['primary']),
        spaceAfter=8,
        spaceBefore=16,
        fontName='Helvetica-Bold',
        leftIndent=0
    )

    body_style = ParagraphStyle(
        'CustomBody',
        fontSize=11,
        textColor=HexColor('#2C2C2C'),
        spaceAfter=8,
        spaceBefore=4,
        fontName='Helvetica',
        alignment=TA_JUSTIFY,
        leading=18
    )

    bullet_style = ParagraphStyle(
        'CustomBullet',
        fontSize=11,
        textColor=HexColor('#333333'),
        spaceAfter=4,
        spaceBefore=2,
        fontName='Helvetica',
        leftIndent=20,
        leading=16
    )

    footer_style = ParagraphStyle(
        'Footer',
        fontSize=9,
        textColor=HexColor(theme['accent']),
        alignment=TA_CENTER,
        fontName='Helvetica'
    )

    story = []

    # Header bar using table
    header_data = [[Paragraph(f'<font color="white"><b>MK-AI Document</b></font>',
                              ParagraphStyle('h', fontSize=11, textColor=white, fontName='Helvetica-Bold', alignment=TA_CENTER))]]
    header_table = Table(header_data, colWidths=[17*cm], rowHeights=[0.7*cm])
    header_table.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['primary'])),
        ('ALIGN', (0,0), (-1,-1), 'CENTER'),
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ('ROWPADDING', (0,0), (-1,-1), 6),
    ]))
    story.append(header_table)
    story.append(Spacer(1, 0.5*cm))

    # Title
    story.append(Paragraph(content.get('title', topic), title_style))
    story.append(Paragraph(content.get('subtitle', ''), subtitle_style))

    # Divider
    story.append(HRFlowable(width="100%", thickness=2, color=HexColor(theme['accent'])))
    story.append(Spacer(1, 0.3*cm))

    # Author + date
    from datetime import datetime
    date_str = datetime.now().strftime("%B %d, %Y")
    meta = f'<font color="{theme["accent"]}">Author: MK-AI &nbsp;&nbsp;|&nbsp;&nbsp; Date: {date_str}</font>'
    story.append(Paragraph(meta, ParagraphStyle('meta', fontSize=10, alignment=TA_CENTER, fontName='Helvetica')))
    story.append(Spacer(1, 0.5*cm))

    # Sections
    for section in content.get('sections', []):
        # Section heading with colored background
        heading_data = [[Paragraph(f'<font color="white"><b>{section["heading"]}</b></font>',
                                   ParagraphStyle('sh', fontSize=13, textColor=white,
                                                 fontName='Helvetica-Bold'))]]
        heading_table = Table(heading_data, colWidths=[17*cm], rowHeights=[0.6*cm])
        heading_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['accent'])),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(heading_table)
        story.append(Spacer(1, 0.2*cm))

        # Content paragraph
        if section.get('content'):
            story.append(Paragraph(section['content'], body_style))

        # Bullet points
        for point in section.get('points', []):
            bullet = f'<font color="{theme["accent"]}">▶</font>  {point}'
            story.append(Paragraph(bullet, bullet_style))

        story.append(Spacer(1, 0.3*cm))

    # Conclusion
    if content.get('conclusion'):
        story.append(HRFlowable(width="100%", thickness=1, color=HexColor(theme['accent'])))
        story.append(Spacer(1, 0.2*cm))
        story.append(Paragraph('<b>Conclusion</b>', heading_style))
        story.append(Paragraph(content['conclusion'], body_style))

    # Footer
    story.append(Spacer(1, 0.5*cm))
    story.append(HRFlowable(width="100%", thickness=1, color=HexColor(theme['primary'])))
    story.append(Paragraph(f'Generated by MK-AI | Made by Mushab Khan | {date_str}', footer_style))

    doc.build(story)
    print(f"✅ PDF ready: {save_path}")
    return save_path

print("✅ PDF builder ready!")

#@title PDF Agent
def pdf_agent(command):
    print(f"📄 PDF Agent: {command}\n")

    extract_prompt = f"""<|system|>
Extract topic and document type from command. Reply in JSON only.
{{"topic": "document topic", "type": "document or report or notes or letter"}}
<|end|>
<|user|>
{command}
<|end|>
<|assistant|>
"""

    output = llm(extract_prompt, max_tokens=100, temperature=0.3)

    try:
        json_match = re.search(r'\{.*?\}', output['choices'][0]['text'], re.DOTALL)
        details = json.loads(json_match.group())
        topic = details.get('topic', command)
        doc_type = details.get('type', 'document')
    except:
        topic = command
        doc_type = 'document'

    print(f"📌 Topic: {topic}")
    print(f"📋 Type: {doc_type}")

    content = generate_pdf_content(topic, doc_type)
    save_path = f'/content/{topic[:20].replace(" ", "_")}_MK-AI.pdf'
    build_pdf(content, topic, save_path)

    print(f"\n🎉 PDF ready hai bhai!")
    files.download(save_path)
    return save_path

print("✅ PDF Agent ready!")

