#@title Image Reader Ready
import pytesseract
from PIL import Image
import io, os, re

def read_image_text(image_path):
    """Image se text nikalo"""
    print(f"🔍 Image padh raha hun...")

    img = Image.open(image_path)

    # Image enhance karo better OCR ke liye
    img = img.convert('RGB')

    # English + Hindi dono try karo
    try:
        text = pytesseract.image_to_string(img, lang='eng+hin')
    except:
        text = pytesseract.image_to_string(img, lang='eng')

    text = text.strip()

    if len(text) < 10:
        print("⚠️ Text bahut kam mila — image clear nahi hai")
        return None

    print(f"✅ Text mila! ({len(text)} characters)")
    return text

print("✅ Image reader ready!")

#@title Scanner Agent Ready
def scan_and_explain(image_path, question=None):
    """
    Image upload karo — AI padhega aur samjhayega
    question = koi specific sawaal pucho image ke baare mein
    """

    print(f"📸 Document scan ho raha hai...")

    # Image se text nikalo
    text = read_image_text(image_path)

    if not text:
        print("❌ Image se text nahi nikla — clearer image try karo")
        return

    print(f"\n📝 Raw text:\n{text[:500]}...\n")

    # AI se samjhwao
    if question:
        prompt_text = f"Answer this question based on the document: {question}"
    else:
        prompt_text = "Summarize and explain this document content clearly."

    scan_prompt = f"""<|system|>
You are MK-AI document scanner.
Analyze the scanned document text and provide clear explanation.
Reply in English only.
Be helpful and detailed.
<|end|>
<|user|>
Scanned document text:
{text[:2000]}

Task: {prompt_text}
<|end|>
<|assistant|>
"""

    output = llm(scan_prompt, max_tokens=500, temperature=0.5)
    answer = output['choices'][0]['text'].strip()

    print(f"🤖 MK-AI Scanner:\n{answer}\n")

    # Voice mein bhi bolo
    text_to_voice(answer)

    return answer

print("✅ Scanner agent ready!")

