#@title Translator Ready
def translate_text(text, target='hinglish'):

    if target == 'hinglish':
        instruction = """Convert COMPLETE English text to Hinglish.
Hinglish = Hindi words in English script + English words mixed.
Example: "Machine learning is a branch of AI" → "Bhai Machine learning basically AI ki ek branch hai jo computers ko khud seekhne deti hai!"
Write the COMPLETE translation. Do not cut short."""
    else:
        instruction = """Convert COMPLETE Hinglish text to proper English.
Example: "Bhai ye bahut accha hai yaar" → "This is really very good."""

    prompt = f"""<|system|>
You are a translator. {instruction}
IMPORTANT: Translate the COMPLETE text. Do not stop in between.
Reply with ONLY the translated text.
<|end|>
<|user|>
Translate completely: {text}
<|end|>
<|assistant|>
"""

    output = llm(prompt, max_tokens=600, temperature=0.5)
    result = output['choices'][0]['text'].strip()

    import re
    result = re.sub(r'[\u0900-\u097F]+', '', result)
    result = ' '.join(result.split())

    return result

def translator_agent(command):
    print(f"🌐 Translator: {command}\n")

    command_lower = command.lower()

    if any(w in command_lower for w in ['hinglish mein', 'hinglish mai', 'hinglish kar', 'to hinglish', 'hinglish karo']):
        target = 'hinglish'
    elif any(w in command_lower for w in ['english mein', 'english mai', 'english kar', 'to english', 'english karo']):
        target = 'english'
    else:
        has_hinglish = any(w in command_lower for w in ['bhai', 'yaar', 'hai', 'nahi', 'karo', 'yrr'])
        target = 'english' if has_hinglish else 'hinglish'

    # Text extract karo
    separators = [':', 'karo', 'kar', 'kardo']
    text = command
    for sep in separators:
        if sep in command_lower:
            parts = command.split(sep, 1)
            if len(parts) > 1 and len(parts[1].strip()) > 3:
                text = parts[1].strip()
                break

    print(f"🎯 Target: {target}")
    print(f"📝 Text: {text}\n")

    result = translate_text(text, target)
    print(f"✅ Translated: {result}\n")

    try:
        text_to_voice(result)
    except:
        pass

    return result

print("✅ Translator ready!")

#@title PDF hinglish Answer Ready
def ask_pdf_hinglish(question, collection_name="mk_ai_docs", top_k=4):
    """PDF ka jawab — English mein nikalo phir Hinglish mein do"""

    try:
        collection = chroma_client.get_collection(collection_name)
    except:
        print("❌ Pehle PDF upload karo!")
        return

    question_embedding = embedder.encode(question).tolist()
    results = collection.query(
        query_embeddings=[question_embedding],
        n_results=top_k
    )

    relevant_chunks = "\n\n".join(results['documents'][0])
    relevant_chunks = relevant_chunks[:1500]

    # Pehle English mein answer lo
    rag_prompt = f"""<|system|>
You are MK-AI. Answer from document only. Reply in English. Be detailed and clear.
<|end|>
<|user|>
Document:
{relevant_chunks}

Question: {question}
<|end|>
<|assistant|>
"""

    output = llm(rag_prompt, max_tokens=400, temperature=0.3)
    english_answer = output['choices'][0]['text'].strip()

    # User Hinglish mein puch raha hai toh translate karo
    has_hinglish = any(w in question.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'toh', 'aur',
        'batao', 'btao', 'samjhao', 'yrr', 'mai', 'mujhe'
    ])

    if has_hinglish:
        print("🔄 Hinglish mein translate ho raha hai...")
        final_answer = translate_text(english_answer, 'hinglish')
    else:
        final_answer = english_answer

    print(f"\n🤖 MK-AI: {final_answer}\n")
    text_to_voice(final_answer)

    return final_answer

