#@title Memory ydd kar liya
import json, os
from datetime import datetime

MEMORY_FILE = '/content/drive/MyDrive/MK-AI-Models/mk_ai_memory.json'

def load_memory():
    if os.path.exists(MEMORY_FILE):
        with open(MEMORY_FILE, 'r') as f:
            return json.load(f)
    return {
        "user_profile": {},
        "preferences": {},
        "mindset": {},
        "conversation_patterns": [],
        "important_facts": {},
        "onboarding_done": False
    }

def save_memory(memory):
    with open(MEMORY_FILE, 'w') as f:
        json.dump(memory, f, indent=2)

def remember(key, value, category="important_facts"):
    memory = load_memory()
    memory[category][key] = {
        "value": value,
        "saved_at": datetime.now().strftime("%Y-%m-%d %H:%M")
    }
    save_memory(memory)
    print(f"✅ Yaad kar liya: {key} = {value}")

#@title Smart Memory Engine
def recall(key, category="important_facts"):
    memory = load_memory()
    data = memory.get(category, {}).get(key)
    if data:
        return data['value']
    return None

def get_full_memory_context():
    memory = load_memory()
    context = "\nUSER KE BAARE MEIN:\n"

    if memory.get('user_profile'):
        for k, v in memory['user_profile'].items():
            context += f"- {k}: {v['value']}\n"

    if memory.get('preferences'):
        context += "\nUSER KI PASAND:\n"
        for k, v in memory['preferences'].items():
            context += f"- {k}: {v['value']}\n"

    if memory.get('mindset'):
        context += "\nUSER KA MINDSET:\n"
        for k, v in memory['mindset'].items():
            context += f"- {k}: {v['value']}\n"

    return context

def smart_extract_facts(user_message, ai_response):
    """Conversation se automatically facts extract karo"""
    memory = load_memory()
    msg = user_message.lower()

    # Naam
    if any(w in msg for w in ['mera naam', 'my name is', 'main hun', 'i am']):
        words = user_message.split()
        for i, word in enumerate(words):
            if word.lower() in ['naam', 'name', 'hun', 'am', 'is'] and i+1 < len(words):
                remember(key='naam', value=words[i+1], category='user_profile')
                break

    # Age
    if any(w in msg for w in ['meri age', 'meri umar', 'i am', 'years old', 'saal ka']):
        import re
        nums = re.findall(r'\b\d{1,2}\b', user_message)
        if nums:
            remember(key='age', value=nums[0], category='user_profile')

    # City
    if any(w in msg for w in ['main rehta', 'i live', 'i am from', 'mera city', 'se hun']):
        remember(key='location', value=user_message, category='user_profile')

    # Profession
    if any(w in msg for w in ['student', 'engineer', 'doctor', 'teacher', 'padh raha', 'kaam karta']):
        remember(key='profession', value=user_message, category='user_profile')

    # Thinking style
    if any(w in msg for w in ['mujhe pasand', 'i like', 'i prefer', 'mujhe accha lagta']):
        remember(key='preference', value=user_message, category='preferences')

print("✅ Smart memory engine ready!")

#@title Onboarding System Ready
def run_onboarding():
    memory = load_memory()

    if memory.get('onboarding_done'):
        name = recall('naam', 'user_profile')
        if name:
            print(f"✅ Welcome back {name}! MK-AI ready hai!")
        else:
            print("✅ Welcome back! MK-AI ready hai!")
        return

    print("\n" + "="*50)
    print("🤖 MK-AI: Hey! Main MK-AI hun — Mushab Khan ka banaya hua!")
    print("="*50 + "\n")
    text_to_voice("Hey! Main MK-AI hun!")

    # Seedha values set karo — input() nahi
    print("📝 Apna profile set karo:\n")

    naam = input("❓ Tera naam kya hai? → ")
    if naam.strip():
        remember('naam', naam.strip(), 'user_profile')

    kaam = input("❓ Tu kya karta hai? (Student/Job/Business) → ")
    if kaam.strip():
        remember('profession', kaam.strip(), 'user_profile')
        remember('work_style', kaam.strip(), 'mindset')

    style = input("❓ Kaise seekhta hai? A=Seedha karta hun / B=Pehle plan → ")
    if style.strip().upper() == 'A':
        remember('thinking_style', 'doer', 'mindset')
        remember('response_preference', 'short and direct', 'preferences')
    else:
        remember('thinking_style', 'planner', 'mindset')
        remember('response_preference', 'detailed answers', 'preferences')

    lang = input("❓ Language? A=Hinglish / B=English → ")
    if lang.strip().upper() == 'A':
        remember('language', 'hinglish', 'preferences')
    else:
        remember('language', 'english', 'preferences')

    use = input("❓ Use case? A=Padhai / B=Kaam / C=General → ")
    use_map = {
        'A': 'student help',
        'B': 'professional work',
        'C': 'general assistant'
    }
    remember('main_use', use_map.get(use.strip().upper(), 'general'), 'preferences')

    memory = load_memory()
    memory['onboarding_done'] = True
    save_memory(memory)

    naam = recall('naam', 'user_profile') or 'Bhai'
    final_msg = f"Perfect {naam}! Ab shuru karte hain!"
    print(f"\n🤖 MK-AI: {final_msg}")
    text_to_voice(final_msg)
    print("="*50 + "\n")

print("✅ Onboarding fixed!")

