    smart_extract_facts(user_message, "")

    # Language preference memory se lo
    memory = load_memory()
    lang_pref = memory.get('preferences', {}).get('language', {})
    lang_pref_val = lang_pref.get('value', 'hinglish') if lang_pref else 'hinglish'

    has_hinglish = any(w in user_message.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'nahi', 'haan', 'mera',
        'tera', 'karo', 'toh', 'aur', 'bata', 'ho', 'mai',
        'mujhe', 'samajh', 'yrr', 'accha', 'theek', 'chal',
        'kr', 'de', 'le', 'ja', 'aa', 'tha', 'thi', 'hun'
    ])
    hindi_chars = any('\u0900' <= c <= '\u097F' for c in user_message)

    # Translator check
    translate_keywords = ['translate', 'hinglish mein', 'hinglish mai',
                         'english mein', 'english mai', 'kardo', 'kar do']
    is_translate = any(w in user_message.lower() for w in translate_keywords)

    if is_translate:
        response = translator_agent(user_message)
        conversation_history.append({"role": "user", "content": user_message})
        conversation_history.append({"role": "assistant", "content": response})
        return response

    if hindi_chars:
        lang_rule = "REPLY IN HINDI SCRIPT ONLY."
    elif has_hinglish or lang_pref_val == 'hinglish':
        lang_rule = "REPLY IN ENGLISH — will be auto-translated to Hinglish."
    else:
        lang_rule = "REPLY IN ENGLISH ONLY."

    if is_complex_question(user_message) and len(user_message) > 30:
        print("🧠 Deep thinking mode...")
        response = think_deeply(user_message)
    else:
        full_system = (SYSTEM_PROMPT + memory_context +
                      f"\nEMOTION: {emotion}" +
                      f"\nEMOTION RULE: {emotion_instruction}" +
                      f"\nLANGUAGE RULE: {lang_rule}")

        prompt = f"<|system|>\n{full_system}<|end|>\n"

        for msg in conversation_history[-6:]:
            prompt += f"<|{msg['role']}|>\n{msg['content']}<|end|>\n"

        prompt += f"<|user|>\n{user_message}<|end|>\n<|assistant|>\n"

        output = llm(
            prompt,
            max_tokens=600,
            stop=["<|end|>", "<|user|>"],
            temperature=0.75,
            top_p=0.95,
            repeat_penalty=1.1
        )
        response = output['choices'][0]['text'].strip()

    # Auto translate to Hinglish
    if (has_hinglish or lang_pref_val == 'hinglish') and not hindi_chars:
        print("🔄 Hinglish mein translate ho raha hai...")
        response = translate_text(response, 'hinglish')

    conversation_history.append({"role": "user", "content": user_message})
    conversation_history.append({"role": "assistant", "content": response})

    print(f"🎭 Emotion: {emotion}")
    print(f"🤖 MK-AI: {response}\n")

    if speak:
        text_to_voice(response)

    return response

