def chat_online(user_message, speak=False):
    global conversation_history

    emotion = detect_emotion(user_message)
    emotion_instruction = get_emotion_instruction(emotion)
    memory_context = get_full_memory_context()
    smart_extract_facts(user_message, "")

    has_hinglish = any(w in user_message.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'nahi', 'haan', 'mera',
        'tera', 'karo', 'toh', 'aur', 'bata', 'ho', 'mai',
        'mujhe', 'samajh', 'yrr', 'accha', 'theek', 'chal',
        'kr', 'de', 'le', 'ja', 'aa', 'tha', 'thi', 'hun'
    ])
    hindi_chars = any('\u0900' <= c <= '\u097F' for c in user_message)

    # Voice command detect karo
    voice_keywords = ['voice', 'awaaz', 'bol', 'bolo', 'speak', 'sunao']
    wants_voice = any(w in user_message.lower() for w in voice_keywords)

    # Language detect
    wants_english = any(w in user_message.lower() for w in [
        'in english', 'english mein', 'english mai', 'reply in english'
    ])
    wants_hinglish = any(w in user_message.lower() for w in [
        'hinglish mein', 'hinglish mai', 'hinglish mein bata'
    ])

    if wants_english:
        lang_rule = "REPLY IN ENGLISH ONLY. Do not use any Hindi words."
    elif wants_hinglish or has_hinglish:
        lang_rule = """REPLY IN HINGLISH ONLY.
Hinglish = Roman script mein Hindi+English mix.
Bilkul WhatsApp jaisi language.
Example: 'Bhai main MK-AI hun, main tujhe bahut saari cheezein mein help kar sakta hun!'
NEVER use Devanagari script.
NEVER write full Hindi or full English."""
    else:
        lang_rule = "REPLY IN ENGLISH ONLY."

    system = f"""{SYSTEM_PROMPT}
{memory_context}
EMOTION: {emotion}
EMOTION RULE: {emotion_instruction}
LANGUAGE RULE: {lang_rule}
IMPORTANT: {lang_rule}"""

    messages = [{"role": "system", "content": system}]

    for msg in conversation_history[-6:]:
        messages.append({"role": msg['role'], "content": msg['content']})

    messages.append({"role": "user", "content": user_message})

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=messages,
        max_tokens=1024,
        temperature=0.7
    )

    reply = response.choices[0].message.content.strip()

    # Hindi script remove karo
    import re
    if has_hinglish and not wants_english:
        reply = re.sub(r'[\u0900-\u097F]+', '', reply)
        reply = ' '.join(reply.split())

    conversation_history.append({"role": "user", "content": user_message})
    conversation_history.append({"role": "assistant", "content": reply})

    print(f"🎭 Emotion: {emotion}")
    print(f"⚡ Model: Llama 3.3 70B")
    print(f"🤖 MK-AI: {reply}\n")

    # Voice sirf tab aaye jab user ne manga
    if wants_voice or speak:
        text_to_voice(reply)

    return reply

