#@title Smart Query Rewriter
def rewrite_query(user_query):
    """User query ko better search query mein convert karo"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": """Convert user query to an optimal Google search query.
Rules:
- Make it specific and searchable
- Add current year if time-sensitive
- Remove casual words like 'bhai', 'yaar'
- Return ONLY the search query, nothing else
Examples:
"bhai aaj news kya h" → "latest India news today 2025"
"iphone kitne ka h" → "iPhone 16 price India 2025"
"ML kya hota h" → "what is machine learning explained"
"cricket score kya h" → "India cricket live score today 2025"
"""},
            {"role": "user", "content": user_query}
        ],
        max_tokens=50,
        temperature=0.3
    )

    optimized = response.choices[0].message.content.strip()
    print(f"🔄 Query rewritten: '{user_query}' → '{optimized}'")
    return optimized

