#@title Source Ranking + Web Fetch
from ddgs import DDGS
import requests
from bs4 import BeautifulSoup
import re, warnings
warnings.filterwarnings('ignore')

TRUSTED_SOURCES = [
    'wikipedia.org', 'bbc.com', 'reuters.com', 'ndtv.com',
    'timesofindia.com', 'hindustantimes.com', 'thehindu.com',
    'weather.com', 'accuweather.com', 'imd.gov.in',
    'espncricinfo.com', 'cricbuzz.com', 'bcci.tv',
    'moneycontrol.com', 'nseindia.com', 'techcrunch.com'
]

SPAM_SOURCES = ['pinterest.com', 'buzzfeed.com']

def rank_results(results):
    ranked = []
    for r in results:
        url = r.get('url', '')
        score = 0
        for trusted in TRUSTED_SOURCES:
            if trusted in url:
                score += 10
                break
        for spam in SPAM_SOURCES:
            if spam in url:
                score -= 5
        body = r.get('body', '')
        if len(body) > 200: score += 3
        if len(body) > 500: score += 2
        r['score'] = score
        ranked.append(r)
    return sorted(ranked, key=lambda x: x['score'], reverse=True)

def web_search(query, max_results=6):
    results = []
    try:
        with DDGS() as ddgs:
            for r in ddgs.text(query, max_results=max_results):
                results.append({
                    'title': r.get('title', ''),
                    'body': r.get('body', ''),
                    'url': r.get('href', '')
                })
    except Exception as e:
        print(f"⚠️ Search error: {e}")
    return rank_results(results)

def fetch_page_content(url, max_chars=2000):
    try:
        headers = {'User-Agent': 'Mozilla/5.0'}
        response = requests.get(url, timeout=5, headers=headers)
        soup = BeautifulSoup(response.text, 'html.parser')
        for tag in soup(['script', 'style', 'nav', 'footer']):
            tag.decompose()
        text = soup.get_text(separator=' ', strip=True)
        text = re.sub(r'\s+', ' ', text)
        return text[:max_chars]
    except:
        return ""

print("✅ Source ranking ready!")

#@title Real Time Data
import warnings
warnings.filterwarnings('ignore')

def get_weather(city="Delhi"):
    try:
        # India specific query
        results = web_search(
            f"weather {city} India today temperature celsius 2025 forecast",
            max_results=3
        )
        if results:
            return results[0]['body'][:500]
    except:
        pass
    return None

def get_cricket_score():
    try:
        results = web_search(
            "India cricket live score today 2025 cricbuzz",
            max_results=2
        )
        if results:
            return results[0]['body'][:300]
    except:
        pass
    return None

def get_stock_price(company):
    try:
        results = web_search(
            f"{company} stock price today NSE BSE India 2025 moneycontrol",
            max_results=2
        )
        if results:
            return results[0]['body'][:300]
    except:
        pass
    return None

def detect_realtime_query(query):
    q = query.lower()
    if any(w in q for w in ['weather', 'mausam', 'temperature', 'barish', 'garmi', 'sardi']):
        city = "Delhi"
        cities = ['mumbai', 'delhi', 'bangalore', 'bengaluru', 'chennai',
                 'kolkata', 'hyderabad', 'pune', 'jaipur', 'gurugram',
                 'noida', 'lucknow', 'ahmedabad', 'surat']
        for c in cities:
            if c in q:
                city = c.capitalize()
        return 'weather', city
    elif any(w in q for w in ['cricket', 'score', 'ipl', 'test match', 'odi', 't20']):
        return 'cricket', None
    elif any(w in q for w in ['stock', 'share price', 'nse', 'bse', 'sensex', 'nifty']):
        words = query.split()
        company = words[0] if words else "Reliance"
        return 'stock', company
    return None, None

