#@title YouTube Search
from youtubesearchpython import VideosSearch

def youtube_search(query, max_results=3):
    """YouTube pe videos dhundo"""
    try:
        search = VideosSearch(query, limit=max_results)
        results = search.result()['result']

        videos = []
        for v in results:
            videos.append({
                'title': v.get('title', ''),
                'url': v.get('link', ''),
                'duration': v.get('duration', ''),
                'channel': v.get('channel', {}).get('name', ''),
                'views': v.get('viewCount', {}).get('short', '')
            })

        return videos
    except Exception as e:
        print(f"⚠️ YouTube search error: {e}")
        return []

def detect_youtube_query(query):
    """YouTube search chahiye ya nahi"""
    q = query.lower()
    return any(w in q for w in [
        'video', 'youtube', 'tutorial', 'watch', 'dekho',
        'dikhao', 'how to video', 'seekhna', 'course'
    ])

print("✅ YouTube search ready!")

#@title Fact Checking
def fact_check(query, sources_content):
    """Multiple sources compare karke fact check karo"""

    if len(sources_content) < 2:
        return "confident", "Only one source mila"

    check_prompt = f"""Compare these sources and determine if they agree or disagree.
Source 1: {sources_content[0][:500]}
Source 2: {sources_content[1][:500]}

Reply in JSON only:
{{"agreement": "agree or disagree", "confidence": "high or medium or low", "reason": "brief explanation"}}"""

    try:
        response = groq_client.chat.completions.create(
            model="llama-3.3-70b-versatile",
            messages=[{"role": "user", "content": check_prompt}],
            max_tokens=100,
            temperature=0.1
        )

        import json
        result = json.loads(response.choices[0].message.content)
        return result.get('confidence', 'medium'), result.get('reason', '')
    except:
        return "medium", ""

print("✅ Fact checker ready!")

