# Search history for follow-up questions
search_history = []

def search_agent(user_query, speak=True):
    """
    Full powered search agent —
    Smart query + Source ranking + Fact check + YouTube
    """
    print(f"\n🔎 Search Agent: {user_query}\n")

    has_hinglish = any(w in user_query.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'batao', 'btao',
        'karo', 'toh', 'aur', 'mai', 'mujhe', 'yrr', 'dikhao'
    ])

    lang_rule = "Reply in Hinglish" if has_hinglish else "Reply in English"

    # Follow up check
    follow_up_words = ['aur batao', 'more', 'details', 'explain more', 'aur', 'details do']
    is_follow_up = any(w in user_query.lower() for w in follow_up_words)

    if is_follow_up and search_history:
        last_query = search_history[-1]
        user_query = f"{last_query} {user_query}"
        print(f"🔄 Follow up detected — extended query: {user_query}")

    # Real time data check
    rt_type, rt_param = detect_realtime_query(user_query)

    if rt_type == 'weather':
        print(f"🌤️ Weather data fetch ho raha hai: {rt_param}")
        rt_data = get_weather(rt_param)
    elif rt_type == 'cricket':
        print("🏏 Cricket score fetch ho raha hai...")
        rt_data = get_cricket_score()
    elif rt_type == 'stock':
        print(f"📈 Stock price fetch ho raha hai: {rt_param}")
        rt_data = get_stock_price(rt_param)
    else:
        rt_data = None

    # YouTube check
    if detect_youtube_query(user_query):
        print("📺 YouTube videos dhundh raha hun...")
        videos = youtube_search(user_query)
        if videos:
            print("\n📺 YouTube Results:")
            for v in videos:
                print(f"  ▶ {v['title']}")
                print(f"    Channel: {v['channel']} | Duration: {v['duration']}")
                print(f"    {v['url']}\n")

    # Query rewrite
    optimized_query = rewrite_query(user_query)

    # Web search
    results = web_search(optimized_query, max_results=6)

    if not results:
        print("⚠️ No results — Groq se directly answer le raha hun...")
        response = groq_client.chat.completions.create(
            model="llama-3.3-70b-versatile",
            messages=[
                {"role": "system", "content": f"You are MK-AI. {lang_rule}"},
                {"role": "user", "content": user_query}
            ],
            max_tokens=1024,
            temperature=0.5
        )
        answer = response.choices[0].message.content.strip()
        print(f"🤖 MK-AI: {answer}\n")
        if speak:
            text_to_voice(answer[:500])
        return answer

    # Content combine karo
    sources_content = []
    combined = ""

    for i, r in enumerate(results[:4]):
        content = r['body']
        sources_content.append(content)
        combined += f"\nSource {i+1} ({r['title']}):\n{content}\n"

    # Real time data add karo
    if rt_data:
        combined += f"\nReal Time Data:\n{rt_data}\n"

    # Fact check
    confidence, reason = fact_check(user_query, sources_content)

    # Final answer banwao
    search_prompt = f"""You are MK-AI — world's best search assistant.

User Query: {user_query}
Confidence Level: {confidence}

Web Content:
{combined[:3000]}

Instructions:
1. {lang_rule}
2. Give the BEST and most accurate answer
3. Synthesize from multiple sources
4. If confidence is low, mention "Sources mein thoda difference hai"
5. Be clear, structured and helpful
6. Mention key facts with context"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": search_prompt},
            {"role": "user", "content": user_query}
        ],
        max_tokens=1024,
        temperature=0.4
    )

    answer = response.choices[0].message.content.strip()

    # Confidence indicator
    confidence_emoji = "✅" if confidence == "high" else "⚠️" if confidence == "low" else "🟡"

    print(f"🤖 MK-AI Search Result:\n{answer}\n")
    print(f"{confidence_emoji} Confidence: {confidence}")

    # Sources dikhao
    print("\n📚 Top Sources:")
    for i, r in enumerate(results[:3]):
        print(f"  {i+1}. {r['title']}")
        print(f"     {r['url']}")

    # History mein save karo
    search_history.append(user_query)
    if len(search_history) > 5:
        search_history.pop(0)

    if speak:
        text_to_voice(answer[:500])

    return answer

print("✅ Master Search Agent ready!")

