def get_ultra_theme(topic):
    topic_lower = topic.lower()
    for keyword, theme_name in TOPIC_ULTRA_THEMES.items():
        if keyword in topic_lower:
            return ULTRA_PALETTES[theme_name], theme_name
    theme_name = random.choice(list(ULTRA_PALETTES.keys()))
    return ULTRA_PALETTES[theme_name], theme_name


