# HELPER: Add Glowing Orbs (Signature Look)
# ══════════════════════════════════════════
def add_orbs(slide, theme, count=4):
    """Decorative glowing orbs — pitch deck signature look"""
    orb_configs = [
        (0.0, 0.0, 2.5, theme['accent'], 15),
        (7.5, 2.5, 2.0, theme['accent2'], 12),
        (6.5, -0.3, 1.1, theme['accent3'], 18),
        (3.5, 3.8, 1.5, theme['accent'], 10),
        (9.5, 0.2, 0.8, theme['accent2'], 20),
        (1.0, 4.5, 1.2, theme['accent3'], 14),
    ]
    for i, (x, y, size, color, alpha) in enumerate(orb_configs[:count]):
        orb = slide.shapes.add_shape(
            9,  # Oval
            Inches(x - size/2), Inches(y - size/2),
            Inches(size), Inches(size)
        )
        orb.fill.solid()
        orb.fill.fore_color.rgb = color
        orb.fill.fore_color.theme_color = None
        # Simulate transparency via opacity trick
        orb.line.fill.background()
        # Make it very subtle
        try:
            from pptx.oxml.ns import qn
            from lxml import etree
            spPr = orb._element.spPr
            solidFill = spPr.find('.//' + qn('a:solidFill'))
            if solidFill is not None:
                srgbClr = solidFill.find(qn('a:srgbClr'))
                if srgbClr is not None:
                    alpha_el = etree.SubElement(srgbClr, qn('a:alpha'))
                    alpha_el.set('val', str(alpha * 1000))
        except:
            pass


# ══════════════════════════════════════════
# HELPER: Grid Lines Background
# ══════════════════════════════════════════
def add_grid(slide, theme):
    """Subtle grid lines in background"""
    try:
        from pptx.oxml.ns import qn
        from lxml import etree
        bg = slide.background
        bgPr = bg._element.find(qn('p:bgPr'))
        if bgPr is None:
            cSld = slide._element.find(qn('p:cSld'))
            bgEl = etree.SubElement(cSld, qn('p:bg'))
            bgPr = etree.SubElement(bgEl, qn('p:bgPr'))
        # Set solid fill
        solidFill = etree.SubElement(bgPr, qn('a:solidFill'))
        srgbClr = etree.SubElement(solidFill, qn('a:srgbClr'))
        r, g, b = theme['bg'].red, theme['bg'].green, theme['bg'].blue
        srgbClr.set('val', f'{r:02X}{g:02X}{b:02X}')
    except:
        bg = slide.background.fill
        bg.solid()
        bg.fore_color.rgb = theme['bg']


# ══════════════════════════════════════════
# HELPER: Gradient Bar
# ══════════════════════════════════════════
def add_gradient_bar(slide, x, y, w, h, color1, color2=None, vertical=False):
    """Add accent bar"""
    bar = slide.shapes.add_shape(1, Inches(x), Inches(y), Inches(w), Inches(h))
    bar.fill.solid()
    bar.fill.fore_color.rgb = color1
    bar.line.fill.background()
    return bar


# ══════════════════════════════════════════
# HELPER: Modern Card
# ══════════════════════════════════════════
def add_card(slide, x, y, w, h, theme, has_border=True):
    """Glassmorphism-style dark card"""
    card = slide.shapes.add_shape(
        10,  # Rounded rect
        Inches(x), Inches(y), Inches(w), Inches(h)
    )
    card.fill.solid()
    card.fill.fore_color.rgb = theme['card']
    if has_border:
        card.line.color.rgb = theme['border']
        card.line.width = Pt(0.5)
    else:
        card.line.fill.background()
    return card


# ══════════════════════════════════════════
# HELPER: Add Text
# ══════════════════════════════════════════
def add_text(slide, text, x, y, w, h, font_size=14, bold=False, color=None,
             align=PP_ALIGN.LEFT, italic=False, wrap=True):
    tb = slide.shapes.add_textbox(Inches(x), Inches(y), Inches(w), Inches(h))
    tf = tb.text_frame
    tf.word_wrap = wrap
    p = tf.paragraphs[0]
    p.alignment = align
    run = p.add_run()
    run.text = text
    run.font.size = Pt(font_size)
    run.font.bold = bold
    run.font.italic = italic
    if color:
        run.font.color.rgb = color
    return tb


# ══════════════════════════════════════════
# SLIDE BUILDERS
# ══════════════════════════════════════════

def build_title_slide(prs, content, topic, theme):
    """Slide 1 — Full cinematic title"""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    W, H = 10.0, 5.63

    # BG
    bg = slide.background.fill
    bg.solid()
    bg.fore_color.rgb = theme['bg']

    # Orbs
    add_orbs(slide, theme, 5)

    # Left accent bar
    add_gradient_bar(slide, 0, 0, 0.06, H, theme['accent'])

    # Top micro line
    add_gradient_bar(slide, 0, 0, W, 0.04, theme['accent'])

    # Badge pill
    badge = slide.shapes.add_shape(10, Inches(0.4), Inches(0.25), Inches(2.8), Inches(0.38))
    badge.fill.solid()
    badge.fill.fore_color.rgb = theme['accent']
    try:
        from pptx.oxml.ns import qn
        from lxml import etree
        spPr = badge._element.spPr
        solidFill = spPr.find('.//' + qn('a:solidFill'))
        if solidFill is not None:
            srgbClr = solidFill.find(qn('a:srgbClr'))
            if srgbClr is not None:
                alpha_el = etree.SubElement(srgbClr, qn('a:alpha'))
                alpha_el.set('val', '30000')
    except: pass
    badge.line.color.rgb = theme['accent']
    badge.line.width = Pt(0.8)

    add_text(slide, '✦  AI GENERATED  ·  MK-AI', 0.42, 0.25, 2.8, 0.38,
             font_size=8, bold=True, color=theme['accent'], align=PP_ALIGN.CENTER)

    # Main Title — Big
    title_text = content.get('title', topic).upper()
    add_text(slide, title_text, 0.4, 0.85, 7.5, 2.2,
             font_size=42, bold=True, color=theme['text'], align=PP_ALIGN.LEFT)

    # Divider line
    add_gradient_bar(slide, 0.4, 3.15, 4.0, 0.04, theme['accent'])

    # Subtitle
    sub = content.get('subtitle', f'A comprehensive guide to {topic}')
    add_text(slide, sub, 0.4, 3.3, 7.5, 0.7,
             font_size=14, bold=False, color=theme['text_muted'], align=PP_ALIGN.LEFT)

    # Stats row at bottom
    slide_count = len(content.get('slides', []))
    stats = [('📊', str(slide_count), 'Slides'), ('🤖', 'AI', 'Generated'), ('⚡', 'Groq', 'Powered')]
    for i, (icon, val, label) in enumerate(stats):
        add_card(slide, 0.4 + i * 2.0, 4.2, 1.7, 0.9, theme)
        add_text(slide, f'{icon} {val}', 0.5 + i * 2.0, 4.3, 1.5, 0.35,
                 font_size=13, bold=True, color=theme['accent'], align=PP_ALIGN.CENTER)
        add_text(slide, label, 0.5 + i * 2.0, 4.65, 1.5, 0.28,
                 font_size=9, color=theme['text_muted'], align=PP_ALIGN.CENTER)

    # Right side — decorative number
    add_text(slide, '01', 7.8, 1.5, 2.0, 2.0,
             font_size=100, bold=True, color=theme['accent'], align=PP_ALIGN.RIGHT)

    # MK-AI watermark bottom right
    add_text(slide, 'Made by Mushab Khan  ·  MK-AI', 5.5, 5.25, 4.3, 0.3,
             font_size=8, color=theme['text_muted'], align=PP_ALIGN.RIGHT)


