def build_content_slide(prs, slide_data, slide_idx, theme):
    """Standard content slide — modern card layout"""
    slide = prs.slides.add_slide(prs.slide_layouts[6])
    W, H = 10.0, 5.63

    bg = slide.background.fill
    bg.solid()
    bg.fore_color.rgb = theme['bg']

    add_orbs(slide, theme, 3)

    # Top accent bar
    add_gradient_bar(slide, 0, 0, W, 0.05, theme['accent'])

    # Slide number badge top right
    num_badge = slide.shapes.add_shape(10, Inches(8.9), Inches(0.1), Inches(0.8), Inches(0.45))
    num_badge.fill.solid()
    num_badge.fill.fore_color.rgb = theme['accent']
    num_badge.line.fill.background()
    add_text(slide, str(slide_idx + 1), 8.9, 0.1, 0.8, 0.45,
             font_size=13, bold=True, color=RGBColor(0, 0, 0), align=PP_ALIGN.CENTER)

    # Title background strip
    title_strip = slide.shapes.add_shape(1, Inches(0), Inches(0.05), Inches(W), Inches(0.82))
    title_strip.fill.solid()
    title_strip.fill.fore_color.rgb = theme['card']
    title_strip.line.fill.background()

    # Title text
    title = slide_data.get('title', '')
    add_text(slide, title, 0.3, 0.1, 8.5, 0.72,
             font_size=22, bold=True, color=theme['text'], align=PP_ALIGN.LEFT)

    # Left accent strip under title
    add_gradient_bar(slide, 0, 0.87, 0.06, H - 0.87, theme['accent'])

    # Points
    points = slide_data.get('points', [])
    icons = ['▶', '◆', '●', '★', '✦', '▸', '◉', '❯']

    if len(points) >= 4:
        # Two column layout
        mid = math.ceil(len(points) / 2)
        left_pts = points[:mid]
        right_pts = points[mid:]

        for col_idx, col_pts in enumerate([left_pts, right_pts]):
            cx = 0.2 + col_idx * 4.95
            cw = 4.7

            # Card background
            add_card(slide, cx, 1.0, cw, 4.4, theme)

            # Points in card
            y_start = 1.2
            for j, pt in enumerate(col_pts[:5]):
                icon = icons[j % len(icons)]
                # Icon accent
                icon_shape = slide.shapes.add_shape(
                    10, Inches(cx + 0.12), Inches(y_start + j * 0.72),
                    Inches(0.3), Inches(0.3)
                )
                icon_shape.fill.solid()
                icon_shape.fill.fore_color.rgb = theme['accent']
                try:
                    from pptx.oxml.ns import qn
                    from lxml import etree
                    spPr = icon_shape._element.spPr
                    solidFill = spPr.find('.//' + qn('a:solidFill'))
                    if solidFill is not None:
                        srgbClr = solidFill.find(qn('a:srgbClr'))
                        if srgbClr is not None:
                            alpha_el = etree.SubElement(srgbClr, qn('a:alpha'))
                            alpha_el.set('val', '25000')
                except: pass
                icon_shape.line.fill.background()

                add_text(slide, icon, cx + 0.13, y_start + j * 0.72, 0.28, 0.3,
                         font_size=9, bold=True, color=theme['accent'], align=PP_ALIGN.CENTER)
                add_text(slide, pt, cx + 0.5, y_start + j * 0.72, cw - 0.6, 0.7,
                         font_size=11, color=theme['text'], wrap=True)
    else:
        # Single column — bigger cards
        add_card(slide, 0.2, 1.0, 9.6, 4.4, theme)
        y_start = 1.2
        for j, pt in enumerate(points[:6]):
            icon = icons[j % len(icons)]
            icon_shape = slide.shapes.add_shape(
                10, Inches(0.35), Inches(y_start + j * 0.6),
                Inches(0.28), Inches(0.28)
            )
            icon_shape.fill.solid()
            icon_shape.fill.fore_color.rgb = theme['accent']
            try:
                from pptx.oxml.ns import qn
                from lxml import etree
                spPr = icon_shape._element.spPr
                solidFill = spPr.find('.//' + qn('a:solidFill'))
                if solidFill is not None:
                    srgbClr = solidFill.find(qn('a:srgbClr'))
                    if srgbClr is not None:
                        alpha_el = etree.SubElement(srgbClr, qn('a:alpha'))
                        alpha_el.set('val', '25000')
            except: pass
            icon_shape.line.fill.background()

            add_text(slide, icon, 0.36, y_start + j * 0.6, 0.26, 0.28,
                     font_size=9, bold=True, color=theme['accent'], align=PP_ALIGN.CENTER)
            add_text(slide, pt, 0.7, y_start + j * 0.6, 9.1, 0.58,
                     font_size=13, color=theme['text'], wrap=True)

    # Footer
    add_gradient_bar(slide, 0, 5.4, W, 0.04, theme['accent'])
    add_text(slide, f'MK-AI  ·  {topic[:30]}  ·  {theme_name}',
             0.2, 5.44, 9.6, 0.2, font_size=7, color=theme['text_muted'], align=PP_ALIGN.CENTER)


