TOPIC_THEMES = {
    'science': 'Midnight Blue',
    'physics': 'Arctic',
    'chemistry': 'Neon',
    'biology': 'Emerald',
    'space': 'Galaxy',
    'tech': 'Slate',
    'ai': 'Royal Purple',
    'computer': 'Midnight Blue',
    'coding': 'Neon',
    'business': 'Golden',
    'marketing': 'Coral',
    'finance': 'Emerald',
    'startup': 'Sunset',
    'history': 'Vintage',
    'war': 'Crimson',
    'health': 'Mint',
    'medical': 'Ocean',
    'nature': 'Forest',
    'environment': 'Forest',
    'climate': 'Ocean',
    'music': 'Magenta',
    'art': 'Rose Gold',
    'sports': 'Crimson',
    'cricket': 'Emerald',
    'education': 'Midnight Blue',
    'psychology': 'Royal Purple',
    'economics': 'Copper',
}

def get_online_theme(topic):
    topic_lower = topic.lower()

    # Topic match karo
    for keyword, theme_name in TOPIC_THEMES.items():
        if keyword in topic_lower:
            return PALETTES[theme_name], theme_name

    # Random premium theme
    theme_name = random.choice(list(PALETTES.keys()))
    return PALETTES[theme_name], theme_name

def generate_theme_variations(base_theme):
    """1000+ variations for variety"""
    variations = []
    base_accent = base_theme['accent']

    for i in range(10):
        r = min(255, base_accent.red + random.randint(-30, 30))
        g = min(255, base_accent.green + random.randint(-30, 30))
        b = min(255, base_accent.blue + random.randint(-30, 30))
        variations.append(RGBColor(max(0,r), max(0,g), max(0,b)))

    return variations

