#@title Image Generator (No API needed)
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
import numpy as np
import io, random

def get_rgb_hex(color):
    return f"#{color.red:02x}{color.green:02x}{color.blue:02x}"

def fetch_image(query, width=800, height=500):
    return fetch_fallback_image(query, {
        'accent': RGBColor(0,150,255),
        'bg': RGBColor(10,10,40),
        'secondary': RGBColor(0,80,180)
    })

def fetch_fallback_image(topic, theme):
    fig, ax = plt.subplots(figsize=(13, 6))

    try:
        accent = get_rgb_hex(theme['accent'])
        bg = get_rgb_hex(theme['bg'])
    except:
        accent = '#0096FF'
        bg = '#0A0A28'

    x = np.linspace(0, 10, 300)
    y = np.linspace(0, 6, 300)
    X, Y = np.meshgrid(x, y)
    Z = np.sin(X/2) * np.cos(Y/2) + np.sin(X/3 + Y/3)

    ax.contourf(X, Y, Z, levels=20, cmap='plasma', alpha=0.8)

    for _ in range(5):
        cx = random.uniform(1, 9)
        cy = random.uniform(1, 5)
        r = random.uniform(0.3, 1.2)
        circle = plt.Circle((cx, cy), r, color=accent, alpha=0.15)
        ax.add_patch(circle)

    ax.text(5, 3.5, topic[:25],
            ha='center', va='center',
            fontsize=32, fontweight='bold',
            color='white', alpha=0.9)

    ax.text(5, 2.2, "MK-AI Presentation",
            ha='center', va='center',
            fontsize=14, color=accent, alpha=0.7)

    ax.set_xlim(0, 10)
    ax.set_ylim(0, 6)
    ax.axis('off')

    buf = io.BytesIO()
    plt.savefig(buf, format='png',
                bbox_inches='tight',
                facecolor=bg, dpi=150)
    buf.seek(0)
    plt.close()
    return buf

