#@title Premium PPT Builder
from pptx import Presentation
from pptx.util import Inches, Pt
from pptx.dml.color import RGBColor
from pptx.enum.text import PP_ALIGN
import random

def get_hex(color):
    return f"#{color.red:02x}{color.green:02x}{color.blue:02x}"

def build_premium_ppt(content, topic, theme, theme_name, save_path=None):
    if not save_path:
        save_path = f'/content/{topic[:20].replace(" ", "_")}_Premium_MK-AI.pptx'

    prs = Presentation()
    prs.slide_width = Inches(13.33)
    prs.slide_height = Inches(7.5)

    slides_data = content.get('slides', [])

    for slide_idx, slide_data in enumerate(slides_data):
        slide = prs.slides.add_slide(prs.slide_layouts[6])
        stype = slide_data.get('type', 'content')

        # Background
        bg = slide.background.fill
        bg.solid()
        bg.fore_color.rgb = theme['bg']

        # Decorative dots
        for _ in range(6):
            x = random.uniform(0, 12)
            y = random.uniform(0, 7)
            star = slide.shapes.add_shape(1,
                Inches(x), Inches(y),
                Inches(0.04), Inches(0.04))
            star.fill.solid()
            star.fill.fore_color.rgb = theme['accent']
            star.line.fill.background()

        if stype == 'title':
            left_bar = slide.shapes.add_shape(1,
                Inches(0), Inches(0),
                Inches(0.3), Inches(7.5))
            left_bar.fill.solid()
            left_bar.fill.fore_color.rgb = theme['accent']
            left_bar.line.fill.background()

            right_bar = slide.shapes.add_shape(1,
                Inches(13.0), Inches(0),
                Inches(0.33), Inches(7.5))
            right_bar.fill.solid()
            right_bar.fill.fore_color.rgb = theme['secondary']
            right_bar.line.fill.background()

            top_bar = slide.shapes.add_shape(1,
                Inches(0), Inches(0),
                Inches(13.33), Inches(0.08))
            top_bar.fill.solid()
            top_bar.fill.fore_color.rgb = theme['accent']
            top_bar.line.fill.background()

            bot_bar = slide.shapes.add_shape(1,
                Inches(0), Inches(7.42),
                Inches(13.33), Inches(0.08))
            bot_bar.fill.solid()
            bot_bar.fill.fore_color.rgb = theme['secondary']
            bot_bar.line.fill.background()

            tb = slide.shapes.add_textbox(
                Inches(1), Inches(1.8),
                Inches(11.33), Inches(2))
            tf = tb.text_frame
            tf.word_wrap = True
            p = tf.paragraphs[0]
            p.text = content.get('title', topic)
            p.alignment = PP_ALIGN.CENTER
            p.font.size = Pt(48)
            p.font.bold = True
            p.font.color.rgb = theme['text']

            div = slide.shapes.add_shape(1,
                Inches(3), Inches(4.0),
                Inches(7.33), Inches(0.05))
            div.fill.solid()
            div.fill.fore_color.rgb = theme['accent']
            div.line.fill.background()

            tb2 = slide.shapes.add_textbox(
                Inches(1), Inches(4.2),
                Inches(11.33), Inches(0.8))
            tf2 = tb2.text_frame
            p2 = tf2.paragraphs[0]
            p2.text = content.get('subtitle', f'A comprehensive guide to {topic}')
            p2.alignment = PP_ALIGN.CENTER
            p2.font.size = Pt(20)
            p2.font.color.rgb = theme['accent']

            badge = slide.shapes.add_textbox(
                Inches(0.5), Inches(6.8),
                Inches(4), Inches(0.4))
            tbf = badge.text_frame
            pb = tbf.paragraphs[0]
            pb.text = f"Theme: {theme_name}"
            pb.font.size = Pt(10)
            pb.font.color.rgb = theme['secondary']

            badge2 = slide.shapes.add_textbox(
                Inches(9.5), Inches(6.8),
                Inches(3.5), Inches(0.4))
            tbf2 = badge2.text_frame
            pb2 = tbf2.paragraphs[0]
            pb2.text = "✦ Made by MK-AI ✦"
            pb2.alignment = PP_ALIGN.RIGHT
            pb2.font.size = Pt(11)
            pb2.font.color.rgb = theme['accent']

        elif stype == 'section':
            side = slide.shapes.add_shape(1,
                Inches(0), Inches(2.5),
                Inches(0.5), Inches(2.5))
            side.fill.solid()
            side.fill.fore_color.rgb = theme['accent']
            side.line.fill.background()

            num_box = slide.shapes.add_textbox(
                Inches(1), Inches(2),
                Inches(3), Inches(2))
            tfn = num_box.text_frame
            pn = tfn.paragraphs[0]
            pn.text = f"{slide_idx + 1:02d}"
            pn.font.size = Pt(80)
            pn.font.bold = True
            pn.font.color.rgb = theme['accent']

            tb = slide.shapes.add_textbox(
                Inches(4), Inches(2.8),
                Inches(8.5), Inches(1.5))
            tf = tb.text_frame
            p = tf.paragraphs[0]
            p.text = slide_data.get('title', 'Section')
            p.font.size = Pt(36)
            p.font.bold = True
            p.font.color.rgb = theme['text']

        elif stype == 'quote':
            quote_bg = slide.shapes.add_shape(1,
                Inches(1), Inches(1.5),
                Inches(11.33), Inches(4.5))
            quote_bg.fill.solid()
            quote_bg.fill.fore_color.rgb = theme['secondary']
            quote_bg.line.fill.background()

            qm = slide.shapes.add_textbox(
                Inches(1.2), Inches(1.3),
                Inches(2), Inches(1.5))
            tfq = qm.text_frame
            pq = tfq.paragraphs[0]
            pq.text = '"'
            pq.font.size = Pt(100)
            pq.font.color.rgb = theme['accent']

            quote_text = slide_data.get('quote',
                slide_data.get('points', ['Knowledge is power'])[0])
            tb = slide.shapes.add_textbox(
                Inches(2), Inches(2.5),
                Inches(9.5), Inches(2.5))
            tf = tb.text_frame
            tf.word_wrap = True
            p = tf.paragraphs[0]
            p.text = quote_text
            p.alignment = PP_ALIGN.CENTER
            p.font.size = Pt(22)
            p.font.bold = True
            p.font.color.rgb = theme['text']

            tb2 = slide.shapes.add_textbox(
                Inches(1), Inches(6.2),
                Inches(11.33), Inches(0.5))
            tf2 = tb2.text_frame
            p2 = tf2.paragraphs[0]
            p2.text = f"— {topic}"
            p2.alignment = PP_ALIGN.RIGHT
            p2.font.size = Pt(14)
            p2.font.color.rgb = theme['accent']

        elif stype in ['flowchart', 'mindmap', 'chart', 'stats', 'comparison', 'image']:
            bar = slide.shapes.add_shape(1,
                Inches(0), Inches(0),
                Inches(13.33), Inches(0.08))
            bar.fill.solid()
            bar.fill.fore_color.rgb = theme['accent']
            bar.line.fill.background()

            tb = slide.shapes.add_textbox(
                Inches(0.5), Inches(0.15),
                Inches(12), Inches(0.8))
            tf = tb.text_frame
            p = tf.paragraphs[0]
            p.text = slide_data.get('title', '')
            p.font.size = Pt(26)
            p.font.bold = True
            p.font.color.rgb = theme['text']

            if stype == 'flowchart':
                steps = slide_data.get('steps',
                    slide_data.get('points', ['Step 1', 'Step 2', 'Step 3']))
                chart_buf = make_flowchart(steps, theme,
                    slide_data.get('title', 'Process'))
                slide.shapes.add_picture(chart_buf,
                    Inches(1), Inches(1.1),
                    Inches(11.33), Inches(6))

            elif stype == 'mindmap':
                center_text = slide_data.get('title', topic)[:15]
                branches = slide_data.get('branches',
                    slide_data.get('points', ['A', 'B', 'C', 'D']))
                chart_buf = make_mindmap(center_text, branches, theme)
                slide.shapes.add_picture(chart_buf,
                    Inches(0.5), Inches(1.1),
                    Inches(12.33), Inches(6))

            elif stype in ['chart', 'stats']:
                labels = ['2020', '2021', '2022', '2023', '2024', '2025']
                data_points = [{'label': l, 'value': random.randint(30, 90)}
                              for l in labels]
                chart_buf = make_stats_chart(data_points, theme,
                    slide_data.get('chart_type', 'bar'))
                slide.shapes.add_picture(chart_buf,
                    Inches(1.5), Inches(1.2),
                    Inches(10.33), Inches(5.8))

            elif stype == 'comparison':
                points = slide_data.get('points', ['Item 1', 'Item 2'])
                chart_buf = make_comparison_table(points, theme)
                slide.shapes.add_picture(chart_buf,
                    Inches(0.5), Inches(1.2),
                    Inches(12.33), Inches(5.8))

            elif stype == 'image':
                image_query = slide_data.get('image_query', topic)
                img_buf = fetch_fallback_image(image_query, theme)
                if img_buf:
                    slide.shapes.add_picture(img_buf,
                        Inches(0), Inches(1.0),
                        Inches(13.33), Inches(6.4))

        else:
            # Content slide
            bar = slide.shapes.add_shape(1,
                Inches(0), Inches(0),
                Inches(13.33), Inches(0.08))
            bar.fill.solid()
            bar.fill.fore_color.rgb = theme['accent']
            bar.line.fill.background()

            strip = slide.shapes.add_shape(1,
                Inches(0), Inches(0.08),
                Inches(0.08), Inches(7.42))
            strip.fill.solid()
            strip.fill.fore_color.rgb = theme['secondary']
            strip.line.fill.background()

            numbox = slide.shapes.add_shape(9,
                Inches(12.0), Inches(0.1),
                Inches(1.0), Inches(0.6))
            numbox.fill.solid()
            numbox.fill.fore_color.rgb = theme['accent']
            numbox.line.fill.background()
            txn = numbox.text_frame
            pn = txn.paragraphs[0]
            pn.text = str(slide_idx + 1)
            pn.alignment = PP_ALIGN.CENTER
            pn.font.size = Pt(14)
            pn.font.bold = True
            pn.font.color.rgb = RGBColor(255, 255, 255)

            title_bg = slide.shapes.add_shape(1,
                Inches(0.2), Inches(0.15),
                Inches(11.5), Inches(0.9))
            title_bg.fill.solid()
            title_bg.fill.fore_color.rgb = theme['secondary']
            title_bg.line.fill.background()

            tb = slide.shapes.add_textbox(
                Inches(0.3), Inches(0.2),
                Inches(11.5), Inches(0.8))
            tf = tb.text_frame
            p = tf.paragraphs[0]
            p.text = slide_data.get('title', '')
            p.font.size = Pt(26)
            p.font.bold = True
            p.font.color.rgb = theme['text']

            div = slide.shapes.add_shape(1,
                Inches(0.2), Inches(1.1),
                Inches(12.9), Inches(0.04))
            div.fill.solid()
            div.fill.fore_color.rgb = theme['accent']
            div.line.fill.background()

            points = slide_data.get('points', [])
            icons = ['▶', '◆', '●', '★', '✦', '▸', '◉', '❯']

            if len(points) >= 4:
                mid = (len(points) + 1) // 2
                left_pts = points[:mid]
                right_pts = points[mid:]

                for col_idx, col_pts in enumerate([left_pts, right_pts]):
                    x = 0.3 + col_idx * 6.5

                    col_bg = slide.shapes.add_shape(1,
                        Inches(x), Inches(1.2),
                        Inches(6.2), Inches(6.0))
                    col_bg.fill.solid()
                    col_bg.fill.fore_color.rgb = theme['secondary']
                    col_bg.line.fill.background()

                    tb2 = slide.shapes.add_textbox(
                        Inches(x + 0.15), Inches(1.3),
                        Inches(5.9), Inches(5.8))
                    tf2 = tb2.text_frame
                    tf2.word_wrap = True

                    for j, pt in enumerate(col_pts[:5]):
                        p2 = tf2.paragraphs[0] if j == 0 else tf2.add_paragraph()
                        p2.text = f"{icons[j % len(icons)]}  {pt}"
                        p2.font.size = Pt(15)
                        p2.font.color.rgb = theme['text']
                        p2.space_before = Pt(10)
            else:
                content_bg = slide.shapes.add_shape(1,
                    Inches(0.3), Inches(1.2),
                    Inches(12.7), Inches(6.0))
                content_bg.fill.solid()
                content_bg.fill.fore_color.rgb = theme['secondary']
                content_bg.line.fill.background()

                tb2 = slide.shapes.add_textbox(
                    Inches(0.5), Inches(1.3),
                    Inches(12.3), Inches(5.8))
                tf2 = tb2.text_frame
                tf2.word_wrap = True

                for j, pt in enumerate(points[:6]):
                    p2 = tf2.paragraphs[0] if j == 0 else tf2.add_paragraph()
                    p2.text = f"{icons[j % len(icons)]}  {pt}"
                    p2.font.size = Pt(17)
                    p2.font.color.rgb = theme['text']
                    p2.space_before = Pt(12)

            # Speaker notes
            notes = slide_data.get('speaker_notes', '')
            if notes:
                try:
                    notes_slide = slide.notes_slide
                    tf_notes = notes_slide.notes_text_frame
                    tf_notes.text = notes
                except:
                    pass

        # Footer
        if stype not in ['title', 'section']:
            footer = slide.shapes.add_textbox(
                Inches(0.2), Inches(7.1),
                Inches(13), Inches(0.3))
            tf_f = footer.text_frame
            pf = tf_f.paragraphs[0]
            pf.text = f"MK-AI | {topic} | {theme_name} Theme"
            pf.alignment = PP_ALIGN.CENTER
            pf.font.size = Pt(8)
            pf.font.color.rgb = theme['secondary']

    prs.save(save_path)
    print(f"✅ Premium PPT saved: {save_path}")
    return save_path

print("✅ Premium PPT builder ready!")

#@title Premium PPT Agent
from google.colab import files
import re, json

def premium_ppt_agent(command):
    print(f"🎨 Premium PPT Agent: {command}\n")

    # Details extract karo
    extract_response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "Extract topic and slides count. Return JSON only: {\"topic\": \"topic here\", \"num_slides\": 15}"},
            {"role": "user", "content": command}
        ],
        max_tokens=100,
        temperature=0.1
    )

    try:
        json_match = re.search(r'\{.*?\}',
            extract_response.choices[0].message.content,
            re.DOTALL)
        details = json.loads(json_match.group())
        topic = details.get('topic', command)
        num_slides = min(int(details.get('num_slides', 15)), 60)
    except:
        topic = command
        num_slides = 15

    print(f"📌 Topic: {topic}")
    print(f"📑 Slides: {num_slides}")

    # Theme select karo
    theme, theme_name = get_online_theme(topic)
    print(f"🎨 Theme: {theme_name}")

    # Content generate karo
    content = generate_premium_content(topic, num_slides)

    # PPT build karo
    save_path = f'/content/{topic[:20].replace(" ", "_")}_Premium_MK-AI.pptx'
    build_premium_ppt(content, topic, theme, theme_name, save_path)

    print(f"\n🎉 Premium PPT ready hai bhai!")
    print(f"📊 Slides: {len(content['slides'])}")
    print(f"🎨 Theme: {theme_name}")

    files.download(save_path)
    return save_path

print("✅ Premium PPT Agent ready!")

#@title Theme Engine Fix
from pptx.dml.color import RGBColor
import random

PALETTES = {
    'Midnight Blue': {'bg': RGBColor(10,10,40), 'accent': RGBColor(0,150,255), 'text': RGBColor(255,255,255), 'secondary': RGBColor(0,80,180)},
    'Royal Purple': {'bg': RGBColor(20,0,40), 'accent': RGBColor(180,0,255), 'text': RGBColor(255,255,255), 'secondary': RGBColor(100,0,180)},
    'Emerald': {'bg': RGBColor(0,30,20), 'accent': RGBColor(0,220,120), 'text': RGBColor(255,255,255), 'secondary': RGBColor(0,140,80)},
    'Sunset': {'bg': RGBColor(40,10,0), 'accent': RGBColor(255,100,0), 'text': RGBColor(255,255,255), 'secondary': RGBColor(200,60,0)},
    'Ocean': {'bg': RGBColor(0,20,40), 'accent': RGBColor(0,200,220), 'text': RGBColor(255,255,255), 'secondary': RGBColor(0,120,160)},
    'Rose Gold': {'bg': RGBColor(40,20,20), 'accent': RGBColor(220,100,120), 'text': RGBColor(255,255,255), 'secondary': RGBColor(180,80,100)},
    'Neon': {'bg': RGBColor(5,5,5), 'accent': RGBColor(0,255,180), 'text': RGBColor(255,255,255), 'secondary': RGBColor(255,0,180)},
    'Galaxy': {'bg': RGBColor(5,0,20), 'accent': RGBColor(120,80,255), 'text': RGBColor(255,255,255), 'secondary': RGBColor(200,100,255)},
    'Golden': {'bg': RGBColor(30,25,0), 'accent': RGBColor(255,200,0), 'text': RGBColor(255,255,255), 'secondary': RGBColor(200,150,0)},
    'Slate': {'bg': RGBColor(20,25,35), 'accent': RGBColor(100,150,200), 'text': RGBColor(255,255,255), 'secondary': RGBColor(60,100,160)},
}

TOPIC_THEMES = {
    'science': 'Midnight Blue', 'physics': 'Slate', 'chemistry': 'Neon',
    'biology': 'Emerald', 'space': 'Galaxy', 'tech': 'Slate',
    'ai': 'Royal Purple', 'computer': 'Midnight Blue', 'coding': 'Neon',
    'business': 'Golden', 'marketing': 'Sunset', 'finance': 'Emerald',
    'history': 'Golden', 'health': 'Emerald', 'medical': 'Ocean',
}

def get_online_theme(topic):
    topic_lower = topic.lower()
    for keyword, theme_name in TOPIC_THEMES.items():
        if keyword in topic_lower:
            return PALETTES[theme_name], theme_name
    theme_name = random.choice(list(PALETTES.keys()))
    return PALETTES[theme_name], theme_name

print("✅ Theme engine ready!")

