premium_ppt_agent("Artificial Intelligence pe 15 slides banao")

#@title Smart Input Handler
def get_ppt_input():
    """User se input lo — topic ya content ya dono"""

    print("="*60)
    print("🎨 MK-AI PREMIUM PPT GENERATOR")
    print("="*60)
    print("\n📝 Input Type choose karo:")
    print("   1 → Sirf Topic do (AI sab likhega)")
    print("   2 → Apna Content do (AI polish karega)")
    print("   3 → Topic + Rough Notes dono do")

    input_type = input("\nChoice (1/2/3): ").strip()

    result = {
        'type': input_type,
        'topic': '',
        'content': '',
        'rough_notes': ''
    }

    if input_type == '1':
        result['topic'] = input("\n📌 Topic kya hai? → ").strip()

    elif input_type == '2':
        print("\n📄 Apna content paste karo (Enter dabao phir 'DONE' likho):")
        lines = []
        while True:
            line = input()
            if line.strip().upper() == 'DONE':
                break
            lines.append(line)
        result['content'] = '\n'.join(lines)
        result['topic'] = input("\n📌 Presentation ka title kya ho? → ").strip()

    elif input_type == '3':
        result['topic'] = input("\n📌 Topic kya hai? → ").strip()
        print("\n📝 Rough notes paste karo (Enter dabao phir 'DONE' likho):")
        lines = []
        while True:
            line = input()
            if line.strip().upper() == 'DONE':
                break
            lines.append(line)
        result['rough_notes'] = '\n'.join(lines)

    print(f"\n✅ Input ready! Type: {input_type}")
    return result

print("✅ Input handler ready!")

#@title Style + Theme + Language Config
def get_ppt_config(topic):
    """User se style, theme, language, slides choose karwao"""

    print("\n" + "="*60)
    print("⚙️ PPT CONFIGURATION")
    print("="*60)

    # Style
    print("\n🎯 Style choose karo:")
    print("   1 → Professional (Corporate/Business)")
    print("   2 → Academic (Students/Education)")
    print("   3 → Creative (Bold + Colorful)")
    print("   4 → Minimal (Clean + Simple)")
    print("   5 → AI Auto Select")

    style_choice = input("\nStyle (1-5): ").strip()
    styles = {
        '1': 'professional',
        '2': 'academic',
        '3': 'creative',
        '4': 'minimal',
        '5': 'auto'
    }
    style = styles.get(style_choice, 'professional')

    # Theme
    print("\n🎨 Theme choose karo:")
    theme_list = list(PALETTES.keys())
    for i, name in enumerate(theme_list):
        print(f"   {i+1:2d} → {name}")
    print(f"   {len(theme_list)+1:2d} → AI Auto Select")

    theme_choice = input(f"\nTheme (1-{len(theme_list)+1}): ").strip()

    try:
        idx = int(theme_choice) - 1
        if idx < len(theme_list):
            theme_name = theme_list[idx]
            theme = PALETTES[theme_name]
        else:
            theme, theme_name = get_online_theme(topic)
    except:
        theme, theme_name = get_online_theme(topic)

    # Language
    print("\n🌐 Language choose karo:")
    print("   1 → English")
    print("   2 → Hindi")
    print("   3 → Hinglish")

    lang_choice = input("\nLanguage (1-3): ").strip()
    languages = {'1': 'English', '2': 'Hindi', '3': 'Hinglish'}
    language = languages.get(lang_choice, 'English')

    # Slides count
    print("\n📑 Kitni slides chahiye?")
    print("   1 → 5-10  (Short)")
    print("   2 → 10-20 (Medium)")
    print("   3 → 20-35 (Detailed)")
    print("   4 → 35-60 (Comprehensive)")
    print("   5 → Custom (Khud likho)")

    slides_choice = input("\nSlides (1-5): ").strip()

    if slides_choice == '1':
        num_slides = 8
    elif slides_choice == '2':
        num_slides = 15
    elif slides_choice == '3':
        num_slides = 25
    elif slides_choice == '4':
        num_slides = 45
    elif slides_choice == '5':
        num_slides = int(input("Kitni slides? (max 60): ").strip() or "15")
        num_slides = min(num_slides, 60)
    else:
        num_slides = 15

    config = {
        'style': style,
        'theme': theme,
        'theme_name': theme_name,
        'language': language,
        'num_slides': num_slides
    }

    print(f"\n✅ Config ready!")
    print(f"   Style: {style}")
    print(f"   Theme: {theme_name}")
    print(f"   Language: {language}")
    print(f"   Slides: {num_slides}")

    return config

print("✅ Config handler ready!")

#@title Content Enhancer + Polish Engine
def enhance_content_with_ai(topic, content, rough_notes, config):
    """
    Content ko AI se enhance karo —
    Topic only → Full content banao
    User content → Polish + Increase karo
    Dono → Mix karke best banao
    """

    style = config['style']
    language = config['language']
    num_slides = config['num_slides']

    style_instructions = {
        'professional': """
- Formal and corporate tone
- Data-driven points
- Business terminology
- Executive summary style
- Action-oriented language""",
        'academic': """
- Educational and informative tone
- Research-backed points
- Clear explanations
- Examples and case studies
- Learning objectives""",
        'creative': """
- Bold and engaging tone
- Story-telling approach
- Vivid descriptions
- Creative metaphors
- Inspiring language""",
        'minimal': """
- Clean and concise
- Maximum 3 points per slide
- Simple language
- No jargon
- Direct and clear"""
    }

    lang_instruction = {
        'English': "Write ALL content in English only.",
        'Hindi': "Write ALL content in Hindi (Devanagari script).",
        'Hinglish': "Write ALL content in Hinglish (Hindi+English mix in Roman script). Example: 'Aaj hum AI ke baare mein samjhenge...'"
    }

    # Prompt banao based on input type
    if content and rough_notes:
        input_section = f"""
User ka content:
{content}

User ke rough notes:
{rough_notes}

Task: Dono ko combine karke best presentation banao."""

    elif content:
        input_section = f"""
User ka content:
{content}

Task: Is content ko enhance karke professional presentation banao.
Content ko expand karo — har point ko zyada detailed banao."""

    elif rough_notes:
        input_section = f"""
Topic: {topic}

User ke rough notes:
{rough_notes}

Task: In notes ko base karke full presentation banao."""

    else:
        input_section = f"""
Topic: {topic}

Task: Is topic pe comprehensive presentation banao."""

    prompt = f"""Create a PREMIUM professional presentation.

{input_section}

Style Requirements:
{style_instructions.get(style, style_instructions['professional'])}

Language: {lang_instruction.get(language, lang_instruction['English'])}

Number of slides: {num_slides}

Return ONLY valid JSON:
{{
  "title": "Compelling presentation title",
  "subtitle": "One powerful tagline",
  "slides": [
    {{
      "title": "Slide title",
      "type": "title/content/image/flowchart/mindmap/chart/comparison/section/quote/stats",
      "points": [
        "Very detailed point 1 with full explanation and examples",
        "Very detailed point 2 with data and insights",
        "Very detailed point 3 with practical applications",
        "Very detailed point 4 with key takeaways",
        "Very detailed point 5 with future implications"
      ],
      "quote": "Inspiring quote (only if type is quote)",
      "steps": ["Step 1 detailed", "Step 2 detailed", "Step 3 detailed"],
      "branches": ["Branch 1", "Branch 2", "Branch 3", "Branch 4"],
      "chart_type": "bar/line/pie",
      "speaker_notes": "Detailed speaker notes for this slide",
      "image_query": "specific image search term"
    }}
  ]
}}

IMPORTANT RULES:
- Each content slide MUST have 4-6 VERY DETAILED points
- Points should be complete sentences with explanations
- Add real data, statistics, examples wherever possible
- Slide 1 = title slide
- Every 5-6 slides = section divider
- Include 2-3 flowchart/mindmap/chart slides
- Include 1-2 quote slides
- Last slide = powerful conclusion + thank you
- Make it {style} style throughout"""

    print(f"🤔 AI premium content bana raha hai...")
    print(f"   Topic: {topic}")
    print(f"   Style: {style}")
    print(f"   Language: {language}")
    print(f"   Slides: {num_slides}")

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are a world-class presentation designer. Create exceptional content. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=6000,
        temperature=0.7
    )

    result = response.choices[0].message.content.strip()

    # JSON extract
    import json, re
    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            content_json = json.loads(json_match.group())
            print(f"✅ {len(content_json['slides'])} slides ready!")
            return content_json
    except Exception as e:
        print(f"⚠️ Parse error: {e}")

    # Fallback
    return {
        "title": topic,
        "subtitle": f"A comprehensive guide to {topic}",
        "slides": [
            {"title": topic, "type": "title", "points": [f"Complete guide to {topic}"], "speaker_notes": "Welcome"},
            {"title": "Introduction", "type": "content", "points": ["What is it?", "Why it matters", "Key concepts", "Our approach", "What we will cover"], "speaker_notes": "Introduction"},
            {"title": "Key Concepts", "type": "content", "points": ["Concept 1 explained", "Concept 2 explained", "Concept 3 explained", "Practical examples"], "speaker_notes": "Main concepts"},
            {"title": "Process Flow", "type": "flowchart", "steps": ["Research", "Planning", "Execution", "Review", "Launch"], "speaker_notes": "Process"},
            {"title": "Data Analysis", "type": "chart", "chart_type": "bar", "points": [], "speaker_notes": "Data"},
            {"title": "Conclusion", "type": "content", "points": ["Key takeaways", "Next steps", "Action items", "Thank you!"], "speaker_notes": "Conclusion"}
        ]
    }

print("✅ Content enhancer ready!")

#@title Export Handler
from google.colab import files
import subprocess

def export_ppt(pptx_path, topic, export_pdf=True):
    """PPT ko download karo — PPTX + PDF dono"""

    print(f"\n📦 Export ho raha hai...")

    # PPTX download
    print("📊 PPTX downloading...")
    files.download(pptx_path)

    # PDF export
    if export_pdf:
        try:
            pdf_path = pptx_path.replace('.pptx', '.pdf')

            # LibreOffice se PDF banao
            result = subprocess.run([
                'libreoffice', '--headless', '--convert-to', 'pdf',
                '--outdir', '/content/', pptx_path
            ], capture_output=True, text=True, timeout=60)

            import os
            if os.path.exists(pdf_path):
                print("📄 PDF downloading...")
                files.download(pdf_path)
                print("✅ PDF bhi download ho gaya!")
            else:
                print("⚠️ PDF export nahi hua — sirf PPTX download hua")
        except Exception as e:
            print(f"⚠️ PDF error: {e} — sirf PPTX download hua")

    print("🎉 Export complete!")

print("✅ Export handler ready!")

#@title Master PPT Agent
def advanced_ppt_agent(command=None):
    """
    Full powered PPT agent —
    Topic / Content / Dono accept karta hai
    Theme + Style + Language choose karne deta hai
    """

    print("\n🚀 MK-AI Advanced PPT Generator Starting...\n")

    # Command se topic extract karo agar diya
    if command:
        import re, json
        try:
            extract = groq_client.chat.completions.create(
                model="llama-3.3-70b-versatile",
                messages=[
                    {"role": "system", "content": "Extract topic from command. Return JSON only: {\"topic\": \"topic here\", \"num_slides\": 15}"},
                    {"role": "user", "content": command}
                ],
                max_tokens=100,
                temperature=0.1
            )
            details = json.loads(re.search(r'\{.*?\}',
                extract.choices[0].message.content,
                re.DOTALL).group())
            auto_topic = details.get('topic', command)
            auto_slides = min(int(details.get('num_slides', 15)), 60)
        except:
            auto_topic = command
            auto_slides = 15

        print(f"📌 Topic detected: {auto_topic}")

        # Quick mode — command se seedha banao
        print("\n⚡ Quick Mode ya Custom Mode?")
        print("   1 → Quick (Automatic sab decide hoga)")
        print("   2 → Custom (Khud sab choose karo)")
        mode = input("\nChoice (1/2): ").strip()

        if mode == '1':
            theme, theme_name = get_online_theme(auto_topic)
            config = {
                'style': 'professional',
                'theme': theme,
                'theme_name': theme_name,
                'language': 'English',
                'num_slides': auto_slides
            }
            user_input = {
                'type': '1',
                'topic': auto_topic,
                'content': '',
                'rough_notes': ''
            }
        else:
            user_input = get_ppt_input()
            config = get_ppt_config(user_input['topic'] or auto_topic)
    else:
        # Interactive mode
        user_input = get_ppt_input()
        config = get_ppt_config(user_input['topic'])

    topic = user_input.get('topic') or command or 'Presentation'

    # Content generate/enhance karo
    content = enhance_content_with_ai(
        topic=topic,
        content=user_input.get('content', ''),
        rough_notes=user_input.get('rough_notes', ''),
        config=config
    )

    # PPT build karo
    save_path = f'/content/{topic[:20].replace(" ", "_")}_MK-AI_Premium.pptx'

    print(f"\n🏗️ PPT build ho raha hai...")
    build_premium_ppt(
        content=content,
        topic=topic,
        theme=config['theme'],
        theme_name=config['theme_name'],
        save_path=save_path
    )

    print(f"\n✅ PPT ready!")
    print(f"   📊 Slides: {len(content['slides'])}")
    print(f"   🎨 Theme: {config['theme_name']}")
    print(f"   🎯 Style: {config['style']}")
    print(f"   🌐 Language: {config['language']}")

    # Export karo
    export_pdf = input("\n📄 PDF bhi chahiye? (haan/nahi): ").strip().lower()
    export_ppt(save_path, topic, export_pdf in ['haan', 'ha', 'y', 'yes', 'h'])

    return save_path

print("✅ Master PPT Agent ready!")

