#@title Master PDF Agent
from google.colab import files

def online_pdf_agent(command=None):
    """Full powered PDF agent"""

    print("\n🚀 MK-AI Premium PDF Generator Starting...\n")

    if command:
        import re, json
        try:
            extract = groq_client.chat.completions.create(
                model="llama-3.3-70b-versatile",
                messages=[
                    {"role": "system", "content": "Extract topic from command. JSON only: {\"topic\": \"topic\"}"},
                    {"role": "user", "content": command}
                ],
                max_tokens=50,
                temperature=0.1
            )
            details = json.loads(re.search(r'\{.*?\}',
                extract.choices[0].message.content,
                re.DOTALL).group())
            auto_topic = details.get('topic', command)
        except:
            auto_topic = command

        print(f"📌 Topic: {auto_topic}")
        print("\n⚡ Quick Mode ya Custom Mode?")
        print("   1 → Quick (Auto sab)")
        print("   2 → Custom (Khud choose karo)")

        mode = input("\nChoice (1/2): ").strip()

        if mode == '1':
            user_input = {
                'type': '1',
                'topic': auto_topic,
                'content': '',
                'rough_notes': '',
                'doc_type': 'general document',
                'language': 'English',
                'style': 'professional'
            }
        else:
            user_input = get_pdf_input()
    else:
        user_input = get_pdf_input()

    topic = user_input.get('topic', 'Document')
    style = user_input.get('style', 'professional')

    # Content generate
    content = generate_online_pdf_content(user_input)

    # PDF build
    save_path = f'/content/{topic[:20].replace(" ", "_")}_MK-AI_Premium.pdf'
    build_online_pdf(content, topic, style, save_path)

    print(f"\n🎉 Premium PDF ready!")
    print(f"   📄 Sections: {len(content['sections'])}")
    print(f"   🎨 Style: {style}")
    print(f"   🌐 Language: {user_input.get('language', 'English')}")

    files.download(save_path)
    return save_path

print("✅ Master PDF Agent ready!")

