#@title Grammar Fix Agent
def grammar_fix_agent(command=None):
    """
    Full Grammar Fix Agent —
    Text do → AI fix karega
    """

    print("="*60)
    print("✏️ MK-AI GRAMMAR FIX AGENT")
    print("="*60)

    print("\n🎯 Kya karna hai?")
    print("   1 → Grammar fix karo")
    print("   2 → Text improve karo (better wording)")
    print("   3 → Formal banao")
    print("   4 → Simple banao")
    print("   5 → Hinglish → English convert karo")
    print("   6 → English → Hinglish convert karo")

    choice = input("\nChoice (1-6): ").strip()

    print("\n📝 Text paste karo (phir 'DONE' likho):")
    lines = []
    while True:
        line = input()
        if line.strip().upper() == 'DONE':
            break
        lines.append(line)

    text = '\n'.join(lines)

    if not text.strip():
        print("❌ Koi text nahi diya!")
        return

    task_map = {
        '1': 'Fix all grammar, spelling and punctuation errors. Keep the meaning same.',
        '2': 'Improve the wording and style. Make it more impactful and clear.',
        '3': 'Convert to formal professional language suitable for business or academic use.',
        '4': 'Simplify the language. Use simple words. Make it easy to understand.',
        '5': 'Convert Hinglish text to proper professional English.',
        '6': 'Convert English text to natural Hinglish (Hindi+English Roman mix).'
    }

    task = task_map.get(choice, task_map['1'])

    # Output language
    print("\n🌐 Output Language:")
    print("   1 → Same as input")
    print("   2 → English")
    print("   3 → Hinglish")

    lang_choice = input("Choice (1-3): ").strip()

    lang_rule = {
        '1': "Keep the same language as input.",
        '2': "Output in English only.",
        '3': "Output in Hinglish (Hindi+English Roman mix)."
    }.get(lang_choice, "Keep the same language as input.")

    prompt = f"""You are MK-AI Grammar Expert.

Task: {task}
Language Rule: {lang_rule}

Original Text:
{text}

Provide:
1. FIXED TEXT (just the corrected version)
2. CHANGES MADE (list what was changed)
3. TIPS (2-3 writing tips based on errors found)

Format your response exactly like this:
---FIXED TEXT---
[corrected text here]

---CHANGES MADE---
[list of changes]

---TIPS---
[writing tips]"""

    print(f"\n🤔 AI text fix kar raha hai...")

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert grammar and writing coach. Fix text professionally."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=2000,
        temperature=0.3
    )

    result = response.choices[0].message.content.strip()

    print("\n" + "="*60)
    print("✏️ GRAMMAR FIX RESULT")
    print("="*60)
    print(result)
    print("="*60)

    # Save option
    save = input("\n💾 Fixed text save karein? (haan/nahi): ").strip().lower()
    if save in ['haan', 'ha', 'y', 'yes', 'h']:
        save_path = '/content/Grammar_Fixed_MK-AI.txt'
        with open(save_path, 'w', encoding='utf-8') as f:
            f.write(f"ORIGINAL:\n{text}\n\n")
            f.write(f"FIXED:\n{result}")
        from google.colab import files
        files.download(save_path)
        print("✅ File download ho gayi!")

    return result

print("✅ Grammar Fix Agent ready!")

#@title Quick Grammar Fix
def fix_grammar(text, mode='grammar'):
    """
    Quick grammar fix —
    fix_grammar("your text here")
    fix_grammar("your text", mode='formal')
    fix_grammar("your text", mode='simple')
    fix_grammar("your text", mode='improve')
    """

    mode_map = {
        'grammar': 'Fix grammar, spelling and punctuation only.',
        'formal': 'Make it formal and professional.',
        'simple': 'Simplify the language.',
        'improve': 'Improve the wording and style.',
        'hinglish': 'Convert to Hinglish.',
        'english': 'Convert to proper English.'
    }

    task = mode_map.get(mode, mode_map['grammar'])

    has_hinglish = any(w in text.lower() for w in [
        'bhai', 'yaar', 'kya', 'hai', 'nahi', 'toh', 'aur'
    ])

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": f"You are a grammar expert. {task} Return only the fixed text, nothing else."},
            {"role": "user", "content": text}
        ],
        max_tokens=1000,
        temperature=0.2
    )

    fixed = response.choices[0].message.content.strip()

    print(f"📝 Original: {text}")
    print(f"✅ Fixed: {fixed}")

    return fixed

print("✅ Quick grammar fix ready!")

