#@title Smart Resume Input Handler
import pytesseract
from PIL import Image
import io, re

def extract_text_from_image(image_path):
    """Certificate/Degree photo se text nikalo"""
    print("🔍 Certificate/Photo padh raha hai...")
    try:
        img = Image.open(image_path)
        img = img.convert('RGB')
        text = pytesseract.image_to_string(img, lang='eng+hin')
        print(f"✅ Text extract hua! ({len(text)} chars)")
        return text.strip()
    except Exception as e:
        print(f"❌ Error: {e}")
        return ""

def extract_info_from_text(raw_text, source_type):
    """AI se information extract karo"""

    prompt = f"""Extract resume information from this {source_type}:

{raw_text}

Return ONLY valid JSON:
{{
  "name": "Full name",
  "email": "email@example.com",
  "phone": "phone number",
  "location": "city, state",
  "linkedin": "linkedin url or empty",
  "github": "github url or empty",
  "portfolio": "portfolio url or empty",
  "summary": "professional summary",
  "education": [
    {{
      "degree": "degree name",
      "field": "field of study",
      "institution": "college/school name",
      "year": "graduation year",
      "grade": "percentage/CGPA",
      "achievements": ["achievement 1", "achievement 2"]
    }}
  ],
  "experience": [
    {{
      "title": "job title",
      "company": "company name",
      "duration": "start - end date",
      "location": "city",
      "points": ["achievement 1", "achievement 2", "achievement 3"]
    }}
  ],
  "skills": {{
    "technical": ["skill 1", "skill 2"],
    "soft": ["skill 1", "skill 2"],
    "languages": ["English", "Hindi"],
    "tools": ["tool 1", "tool 2"]
  }},
  "projects": [
    {{
      "name": "project name",
      "description": "what it does",
      "tech": ["tech 1", "tech 2"],
      "link": "github/live link or empty"
    }}
  ],
  "certifications": [
    {{
      "name": "certification name",
      "issuer": "issued by",
      "year": "year"
    }}
  ],
  "achievements": ["achievement 1", "achievement 2"],
  "hobbies": ["hobby 1", "hobby 2"]
}}

If any field is not found, use empty string or empty list."""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert at extracting resume information. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=3000,
        temperature=0.2
    )

    result = response.choices[0].message.content.strip()

    import json
    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            return json.loads(json_match.group())
    except:
        pass

    return {}

def get_resume_input():
    """User se resume input lo"""

    print("="*60)
    print("📄 MK-AI RESUME/CV MAKER")
    print("="*60)

    print("\n📝 Input Method:")
    print("   1 → Chat se batao (type karke)")
    print("   2 → Certificate/Degree photo upload")
    print("   3 → Purana resume upload (PDF/Image)")
    print("   4 → Mix (Photo + Chat dono)")

    method = input("\nChoice (1-4): ").strip()

    resume_data = {}

    if method in ['2', '3', '4']:
        from google.colab import files
        print("\n📸 File upload karo (certificate/photo/resume):")
        uploaded = files.upload()

        if uploaded:
            filename = list(uploaded.keys())[0]
            filepath = f"/content/{filename}"

            # Image se text nikalo
            raw_text = extract_text_from_image(filepath)

            if raw_text:
                print("🤔 AI information extract kar raha hai...")
                resume_data = extract_info_from_text(raw_text, "certificate/resume")
                print("✅ Information extract ho gayi!")

                # Dikhao kya mila
                print(f"\n📋 Extracted Info:")
                print(f"   Name: {resume_data.get('name', 'Not found')}")
                print(f"   Email: {resume_data.get('email', 'Not found')}")
                print(f"   Education: {len(resume_data.get('education', []))} entries")
                print(f"   Experience: {len(resume_data.get('experience', []))} entries")

    if method in ['1', '4']:
        print("\n💬 Chat se batao — jo pata ho woh type karo:")
        print("   (Enter karo phir 'DONE' likho)")

        lines = []
        while True:
            line = input()
            if line.strip().upper() == 'DONE':
                break
            lines.append(line)

        chat_text = '\n'.join(lines)

        if chat_text:
            print("🤔 AI chat se information extract kar raha hai...")
            chat_data = extract_info_from_text(chat_text, "chat message")

            # Merge with existing data
            for key, value in chat_data.items():
                if value and not resume_data.get(key):
                    resume_data[key] = value
                elif isinstance(value, list) and value:
                    existing = resume_data.get(key, [])
                    if isinstance(existing, list):
                        resume_data[key] = existing + value

    # Missing info manually fill karo
    print("\n📝 Kuch details manually confirm/add karo:")

    if not resume_data.get('name'):
        resume_data['name'] = input("👤 Full Name: ").strip()
    else:
        confirm = input(f"👤 Name: {resume_data['name']} (Enter to confirm or type new): ").strip()
        if confirm:
            resume_data['name'] = confirm

    if not resume_data.get('email'):
        resume_data['email'] = input("📧 Email: ").strip()

    if not resume_data.get('phone'):
        resume_data['phone'] = input("📱 Phone: ").strip()

    if not resume_data.get('location'):
        resume_data['location'] = input("📍 Location (City, State): ").strip()

    # Job target
    resume_data['target_job'] = input("\n🎯 Target Job/Role (e.g. Software Engineer): ").strip()
    resume_data['job_description'] = ""

    add_jd = input("📋 Job Description paste karein ATS check ke liye? (haan/nahi): ").strip().lower()
    if add_jd in ['haan', 'ha', 'y', 'yes', 'h']:
        print("Job Description paste karo (phir 'DONE' likho):")
        jd_lines = []
        while True:
            line = input()
            if line.strip().upper() == 'DONE':
                break
            jd_lines.append(line)
        resume_data['job_description'] = '\n'.join(jd_lines)

    # New skills add karo
    new_skills = input("\n🆕 Koi nayi skills add karni hain? (comma separated): ").strip()
    if new_skills:
        new_skill_list = [s.strip() for s in new_skills.split(',')]
        existing = resume_data.get('skills', {})
        if isinstance(existing, dict):
            existing['technical'] = existing.get('technical', []) + new_skill_list
        else:
            existing = {'technical': new_skill_list, 'soft': [], 'languages': [], 'tools': []}
        resume_data['skills'] = existing

    print("\n✅ Input collection complete!")
    return resume_data

print("✅ Smart input handler ready!")

#@title AI Content Enhancer
def enhance_resume_content(resume_data):
    """AI se resume content enhance karo"""

    print("🤔 AI content enhance kar raha hai...")

    target_job = resume_data.get('target_job', 'Professional')
    job_desc = resume_data.get('job_description', '')

    prompt = f"""You are an expert resume writer. Enhance this resume data for: {target_job}

Current Data:
{str(resume_data)[:3000]}

Job Description (if provided):
{job_desc[:1000] if job_desc else 'Not provided'}

Return enhanced JSON with:
1. Professional summary (3-4 powerful sentences)
2. Enhanced experience bullet points (achievement-focused, use numbers)
3. ATS-optimized skills list
4. Suggested skills to add based on job
5. ATS score if job description provided
6. Missing sections to add

Return ONLY valid JSON:
{{
  "summary": "Enhanced professional summary",
  "enhanced_experience": [
    {{
      "title": "job title",
      "company": "company",
      "duration": "duration",
      "points": [
        "Achieved X% improvement in Y by doing Z",
        "Led team of N people to accomplish X",
        "Developed X resulting in Y outcome"
      ]
    }}
  ],
  "suggested_skills": ["skill 1", "skill 2", "skill 3"],
  "ats_score": 85,
  "ats_feedback": "ATS feedback here",
  "missing_sections": ["section 1", "section 2"],
  "improvements": ["improvement 1", "improvement 2"]
}}"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert resume writer and ATS specialist. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=3000,
        temperature=0.4
    )

    result = response.choices[0].message.content.strip()

    import json
    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            enhanced = json.loads(json_match.group())

            # Merge enhanced data
            if enhanced.get('summary'):
                resume_data['summary'] = enhanced['summary']

            if enhanced.get('enhanced_experience'):
                resume_data['experience'] = enhanced['enhanced_experience']

            if enhanced.get('suggested_skills'):
                skills = resume_data.get('skills', {})
                if isinstance(skills, dict):
                    skills['suggested'] = enhanced['suggested_skills']
                resume_data['skills'] = skills

            resume_data['ats_score'] = enhanced.get('ats_score', 0)
            resume_data['ats_feedback'] = enhanced.get('ats_feedback', '')
            resume_data['improvements'] = enhanced.get('improvements', [])

            print(f"✅ Content enhanced!")
            if enhanced.get('ats_score'):
                print(f"📊 ATS Score: {enhanced['ats_score']}/100")
            if enhanced.get('improvements'):
                print(f"💡 Improvements:")
                for imp in enhanced['improvements'][:3]:
                    print(f"   → {imp}")
    except Exception as e:
        print(f"⚠️ Enhancement error: {e}")

    return resume_data

print("✅ AI content enhancer ready!")

#@title Resume PDF Builder
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor, white, black, Color
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable
from reportlab.lib.units import inch, cm
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_RIGHT, TA_JUSTIFY
from datetime import datetime

def build_resume_pdf(resume_data, template_num, theme_name, save_path=None):
    """20 templates mein se ek choose karke resume banao"""

    name = resume_data.get('name', 'Your Name')
    if not save_path:
        save_path = f'/content/{name.replace(" ", "_")}_Resume_MK-AI.pdf'

    theme = RESUME_THEMES.get(theme_name, RESUME_THEMES['Navy Blue'])
    template = RESUME_TEMPLATES.get(template_num, 'Modern Tech')

    print(f"🏗️ Building: {template} template with {theme_name} theme...")

    doc = SimpleDocTemplate(
        save_path, pagesize=A4,
        rightMargin=1.5*cm, leftMargin=1.5*cm,
        topMargin=1.5*cm, bottomMargin=1.5*cm
    )

    story = []

    # Styles
    name_style = ParagraphStyle('Name',
        fontSize=28, fontName='Helvetica-Bold',
        textColor=HexColor(theme['primary']),
        alignment=TA_CENTER, spaceAfter=4)

    contact_style = ParagraphStyle('Contact',
        fontSize=9, fontName='Helvetica',
        textColor=HexColor('#424242'),
        alignment=TA_CENTER, spaceAfter=2)

    section_style = ParagraphStyle('Section',
        fontSize=12, fontName='Helvetica-Bold',
        textColor=white, spaceAfter=0)

    body_style = ParagraphStyle('Body',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor(theme['text']),
        spaceAfter=4, leading=16)

    bullet_style = ParagraphStyle('Bullet',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor(theme['text']),
        leftIndent=15, spaceAfter=3, leading=15)

    job_title_style = ParagraphStyle('JobTitle',
        fontSize=11, fontName='Helvetica-Bold',
        textColor=HexColor(theme['primary']), spaceAfter=2)

    company_style = ParagraphStyle('Company',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor(theme['accent']), spaceAfter=4)

    sub_style = ParagraphStyle('Sub',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor('#616161'), spaceAfter=4)

    # ===== HEADER =====
    # Name
    story.append(Paragraph(name, name_style))

    # Target Job
    if resume_data.get('target_job'):
        target_style = ParagraphStyle('Target',
            fontSize=13, fontName='Helvetica',
            textColor=HexColor(theme['accent']),
            alignment=TA_CENTER, spaceAfter=6)
        story.append(Paragraph(resume_data['target_job'], target_style))

    # Contact bar
    contact_parts = []
    if resume_data.get('email'):
        contact_parts.append(f"✉ {resume_data['email']}")
    if resume_data.get('phone'):
        contact_parts.append(f"📱 {resume_data['phone']}")
    if resume_data.get('location'):
        contact_parts.append(f"📍 {resume_data['location']}")
    if resume_data.get('linkedin'):
        contact_parts.append(f"💼 {resume_data['linkedin']}")
    if resume_data.get('github'):
        contact_parts.append(f"🐙 {resume_data['github']}")

    if contact_parts:
        contact_text = "  |  ".join(contact_parts)
        story.append(Paragraph(contact_text, contact_style))

    story.append(HRFlowable(width="100%", thickness=3,
                            color=HexColor(theme['primary'])))
    story.append(Spacer(1, 0.2*cm))

    def add_section_header(title):
        """Section header banao"""
        header_data = [[
            Paragraph(f'<b>{title}</b>', section_style)
        ]]
        header_table = Table(header_data,
                            colWidths=[18*cm], rowHeights=[0.6*cm])
        header_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['primary'])),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(header_table)
        story.append(Spacer(1, 0.15*cm))

    # ===== ATS SCORE =====
    if resume_data.get('ats_score'):
        score = resume_data['ats_score']
        color = '#2E7D32' if score >= 70 else '#F57F17' if score >= 50 else '#C62828'

        ats_data = [[
            Paragraph(f'<font color="white"><b>ATS Score: {score}/100</b></font>',
                     ParagraphStyle('ats', fontSize=11, textColor=white,
                                   fontName='Helvetica-Bold')),
            Paragraph(f'<font color="white">{resume_data.get("ats_feedback", "")[:80]}</font>',
                     ParagraphStyle('atsfb', fontSize=9, textColor=white,
                                   fontName='Helvetica'))
        ]]
        ats_table = Table(ats_data, colWidths=[5*cm, 13*cm], rowHeights=[0.7*cm])
        ats_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (0,-1), HexColor(color)),
            ('BACKGROUND', (1,0), (1,-1), HexColor(theme['accent'])),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(ats_table)
        story.append(Spacer(1, 0.2*cm))

    # ===== SUMMARY =====
    if resume_data.get('summary'):
        add_section_header('PROFESSIONAL SUMMARY')
        summary_box = [[
            Paragraph(resume_data['summary'], body_style)
        ]]
        sum_table = Table(summary_box, colWidths=[18*cm])
        sum_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['light'])),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('RIGHTPADDING', (0,0), (-1,-1), 10),
            ('TOPPADDING', (0,0), (-1,-1), 8),
            ('BOTTOMPADDING', (0,0), (-1,-1), 8),
            ('BOX', (0,0), (-1,-1), 0.5, HexColor(theme['accent'])),
        ]))
        story.append(sum_table)
        story.append(Spacer(1, 0.2*cm))

    # ===== EXPERIENCE =====
    experience = resume_data.get('experience', [])
    if experience:
        add_section_header('WORK EXPERIENCE')
        for exp in experience:
            # Job title + Company
            story.append(Paragraph(exp.get('title', ''), job_title_style))

            comp_dur = f"{exp.get('company', '')} | {exp.get('duration', '')} | {exp.get('location', '')}"
            story.append(Paragraph(comp_dur, company_style))

            # Points
            for point in exp.get('points', []):
                story.append(Paragraph(f"▸  {point}", bullet_style))

            story.append(Spacer(1, 0.15*cm))

    # ===== EDUCATION =====
    education = resume_data.get('education', [])
    if education:
        add_section_header('EDUCATION')
        for edu in education:
            story.append(Paragraph(
                f"{edu.get('degree', '')} in {edu.get('field', '')}",
                job_title_style))
            story.append(Paragraph(
                f"{edu.get('institution', '')} | {edu.get('year', '')} | {edu.get('grade', '')}",
                company_style))
            for ach in edu.get('achievements', []):
                story.append(Paragraph(f"▸  {ach}", bullet_style))
            story.append(Spacer(1, 0.1*cm))

    # ===== SKILLS =====
    skills = resume_data.get('skills', {})
    if skills:
        add_section_header('SKILLS')

        if isinstance(skills, dict):
            skill_rows = []

            if skills.get('technical'):
                skill_rows.append([
                    Paragraph('<b>Technical:</b>', ParagraphStyle('sk', fontSize=10,
                        fontName='Helvetica-Bold', textColor=HexColor(theme['primary']))),
                    Paragraph(', '.join(skills['technical']), body_style)
                ])

            if skills.get('soft'):
                skill_rows.append([
                    Paragraph('<b>Soft Skills:</b>', ParagraphStyle('sk', fontSize=10,
                        fontName='Helvetica-Bold', textColor=HexColor(theme['primary']))),
                    Paragraph(', '.join(skills['soft']), body_style)
                ])

            if skills.get('tools'):
                skill_rows.append([
                    Paragraph('<b>Tools:</b>', ParagraphStyle('sk', fontSize=10,
                        fontName='Helvetica-Bold', textColor=HexColor(theme['primary']))),
                    Paragraph(', '.join(skills['tools']), body_style)
                ])

            if skills.get('languages'):
                skill_rows.append([
                    Paragraph('<b>Languages:</b>', ParagraphStyle('sk', fontSize=10,
                        fontName='Helvetica-Bold', textColor=HexColor(theme['primary']))),
                    Paragraph(', '.join(skills['languages']), body_style)
                ])

            if skills.get('suggested'):
                skill_rows.append([
                    Paragraph('<b>Suggested:</b>', ParagraphStyle('sk', fontSize=10,
                        fontName='Helvetica-Bold', textColor=HexColor('#2E7D32'))),
                    Paragraph(', '.join(skills['suggested']),
                             ParagraphStyle('sugg', fontSize=10, fontName='Helvetica',
                                           textColor=HexColor('#2E7D32')))
                ])

            if skill_rows:
                skills_table = Table(skill_rows, colWidths=[4*cm, 14*cm])
                skills_table.setStyle(TableStyle([
                    ('BACKGROUND', (0,0), (0,-1), HexColor(theme['light'])),
                    ('LEFTPADDING', (0,0), (-1,-1), 8),
                    ('TOPPADDING', (0,0), (-1,-1), 5),
                    ('BOTTOMPADDING', (0,0), (-1,-1), 5),
                    ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['accent'])),
                ]))
                story.append(skills_table)

        story.append(Spacer(1, 0.2*cm))

    # ===== PROJECTS =====
    projects = resume_data.get('projects', [])
    if projects:
        add_section_header('PROJECTS')
        for proj in projects:
            proj_name = proj.get('name', '')
            tech = proj.get('tech', [])
            tech_str = f" | Tech: {', '.join(tech)}" if tech else ""

            story.append(Paragraph(f"{proj_name}{tech_str}", job_title_style))
            story.append(Paragraph(proj.get('description', ''), body_style))

            if proj.get('link'):
                story.append(Paragraph(
                    f"🔗 {proj['link']}",
                    ParagraphStyle('link', fontSize=9, fontName='Helvetica',
                                  textColor=HexColor(theme['accent']))))
            story.append(Spacer(1, 0.1*cm))

    # ===== CERTIFICATIONS =====
    certs = resume_data.get('certifications', [])
    if certs:
        add_section_header('CERTIFICATIONS')
        cert_data = []
        for cert in certs:
            cert_data.append([
                Paragraph(f"🏆 {cert.get('name', '')}", body_style),
                Paragraph(cert.get('issuer', ''), sub_style),
                Paragraph(cert.get('year', ''), sub_style)
            ])

        if cert_data:
            cert_table = Table(cert_data, colWidths=[9*cm, 6*cm, 3*cm])
            cert_table.setStyle(TableStyle([
                ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['light'])),
                ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['accent'])),
                ('LEFTPADDING', (0,0), (-1,-1), 8),
                ('TOPPADDING', (0,0), (-1,-1), 4),
                ('BOTTOMPADDING', (0,0), (-1,-1), 4),
            ]))
            story.append(cert_table)
        story.append(Spacer(1, 0.2*cm))

    # ===== ACHIEVEMENTS =====
    achievements = resume_data.get('achievements', [])
    if achievements:
        add_section_header('ACHIEVEMENTS')
        for ach in achievements:
            story.append(Paragraph(f"⭐ {ach}", bullet_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== FOOTER =====
    story.append(HRFlowable(width="100%", thickness=1,
                            color=HexColor(theme['primary'])))
    footer_text = f'Generated by MK-AI | Made by Mushab Khan | {datetime.now().strftime("%B %d, %Y")}'
    story.append(Paragraph(footer_text,
        ParagraphStyle('footer', fontSize=8, fontName='Helvetica',
                      textColor=HexColor(theme['accent']),
                      alignment=TA_CENTER)))

    doc.build(story)
    print(f"✅ Resume saved: {save_path}")
    return save_path

print("✅ Resume PDF builder ready!")

#@title Master Resume Agent
from google.colab import files

def resume_agent():
    """Full Resume/CV Maker Agent"""

    print("🚀 MK-AI Resume/CV Maker Starting...\n")

    # Step 1 — Input lo
    resume_data = get_resume_input()

    # Step 2 — AI enhance karo
    print("\n🤔 AI content enhance kar raha hai...")
    resume_data = enhance_resume_content(resume_data)

    # Step 3 — Template choose karo
    print("\n📋 Template choose karo:")
    for k, v in RESUME_TEMPLATES.items():
        print(f"   {k:2d} → {v}")

    template_num = int(input("\nTemplate number (1-20): ").strip() or "1")
    template_num = max(1, min(20, template_num))

    # Step 4 — Theme choose karo
    print("\n🎨 Theme choose karo:")
    themes_list = list(RESUME_THEMES.keys())
    for i, name in enumerate(themes_list, 1):
        print(f"   {i:2d} → {name}")

    theme_choice = int(input(f"\nTheme number (1-{len(themes_list)}): ").strip() or "1")
    theme_name = themes_list[max(0, min(len(themes_list)-1, theme_choice-1))]

    print(f"\n✅ Building resume...")
    print(f"   Template: {RESUME_TEMPLATES[template_num]}")
    print(f"   Theme: {theme_name}")

    # Step 5 — Resume build karo
    name = resume_data.get('name', 'Resume')
    save_path = f'/content/{name.replace(" ", "_")}_Resume_MK-AI.pdf'
    build_resume_pdf(resume_data, template_num, theme_name, save_path)

    # Step 6 — Download karo
    files.download(save_path)
    print("✅ Resume download ho gaya!")

    # Step 7 — Cover letter
    cover = input("\n📝 Cover letter bhi chahiye? (haan/nahi): ").strip().lower()
    if cover in ['haan', 'ha', 'y', 'yes', 'h']:
        letter = generate_cover_letter(resume_data)

        cl_path = f'/content/{name.replace(" ", "_")}_CoverLetter_MK-AI.txt'
        with open(cl_path, 'w', encoding='utf-8') as f:
            f.write(letter)
        files.download(cl_path)
        print("✅ Cover letter download ho gayi!")

    # Step 8 — ATS feedback
    if resume_data.get('ats_score'):
        print(f"\n📊 ATS Score: {resume_data['ats_score']}/100")
        print(f"💡 Feedback: {resume_data.get('ats_feedback', '')}")

    if resume_data.get('improvements'):
        print("\n🔧 Improvements:")
        for imp in resume_data.get('improvements', []):
            print(f"   → {imp}")

    print("\n🎉 Resume ready hai bhai!")
    return resume_data

print("✅ Master Resume Agent ready!")

