#@title Study Planner Agent
def study_planner_agent():
    """
    Full Study Planner —
    Exam details do → AI complete plan banaye
    """

    print("="*60)
    print("📚 MK-AI STUDY PLANNER")
    print("="*60)

    # Basic info
    print("\n👤 Basic Info:")
    name = input("Tera naam: ").strip()

    print("\n📝 Exam Type:")
    print("   1 → Board Exam (10th/12th)")
    print("   2 → College Semester Exam")
    print("   3 → Competitive Exam (JEE/NEET/UPSC etc)")
    print("   4 → University Exam")
    print("   5 → Custom")

    exam_type_map = {
        '1': 'Board Exam',
        '2': 'College Semester Exam',
        '3': 'Competitive Exam',
        '4': 'University Exam',
        '5': 'Custom'
    }
    exam_type = exam_type_map.get(
        input("\nChoice (1-5): ").strip(), 'College Exam')

    exam_name = input(f"\n📋 Exam name (e.g. JEE Mains, B.Tech Sem 3): ").strip()
    exam_date = input("📅 Exam date (DD/MM/YYYY): ").strip()

    # Subjects
    print("\n📚 Subjects list karo (comma separated):")
    print("   Example: Physics, Chemistry, Maths, English")
    subjects_input = input("Subjects: ").strip()
    subjects = [s.strip() for s in subjects_input.split(',')]

    # Study hours
    print("\n⏰ Daily study hours available:")
    print("   1 → 2-3 hours (Light)")
    print("   2 → 4-5 hours (Moderate)")
    print("   3 → 6-8 hours (Intense)")
    print("   4 → Custom")

    hours_map = {'1': 3, '2': 5, '3': 7, '4': 0}
    hours_choice = input("\nChoice (1-4): ").strip()

    if hours_choice == '4':
        daily_hours = int(input("Kitne hours: ").strip() or "4")
    else:
        daily_hours = hours_map.get(hours_choice, 4)

    # Weak subjects
    print(f"\n😰 Weak subjects? (comma separated, ya Enter skip karo):")
    weak_input = input("Weak subjects: ").strip()
    weak_subjects = [s.strip() for s in weak_input.split(',')] if weak_input else []

    # Strong subjects
    print(f"\n💪 Strong subjects? (comma separated, ya Enter skip karo):")
    strong_input = input("Strong subjects: ").strip()
    strong_subjects = [s.strip() for s in strong_input.split(',')] if strong_input else []

    # Current preparation level
    print("\n📊 Current preparation level:")
    print("   1 → Beginner (abhi start kar raha hun)")
    print("   2 → Intermediate (thoda hua hai)")
    print("   3 → Advanced (zyaadatar ho gaya)")

    prep_map = {
        '1': 'Beginner',
        '2': 'Intermediate',
        '3': 'Advanced'
    }
    prep_level = prep_map.get(input("\nChoice (1-3): ").strip(), 'Intermediate')

    # Study style
    print("\n🎯 Study style:")
    print("   1 → Visual (diagrams, mind maps)")
    print("   2 → Reading (notes, books)")
    print("   3 → Practice (problems, MCQs)")
    print("   4 → Mixed")

    style_map = {
        '1': 'Visual learner',
        '2': 'Reading-based learner',
        '3': 'Practice-based learner',
        '4': 'Mixed learner'
    }
    study_style = style_map.get(input("\nChoice (1-4): ").strip(), 'Mixed learner')

    # Extra info
    print("\n📝 Koi aur information? (optional, Enter skip):")
    extra = input("Extra info: ").strip()

    # Data collect
    planner_data = {
        'name': name,
        'exam_type': exam_type,
        'exam_name': exam_name,
        'exam_date': exam_date,
        'subjects': subjects,
        'daily_hours': daily_hours,
        'weak_subjects': weak_subjects,
        'strong_subjects': strong_subjects,
        'prep_level': prep_level,
        'study_style': study_style,
        'extra': extra
    }

    print(f"\n✅ Details collected!")
    print(f"   Exam: {exam_name}")
    print(f"   Subjects: {', '.join(subjects)}")
    print(f"   Daily hours: {daily_hours}")

    return planner_data

print("✅ Study planner input ready!")

#@title AI Study Plan Generator
from datetime import datetime, timedelta

def generate_study_plan(planner_data):
    """Groq se complete study plan banao"""

    print("\n🤔 AI study plan bana raha hai...")

    # Days calculate karo
    try:
        exam_date = datetime.strptime(planner_data['exam_date'], '%d/%m/%Y')
        today = datetime.now()
        days_left = (exam_date - today).days
    except:
        days_left = 30

    prompt = f"""Create a comprehensive study plan for:

Student: {planner_data['name']}
Exam: {planner_data['exam_name']} ({planner_data['exam_type']})
Exam Date: {planner_data['exam_date']}
Days Left: {days_left} days
Subjects: {', '.join(planner_data['subjects'])}
Daily Study Hours: {planner_data['daily_hours']} hours
Weak Subjects: {', '.join(planner_data['weak_subjects']) if planner_data['weak_subjects'] else 'None mentioned'}
Strong Subjects: {', '.join(planner_data['strong_subjects']) if planner_data['strong_subjects'] else 'None mentioned'}
Current Level: {planner_data['prep_level']}
Study Style: {planner_data['study_style']}
Extra Info: {planner_data['extra'] if planner_data['extra'] else 'None'}

Return ONLY valid JSON:
{{
  "overview": {{
    "total_days": {days_left},
    "daily_hours": {planner_data['daily_hours']},
    "total_study_hours": {days_left * planner_data['daily_hours']},
    "strategy": "Overall study strategy in 2-3 sentences",
    "phases": [
      {{
        "name": "Phase 1 name",
        "duration": "X weeks",
        "focus": "What to focus on",
        "goal": "What to achieve"
      }}
    ]
  }},
  "subject_plans": [
    {{
      "subject": "subject name",
      "priority": "High/Medium/Low",
      "daily_time": "X hours",
      "weekly_time": "X hours",
      "topics": ["Topic 1", "Topic 2", "Topic 3"],
      "resources": ["Resource 1", "Resource 2"],
      "tips": ["Tip 1", "Tip 2"],
      "milestone": "What to achieve in 2 weeks"
    }}
  ],
  "weekly_schedule": {{
    "Monday": [
      {{"time": "9:00 AM - 11:00 AM", "subject": "Subject", "topic": "Topic", "activity": "Read/Practice/Revise"}}
    ],
    "Tuesday": [],
    "Wednesday": [],
    "Thursday": [],
    "Friday": [],
    "Saturday": [],
    "Sunday": ["Rest + Light revision"]
  }},
  "daily_routine": {{
    "morning": "Morning routine and study plan",
    "afternoon": "Afternoon study plan",
    "evening": "Evening study plan",
    "night": "Night revision plan",
    "breaks": "Break schedule"
  }},
  "revision_strategy": {{
    "daily_revision": "Daily revision plan",
    "weekly_revision": "Weekly revision plan",
    "last_week": "Last week strategy",
    "last_day": "Last day strategy"
  }},
  "tips": [
    "Study tip 1",
    "Study tip 2",
    "Study tip 3",
    "Study tip 4",
    "Study tip 5"
  ],
  "motivation": "Motivational message for the student",
  "emergency_plan": "What to do if falling behind schedule"
}}

Make the plan realistic, detailed and personalized for {planner_data['name']}."""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert study coach and academic planner. Create detailed, realistic study plans. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=4000,
        temperature=0.6
    )

    result = response.choices[0].message.content.strip()

    import json, re
    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            plan = json.loads(json_match.group())
            print("✅ Study plan ready!")
            return plan, days_left
    except Exception as e:
        print(f"⚠️ Error: {e}")

    return {}, days_left

print("✅ Study plan generator ready!")

#@title Study Plan PDF Builder
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.colors import HexColor, white
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable, PageBreak
from reportlab.lib.units import cm
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_JUSTIFY
from datetime import datetime

def build_study_plan_pdf(plan, planner_data, days_left, save_path=None):
    """Study plan PDF banao"""

    name = planner_data.get('name', 'Student')
    if not save_path:
        save_path = f'/content/{name}_Study_Plan_MK-AI.pdf'

    # Theme
    theme = {
        'primary': '#1A237E',
        'accent': '#1976D2',
        'light': '#E3F2FD',
        'green': '#2E7D32',
        'orange': '#E65100',
        'red': '#C62828'
    }

    doc = SimpleDocTemplate(
        save_path, pagesize=A4,
        rightMargin=2*cm, leftMargin=2*cm,
        topMargin=2*cm, bottomMargin=2*cm
    )

    story = []

    # Styles
    title_style = ParagraphStyle('Title',
        fontSize=26, fontName='Helvetica-Bold',
        textColor=HexColor(theme['primary']),
        alignment=TA_CENTER, spaceAfter=6)

    subtitle_style = ParagraphStyle('Sub',
        fontSize=13, fontName='Helvetica',
        textColor=HexColor(theme['accent']),
        alignment=TA_CENTER, spaceAfter=4)

    section_style = ParagraphStyle('Section',
        fontSize=12, fontName='Helvetica-Bold',
        textColor=white)

    body_style = ParagraphStyle('Body',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor('#212121'),
        spaceAfter=4, leading=16)

    bullet_style = ParagraphStyle('Bullet',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor('#212121'),
        leftIndent=15, spaceAfter=3)

    def add_section(title, color=None):
        c = color or theme['primary']
        data = [[Paragraph(f'<b>{title}</b>', section_style)]]
        t = Table(data, colWidths=[17*cm], rowHeights=[0.65*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(c)),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.15*cm))

    # ===== HEADER =====
    story.append(Paragraph(f"📚 Study Plan", title_style))
    story.append(Paragraph(f"{name} | {planner_data['exam_name']}", subtitle_style))
    story.append(HRFlowable(width="100%", thickness=3,
                            color=HexColor(theme['primary'])))
    story.append(Spacer(1, 0.2*cm))

    # ===== STATS BOX =====
    overview = plan.get('overview', {})
    stats_data = [[
        Paragraph(f'<font color="white"><b>📅 Days Left</b><br/>{days_left}</font>',
                 ParagraphStyle('s', fontSize=11, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>⏰ Daily Hours</b><br/>{planner_data["daily_hours"]}</font>',
                 ParagraphStyle('s', fontSize=11, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>📚 Subjects</b><br/>{len(planner_data["subjects"])}</font>',
                 ParagraphStyle('s', fontSize=11, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>⚡ Level</b><br/>{planner_data["prep_level"]}</font>',
                 ParagraphStyle('s', fontSize=11, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
    ]]

    stats_table = Table(stats_data,
                       colWidths=[4.25*cm]*4, rowHeights=[1.2*cm])
    stats_table.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (0,-1), HexColor(theme['primary'])),
        ('BACKGROUND', (1,0), (1,-1), HexColor(theme['accent'])),
        ('BACKGROUND', (2,0), (2,-1), HexColor(theme['green'])),
        ('BACKGROUND', (3,0), (3,-1), HexColor(theme['orange'])),
        ('ALIGN', (0,0), (-1,-1), 'CENTER'),
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
    ]))
    story.append(stats_table)
    story.append(Spacer(1, 0.3*cm))

    # ===== STRATEGY =====
    if overview.get('strategy'):
        add_section('🎯 OVERALL STRATEGY')
        box = [[Paragraph(overview['strategy'], body_style)]]
        t = Table(box, colWidths=[17*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['light'])),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('TOPPADDING', (0,0), (-1,-1), 8),
            ('BOTTOMPADDING', (0,0), (-1,-1), 8),
            ('BOX', (0,0), (-1,-1), 0.5, HexColor(theme['accent'])),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.2*cm))

    # ===== PHASES =====
    phases = overview.get('phases', [])
    if phases:
        add_section('📊 STUDY PHASES')
        phase_data = [[
            Paragraph('<b>Phase</b>', ParagraphStyle('ph', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Duration</b>', ParagraphStyle('ph', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Focus</b>', ParagraphStyle('ph', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Goal</b>', ParagraphStyle('ph', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
        ]]

        for phase in phases:
            phase_data.append([
                Paragraph(phase.get('name', ''), body_style),
                Paragraph(phase.get('duration', ''), body_style),
                Paragraph(phase.get('focus', ''), body_style),
                Paragraph(phase.get('goal', ''), body_style),
            ])

        phase_table = Table(phase_data,
                           colWidths=[3.5*cm, 3*cm, 5*cm, 5.5*cm])
        phase_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), HexColor(theme['accent'])),
            ('BACKGROUND', (0,1), (-1,-1), HexColor(theme['light'])),
            ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['accent'])),
            ('LEFTPADDING', (0,0), (-1,-1), 6),
            ('TOPPADDING', (0,0), (-1,-1), 5),
            ('BOTTOMPADDING', (0,0), (-1,-1), 5),
            ('VALIGN', (0,0), (-1,-1), 'TOP'),
        ]))
        story.append(phase_table)
        story.append(Spacer(1, 0.3*cm))

    # ===== SUBJECT PLANS =====
    subject_plans = plan.get('subject_plans', [])
    if subject_plans:
        story.append(PageBreak())
        add_section('📚 SUBJECT-WISE PLAN')

        for subj in subject_plans:
            priority = subj.get('priority', 'Medium')
            priority_color = {
                'High': theme['red'],
                'Medium': theme['orange'],
                'Low': theme['green']
            }.get(priority, theme['accent'])

            # Subject header
            subj_data = [[
                Paragraph(f'<font color="white"><b>{subj.get("subject", "")}</b></font>',
                         ParagraphStyle('sh', fontSize=11, textColor=white,
                                       fontName='Helvetica-Bold')),
                Paragraph(f'<font color="white">Priority: {priority} | Daily: {subj.get("daily_time", "")}</font>',
                         ParagraphStyle('sh2', fontSize=10, textColor=white,
                                       fontName='Helvetica'))
            ]]
            subj_table = Table(subj_data, colWidths=[7*cm, 10*cm],
                              rowHeights=[0.6*cm])
            subj_table.setStyle(TableStyle([
                ('BACKGROUND', (0,0), (0,-1), HexColor(priority_color)),
                ('BACKGROUND', (1,0), (1,-1), HexColor(theme['accent'])),
                ('LEFTPADDING', (0,0), (-1,-1), 8),
                ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ]))
            story.append(subj_table)

            # Topics + Tips
            topics = subj.get('topics', [])
            tips = subj.get('tips', [])

            if topics:
                topics_text = ' | '.join(topics[:5])
                story.append(Paragraph(
                    f"<b>Topics:</b> {topics_text}", body_style))

            if tips:
                for tip in tips[:2]:
                    story.append(Paragraph(f"💡 {tip}", bullet_style))

            if subj.get('milestone'):
                story.append(Paragraph(
                    f"🎯 <b>2-week goal:</b> {subj['milestone']}", body_style))

            story.append(Spacer(1, 0.2*cm))

    # ===== WEEKLY SCHEDULE =====
    weekly = plan.get('weekly_schedule', {})
    if weekly:
        story.append(PageBreak())
        add_section('📅 WEEKLY SCHEDULE')

        days = ['Monday', 'Tuesday', 'Wednesday', 'Thursday',
                'Friday', 'Saturday', 'Sunday']

        for day in days:
            if day in weekly and weekly[day]:
                day_color = '#E8EAF6' if day != 'Sunday' else '#E8F5E9'

                story.append(Paragraph(
                    f"<b>{day}</b>",
                    ParagraphStyle('day', fontSize=11, fontName='Helvetica-Bold',
                                  textColor=HexColor(theme['primary']),
                                  spaceAfter=3)))

                slots = weekly[day]
                if isinstance(slots, list):
                    for slot in slots[:4]:
                        if isinstance(slot, dict):
                            time = slot.get('time', '')
                            subj = slot.get('subject', '')
                            topic = slot.get('topic', '')
                            activity = slot.get('activity', '')

                            slot_data = [[
                                Paragraph(time, ParagraphStyle('t', fontSize=9,
                                    fontName='Helvetica-Bold',
                                    textColor=HexColor(theme['primary']))),
                                Paragraph(f"{subj}: {topic}",
                                         ParagraphStyle('t2', fontSize=9,
                                             fontName='Helvetica')),
                                Paragraph(activity, ParagraphStyle('t3',
                                    fontSize=9, fontName='Helvetica',
                                    textColor=HexColor(theme['accent'])))
                            ]]
                            slot_table = Table(slot_data,
                                             colWidths=[4*cm, 9*cm, 4*cm])
                            slot_table.setStyle(TableStyle([
                                ('BACKGROUND', (0,0), (-1,-1),
                                 HexColor(day_color)),
                                ('GRID', (0,0), (-1,-1), 0.3,
                                 HexColor(theme['accent'])),
                                ('LEFTPADDING', (0,0), (-1,-1), 6),
                                ('TOPPADDING', (0,0), (-1,-1), 3),
                                ('BOTTOMPADDING', (0,0), (-1,-1), 3),
                            ]))
                            story.append(slot_table)
                        elif isinstance(slot, str):
                            story.append(Paragraph(f"   {slot}", body_style))

                story.append(Spacer(1, 0.2*cm))

    # ===== DAILY ROUTINE =====
    routine = plan.get('daily_routine', {})
    if routine:
        story.append(PageBreak())
        add_section('⏰ DAILY ROUTINE')

        routine_parts = [
            ('🌅 Morning', routine.get('morning', '')),
            ('☀️ Afternoon', routine.get('afternoon', '')),
            ('🌆 Evening', routine.get('evening', '')),
            ('🌙 Night', routine.get('night', '')),
            ('☕ Breaks', routine.get('breaks', ''))
        ]

        for label, content in routine_parts:
            if content:
                routine_data = [[
                    Paragraph(f'<b>{label}</b>',
                             ParagraphStyle('rl', fontSize=10,
                                           fontName='Helvetica-Bold',
                                           textColor=HexColor(theme['primary']))),
                    Paragraph(content, body_style)
                ]]
                routine_table = Table(routine_data,
                                     colWidths=[3.5*cm, 13.5*cm])
                routine_table.setStyle(TableStyle([
                    ('BACKGROUND', (0,0), (0,-1),
                     HexColor(theme['light'])),
                    ('GRID', (0,0), (-1,-1), 0.3,
                     HexColor(theme['accent'])),
                    ('LEFTPADDING', (0,0), (-1,-1), 8),
                    ('TOPPADDING', (0,0), (-1,-1), 5),
                    ('BOTTOMPADDING', (0,0), (-1,-1), 5),
                    ('VALIGN', (0,0), (-1,-1), 'TOP'),
                ]))
                story.append(routine_table)

        story.append(Spacer(1, 0.3*cm))

    # ===== REVISION STRATEGY =====
    revision = plan.get('revision_strategy', {})
    if revision:
        add_section('🔄 REVISION STRATEGY', theme['green'])

        rev_parts = [
            ('Daily', revision.get('daily_revision', '')),
            ('Weekly', revision.get('weekly_revision', '')),
            ('Last Week', revision.get('last_week', '')),
            ('Last Day', revision.get('last_day', ''))
        ]

        for label, content in rev_parts:
            if content:
                story.append(Paragraph(
                    f"<b>{label}:</b> {content}", body_style))

        story.append(Spacer(1, 0.2*cm))

    # ===== TIPS =====
    tips = plan.get('tips', [])
    if tips:
        add_section('💡 STUDY TIPS', theme['orange'])
        for i, tip in enumerate(tips, 1):
            story.append(Paragraph(f"{i}. {tip}", bullet_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== MOTIVATION =====
    if plan.get('motivation'):
        add_section('🔥 MOTIVATION', theme['red'])
        box = [[Paragraph(plan['motivation'], body_style)]]
        t = Table(box, colWidths=[17*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor('#FFF8E1')),
            ('LEFTPADDING', (0,0), (-1,-1), 12),
            ('TOPPADDING', (0,0), (-1,-1), 10),
            ('BOTTOMPADDING', (0,0), (-1,-1), 10),
            ('BOX', (0,0), (-1,-1), 1, HexColor(theme['orange'])),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.2*cm))

    # ===== EMERGENCY PLAN =====
    if plan.get('emergency_plan'):
        add_section('🚨 EMERGENCY PLAN (If falling behind)')
        story.append(Paragraph(plan['emergency_plan'], body_style))

    # ===== FOOTER =====
    story.append(Spacer(1, 0.3*cm))
    story.append(HRFlowable(width="100%", thickness=1,
                            color=HexColor(theme['primary'])))
    story.append(Paragraph(
        f'Generated by MK-AI | Made by Mushab Khan | {datetime.now().strftime("%B %d, %Y")}',
        ParagraphStyle('footer', fontSize=8, fontName='Helvetica',
                      textColor=HexColor(theme['accent']),
                      alignment=TA_CENTER)))

    doc.build(story)
    print(f"✅ Study plan PDF saved: {save_path}")
    return save_path

print("✅ Study plan PDF builder ready!")

