from google.colab import files

def master_study_planner():
    """Full Study Planner — Input → AI Plan → PDF"""

    print("🚀 MK-AI Study Planner Starting...\n")

    # Input lo
    planner_data = study_planner_agent()

    # AI plan banao
    plan, days_left = generate_study_plan(planner_data)

    if not plan:
        print("❌ Plan generate nahi hua!")
        return

    # Display overview
    overview = plan.get('overview', {})
    print("\n" + "="*60)
    print("📊 STUDY PLAN OVERVIEW")
    print("="*60)
    print(f"📅 Days Left: {days_left}")
    print(f"⏰ Total Hours: {overview.get('total_study_hours', 0)}")
    print(f"🎯 Strategy: {overview.get('strategy', '')[:100]}...")

    phases = overview.get('phases', [])
    if phases:
        print(f"\n📊 Phases:")
        for phase in phases:
            print(f"   → {phase.get('name', '')}: {phase.get('duration', '')} - {phase.get('focus', '')}")

    tips = plan.get('tips', [])
    if tips:
        print(f"\n💡 Top Tips:")
        for tip in tips[:3]:
            print(f"   • {tip}")

    if plan.get('motivation'):
        print(f"\n🔥 Motivation: {plan['motivation'][:100]}...")

    # PDF banao
    print("\n📄 PDF bana raha hai...")
    name = planner_data.get('name', 'Student')
    save_path = f'/content/{name}_Study_Plan_MK-AI.pdf'
    build_study_plan_pdf(plan, planner_data, days_left, save_path)

    # Download
    files.download(save_path)
    print("✅ Study Plan PDF download ho gaya!")

    print("\n🎉 Study Plan ready hai bhai!")
    print(f"   📅 {days_left} din bacha hai exam mein")
    print(f"   💪 Mehnat karo — success milegi!")

    return plan

print("✅ Master Study Planner ready!")

