from google.colab import files

def master_business_planner():
    """Full Business Planner Agent"""

    print("🚀 MK-AI Business Planner Starting...\n")

    # Input lo
    data = get_business_input()

    # Business plan generate karo
    plan = generate_business_plan(data)

    if not plan:
        print("❌ Plan generate nahi hua!")
        return

    # Display overview
    print("\n" + "="*60)
    print("📊 BUSINESS PLAN OVERVIEW")
    print("="*60)

    score = plan.get('viability_score', 0)
    print(f"✅ Viability Score: {score}/100")
    print(f"📋 {plan.get('viability_feedback', '')[:100]}")

    names = plan.get('business_name_suggestions', [])
    if names:
        print(f"\n💡 Business Name Suggestions: {', '.join(names[:3])}")

    first_steps = plan.get('first_steps', [])
    if first_steps:
        print(f"\n👣 First Steps:")
        for step in first_steps[:3]:
            print(f"   → {step}")

    # PDF banao
    print("\n📄 Business Plan PDF bana raha hai...")
    name = data.get('name', 'Business')
    save_path = f'/content/{name}_Business_Plan_MK-AI.pdf'
    build_business_plan_pdf(plan, data, save_path)
    files.download(save_path)
    print("✅ Business Plan PDF download ho gaya!")

    # Pitch deck
    pitch = input("\n🎨 Pitch Deck (PPT) bhi chahiye? (haan/nahi): ").strip().lower()
    if pitch in ['haan', 'ha', 'y', 'yes', 'h']:
        generate_pitch_deck(plan, data)

    print("\n🎉 Business Plan ready hai bhai!")
    print(f"   📊 Viability: {score}/100")
    print(f"   💪 Pehla kadam uthao — success milegi!")

    return plan

print("✅ Master Business Planner ready!")

