#@title Social Media Input Handler
import json, re

# Brand voice save karo
BRAND_VOICE = {}

def setup_brand_voice():
    """Brand voice ek baar define karo"""

    print("="*60)
    print("🎨 BRAND VOICE SETUP")
    print("="*60)

    brand_name = input("\n🏷️ Brand/Personal name: ").strip()
    niche = input("📌 Niche/Industry: ").strip()

    print("\n🎯 Brand Personality:")
    print("   1 → Professional & Authoritative")
    print("   2 → Fun & Casual")
    print("   3 → Inspirational & Motivating")
    print("   4 → Educational & Informative")
    print("   5 → Bold & Controversial")

    personality_map = {
        '1': 'Professional and authoritative',
        '2': 'Fun, casual and relatable',
        '3': 'Inspirational and motivating',
        '4': 'Educational and informative',
        '5': 'Bold and controversial'
    }
    personality = personality_map.get(
        input("\nChoice (1-5): ").strip(),
        'Professional and informative')

    target_audience = input("\n👥 Target audience: ").strip()

    BRAND_VOICE.update({
        'brand_name': brand_name,
        'niche': niche,
        'personality': personality,
        'target_audience': target_audience
    })

    print(f"\n✅ Brand voice saved!")
    print(f"   Brand: {brand_name}")
    print(f"   Niche: {niche}")
    print(f"   Style: {personality}")

    return BRAND_VOICE

def get_social_media_input():
    """Social media post details lo"""

    print("\n" + "="*60)
    print("📱 MK-AI SOCIAL MEDIA POST MAKER")
    print("="*60)

    # Platform
    print("\n📱 Platform choose karo:")
    print("   1 → Instagram")
    print("   2 → Twitter/X")
    print("   3 → LinkedIn")
    print("   4 → Facebook")
    print("   5 → YouTube Description")
    print("   6 → WhatsApp Status")
    print("   7 → All Platforms")

    platform_map = {
        '1': 'Instagram',
        '2': 'Twitter/X',
        '3': 'LinkedIn',
        '4': 'Facebook',
        '5': 'YouTube',
        '6': 'WhatsApp',
        '7': 'All Platforms'
    }
    platform = platform_map.get(
        input("\nChoice (1-7): ").strip(), 'Instagram')

    # Post type
    print("\n📝 Post Type:")
    print("   1 → Single Post")
    print("   2 → Carousel (Multiple slides)")
    print("   3 → Story Ideas")
    print("   4 → Thread (Twitter)")
    print("   5 → Reel Caption")
    print("   6 → Content Calendar (30 days)")

    post_type_map = {
        '1': 'single post',
        '2': 'carousel',
        '3': 'story',
        '4': 'thread',
        '5': 'reel caption',
        '6': 'content calendar'
    }
    post_type = post_type_map.get(
        input("\nChoice (1-6): ").strip(), 'single post')

    # Topic
    topic = input("\n💡 Topic/Idea kya hai?: ").strip()

    # Tone
    print("\n🎭 Tone:")
    print("   1 → Professional")
    print("   2 → Funny/Humorous")
    print("   3 → Motivational")
    print("   4 → Educational")
    print("   5 → Promotional")
    print("   6 → Storytelling")
    print("   7 → Controversial")

    tone_map = {
        '1': 'professional',
        '2': 'funny and humorous',
        '3': 'motivational and inspiring',
        '4': 'educational and informative',
        '5': 'promotional and persuasive',
        '6': 'storytelling',
        '7': 'controversial and thought-provoking'
    }
    tone = tone_map.get(
        input("\nChoice (1-7): ").strip(), 'professional')

    # Language
    print("\n🌐 Language:")
    print("   1 → English")
    print("   2 → Hindi")
    print("   3 → Hinglish")
    print("   4 → Bilingual (English + Hindi)")

    lang_map = {
        '1': 'English',
        '2': 'Hindi',
        '3': 'Hinglish',
        '4': 'Bilingual'
    }
    language = lang_map.get(
        input("\nChoice (1-4): ").strip(), 'Hinglish')

    # Extra info
    extra = input("\n📝 Extra info (optional): ").strip()

    return {
        'platform': platform,
        'post_type': post_type,
        'topic': topic,
        'tone': tone,
        'language': language,
        'extra': extra,
        'brand': BRAND_VOICE
    }

