#@title AI Post Generator
def generate_social_posts(input_data):
    """Groq se social media posts banao"""

    platform = input_data['platform']
    post_type = input_data['post_type']
    topic = input_data['topic']
    tone = input_data['tone']
    language = input_data['language']
    brand = input_data.get('brand', {})

    lang_rule = {
        'English': 'Write in English only.',
        'Hindi': 'Write in Hindi (Devanagari script).',
        'Hinglish': 'Write in Hinglish (Hindi+English Roman mix). Very casual and relatable.',
        'Bilingual': 'Write in both English and Hindi/Hinglish.'
    }.get(language, 'Write in Hinglish.')

    platform_rules = {
        'Instagram': 'Max 2200 chars. Use line breaks. Heavy emoji use. 30 hashtags.',
        'Twitter/X': 'Max 280 chars per tweet. Punchy and concise.',
        'LinkedIn': 'Professional. Max 3000 chars. Minimal emojis. Industry insights.',
        'Facebook': 'Conversational. Max 500 chars ideal. Community focused.',
        'YouTube': 'SEO optimized description. Include keywords. Max 5000 chars.',
        'WhatsApp': 'Very short. Max 700 chars. Personal and direct.',
        'All Platforms': 'Create versions for Instagram, Twitter, LinkedIn.'
    }.get(platform, 'Platform appropriate.')

    brand_context = f"""
Brand: {brand.get('brand_name', 'Personal')}
Niche: {brand.get('niche', 'General')}
Personality: {brand.get('personality', 'Professional')}
Audience: {brand.get('target_audience', 'General')}""" if brand else ""

    if post_type == 'content calendar':
        prompt = f"""Create a 30-day social media content calendar for {platform}.

Topic/Niche: {topic}
Tone: {tone}
Language: {lang_rule}
{brand_context}

Return ONLY valid JSON:
{{
  "calendar": [
    {{
      "day": 1,
      "date": "Monday",
      "theme": "Post theme",
      "topic": "Specific topic",
      "post_type": "Single/Carousel/Reel/Story",
      "hook": "Attention grabbing first line",
      "caption": "Full caption",
      "hashtags": ["#tag1", "#tag2"],
      "best_time": "Best posting time",
      "engagement_tip": "How to boost engagement"
    }}
  ],
  "weekly_themes": {{
    "Monday": "Motivation Monday",
    "Tuesday": "Tips Tuesday",
    "Wednesday": "Wisdom Wednesday",
    "Thursday": "Throwback Thursday",
    "Friday": "Feature Friday",
    "Saturday": "Story Saturday",
    "Sunday": "Sunday Funday"
  }},
  "tips": ["Tip 1", "Tip 2", "Tip 3"]
}}"""

    elif post_type == 'carousel':
        prompt = f"""Create a carousel post for {platform}.

Topic: {topic}
Tone: {tone}
Language: {lang_rule}
{brand_context}

Return ONLY valid JSON:
{{
  "title": "Carousel title",
  "slides": [
    {{
      "slide_number": 1,
      "type": "hook/content/cta",
      "headline": "Slide headline",
      "content": "Slide content",
      "visual_suggestion": "What image/design to use"
    }}
  ],
  "caption": "Main post caption",
  "hashtags": ["#tag1", "#tag2", "#tag3"],
  "cta": "Call to action"
}}"""

    elif post_type == 'thread':
        prompt = f"""Create a Twitter/X thread about: {topic}

Tone: {tone}
Language: {lang_rule}
{brand_context}

Return ONLY valid JSON:
{{
  "thread": [
    {{
      "tweet_number": 1,
      "content": "Tweet content (max 280 chars)",
      "type": "hook/content/insight/cta"
    }}
  ],
  "hook_tweet": "Most engaging first tweet",
  "hashtags": ["#tag1", "#tag2"]
}}"""

    else:
        prompt = f"""Create a {post_type} for {platform} about: {topic}

Tone: {tone}
Language: {lang_rule}
Platform rules: {platform_rules}
{brand_context}
Extra info: {input_data.get('extra', 'None')}

Return ONLY valid JSON:
{{
  "hooks": [
    "Hook option 1 — attention grabbing",
    "Hook option 2 — question based",
    "Hook option 3 — bold statement",
    "Hook option 4 — story based",
    "Hook option 5 — controversial"
  ],
  "posts": [
    {{
      "version": "Version A",
      "caption": "Full post caption",
      "emojis_used": ["emoji1", "emoji2"],
      "viral_formula": "Formula used",
      "estimated_engagement": "High/Medium/Low"
    }},
    {{
      "version": "Version B",
      "caption": "Alternative version",
      "emojis_used": ["emoji1"],
      "viral_formula": "Different formula",
      "estimated_engagement": "High/Medium/Low"
    }}
  ],
  "hashtags": {{
    "trending": ["#tag1", "#tag2", "#tag3"],
    "niche": ["#tag4", "#tag5", "#tag6"],
    "branded": ["#tag7"],
    "all_30": ["#tag1", "#tag2", "#tag3", "#tag4", "#tag5", "#tag6", "#tag7", "#tag8", "#tag9", "#tag10", "#tag11", "#tag12", "#tag13", "#tag14", "#tag15", "#tag16", "#tag17", "#tag18", "#tag19", "#tag20", "#tag21", "#tag22", "#tag23", "#tag24", "#tag25", "#tag26", "#tag27", "#tag28", "#tag29", "#tag30"]
  }},
  "cta_options": [
    "CTA option 1",
    "CTA option 2",
    "CTA option 3"
  ],
  "story_ideas": [
    "Story slide 1 idea",
    "Story slide 2 idea",
    "Story slide 3 idea"
  ],
  "best_posting_time": "Best time to post on {platform}",
  "engagement_prediction": "Why this post will perform well",
  "ab_test_recommendation": "Which version to post first and why",
  "bio_suggestion": "Updated bio based on this content style"
}}"""

    print(f"🤔 AI {post_type} generate kar raha hai...")

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are a viral social media expert. Create engaging, platform-optimized content. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=4000,
        temperature=0.8
    )

    result = response.choices[0].message.content.strip()

    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            posts = json.loads(json_match.group())
            print("✅ Posts generated!")
            return posts
    except Exception as e:
        print(f"⚠️ Error: {e}")

    return {}

print("✅ AI post generator ready!")

#@title Trending Topics Finder
def get_trending_topics(niche):
    """Web search se trending topics dhundo"""

    print(f"🔍 Trending topics dhundh raha hai: {niche}")

    try:
        results = web_search(f"{niche} trending topics India 2025 social media")

        if results:
            content = '\n'.join([r['body'] for r in results[:3]])

            response = groq_client.chat.completions.create(
                model="llama-3.3-70b-versatile",
                messages=[
                    {"role": "system", "content": "Extract trending topics. Return JSON only: {\"trending\": [\"topic1\", \"topic2\", \"topic3\", \"topic4\", \"topic5\"]}"},
                    {"role": "user", "content": f"Niche: {niche}\nContent: {content[:2000]}"}
                ],
                max_tokens=200,
                temperature=0.3
            )

            result = json.loads(re.search(r'\{.*\}',
                response.choices[0].message.content,
                re.DOTALL).group())

            topics = result.get('trending', [])
            print(f"✅ {len(topics)} trending topics mile!")
            return topics
    except:
        pass

    return [f"{niche} tips", f"{niche} trends", f"{niche} secrets",
            f"{niche} mistakes", f"{niche} beginners guide"]

print("✅ Trending topics finder ready!")

#@title Display + Save Posts
from google.colab import files

def display_and_save_posts(posts, input_data):
    """Posts display karo aur save karo"""

    post_type = input_data['post_type']
    platform = input_data['platform']
    topic = input_data['topic']

    print("\n" + "="*60)
    print(f"📱 {platform.upper()} — {post_type.upper()}")
    print("="*60)

    if post_type == 'content calendar':
        calendar = posts.get('calendar', [])
        print(f"\n📅 30-Day Content Calendar:")

        weekly_themes = posts.get('weekly_themes', {})
        if weekly_themes:
            print("\n🗓️ Weekly Themes:")
            for day, theme in weekly_themes.items():
                print(f"   {day}: {theme}")

        print(f"\n📋 First 7 Days Preview:")
        for item in calendar[:7]:
            print(f"\n   Day {item.get('day', '')}: {item.get('date', '')}")
            print(f"   Theme: {item.get('theme', '')}")
            print(f"   Topic: {item.get('topic', '')}")
            print(f"   Hook: {item.get('hook', '')[:80]}...")
            print(f"   Best Time: {item.get('best_time', '')}")

    elif post_type == 'carousel':
        slides = posts.get('slides', [])
        print(f"\n📊 {len(slides)} Slides:")
        for slide in slides:
            print(f"\n   Slide {slide.get('slide_number', '')}: {slide.get('type', '').upper()}")
            print(f"   Headline: {slide.get('headline', '')}")
            print(f"   Content: {slide.get('content', '')[:100]}...")

        print(f"\n📝 Caption:\n{posts.get('caption', '')}")
        print(f"\n🏷️ Hashtags: {' '.join(posts.get('hashtags', [])[:10])}")

    elif post_type == 'thread':
        thread = posts.get('thread', [])
        print(f"\n🧵 Thread ({len(thread)} tweets):")
        for tweet in thread:
            print(f"\n   [{tweet.get('tweet_number', '')}] {tweet.get('type', '').upper()}")
            print(f"   {tweet.get('content', '')}")

    else:
        # Single post / Reel caption
        hooks = posts.get('hooks', [])
        if hooks:
            print("\n🪝 5 Hook Options:")
            for i, hook in enumerate(hooks, 1):
                print(f"   {i}. {hook}")

        post_versions = posts.get('posts', [])
        for post in post_versions:
            print(f"\n📝 {post.get('version', 'Version')}:")
            print(f"   Formula: {post.get('viral_formula', '')}")
            print(f"   Engagement: {post.get('estimated_engagement', '')}")
            print(f"\n{post.get('caption', '')}")

        hashtags = posts.get('hashtags', {})
        if hashtags:
            print(f"\n🏷️ All 30 Hashtags:")
            all_tags = hashtags.get('all_30', [])
            print(' '.join(all_tags[:30]))

        cta_options = posts.get('cta_options', [])
        if cta_options:
            print(f"\n📢 CTA Options:")
            for cta in cta_options:
                print(f"   → {cta}")

        if posts.get('best_posting_time'):
            print(f"\n⏰ Best Time: {posts['best_posting_time']}")

        if posts.get('ab_test_recommendation'):
            print(f"\n🔬 A/B Test: {posts['ab_test_recommendation']}")

        if posts.get('bio_suggestion'):
            print(f"\n👤 Bio Suggestion:\n{posts['bio_suggestion']}")

        story_ideas = posts.get('story_ideas', [])
        if story_ideas:
            print(f"\n📸 Story Ideas:")
            for idea in story_ideas:
                print(f"   → {idea}")

    # Save karo
    save = input("\n💾 Posts text file mein save karein? (haan/nahi): ").strip().lower()
    if save in ['haan', 'ha', 'y', 'yes', 'h']:
        save_path = f'/content/Social_Posts_{platform}_{topic[:15]}_MK-AI.txt'

        with open(save_path, 'w', encoding='utf-8') as f:
            f.write(f"MK-AI Social Media Posts\n")
            f.write(f"Platform: {platform}\n")
            f.write(f"Topic: {topic}\n")
            f.write(f"Generated: {datetime.now().strftime('%B %d, %Y')}\n")
            f.write("="*60 + "\n\n")
            f.write(json.dumps(posts, indent=2, ensure_ascii=False))

        files.download(save_path)
        print("✅ Posts file download ho gayi!")

print("✅ Display + Save ready!")

#@title Post Performance Predictor
def predict_post_performance(caption, platform, hashtags=[]):
    """AI se post performance predict karwao"""

    print("🔮 Performance predict ho raha hai...")

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are a social media analytics expert. Predict post performance."},
            {"role": "user", "content": f"""Analyze this {platform} post:

Caption: {caption[:500]}
Hashtags: {' '.join(hashtags[:10])}

Return JSON only:
{{
  "engagement_score": 75,
  "reach_potential": "High/Medium/Low",
  "strengths": ["strength 1", "strength 2"],
  "weaknesses": ["weakness 1", "weakness 2"],
  "improvements": ["improvement 1", "improvement 2"],
  "predicted_likes": "X-Y range",
  "predicted_comments": "X-Y range",
  "virality_chance": "High/Medium/Low",
  "best_day_to_post": "Day",
  "best_time_to_post": "Time"
}}"""}
        ],
        max_tokens=500,
        temperature=0.3
    )

    result = response.choices[0].message.content.strip()

    try:
        prediction = json.loads(re.search(r'\{.*\}', result, re.DOTALL).group())

        print("\n📊 PERFORMANCE PREDICTION")
        print("="*40)
        print(f"🎯 Engagement Score: {prediction.get('engagement_score', 0)}/100")
        print(f"📈 Reach Potential: {prediction.get('reach_potential', '')}")
        print(f"🔥 Virality Chance: {prediction.get('virality_chance', '')}")
        print(f"❤️ Predicted Likes: {prediction.get('predicted_likes', '')}")
        print(f"💬 Predicted Comments: {prediction.get('predicted_comments', '')}")
        print(f"📅 Best Day: {prediction.get('best_day_to_post', '')}")
        print(f"⏰ Best Time: {prediction.get('best_time_to_post', '')}")

        improvements = prediction.get('improvements', [])
        if improvements:
            print(f"\n💡 Improvements:")
            for imp in improvements:
                print(f"   → {imp}")

        return prediction
    except:
        print("⚠️ Prediction nahi ho saka")
        return {}

print("✅ Performance predictor ready!")

#@title Master Social Media Agent
from datetime import datetime

def social_media_agent():
    """Full Social Media Post Maker"""

    print("🚀 MK-AI Social Media Agent Starting...\n")

    # Brand voice setup
    setup_brand = input("🎨 Brand voice setup karein? (haan/nahi): ").strip().lower()
    if setup_brand in ['haan', 'ha', 'y', 'yes', 'h']:
        setup_brand_voice()

    # Trending topics check
    if BRAND_VOICE.get('niche'):
        check_trending = input(f"\n🔥 '{BRAND_VOICE['niche']}' ke trending topics dekhein? (haan/nahi): ").strip().lower()
        if check_trending in ['haan', 'ha', 'y', 'yes', 'h']:
            trending = get_trending_topics(BRAND_VOICE['niche'])
            print("\n🔥 Trending Topics:")
            for i, t in enumerate(trending, 1):
                print(f"   {i}. {t}")

            use_trending = input("\nKoi trending topic use karein? (number/nahi): ").strip()
            if use_trending.isdigit():
                idx = int(use_trending) - 1
                if 0 <= idx < len(trending):
                    print(f"✅ Topic selected: {trending[idx]}")

    while True:
        # Input lo
        input_data = get_social_media_input()

        # Posts generate karo
        posts = generate_social_posts(input_data)

        if not posts:
            print("❌ Posts generate nahi hue!")
            continue

        # Display + Save karo
        display_and_save_posts(posts, input_data)

        # Performance predict karo
        if input_data['post_type'] == 'single post':
            predict = input("\n🔮 Performance predict karein? (haan/nahi): ").strip().lower()
            if predict in ['haan', 'ha', 'y', 'yes', 'h']:
                post_versions = posts.get('posts', [])
                if post_versions:
                    caption = post_versions[0].get('caption', '')
                    hashtags = posts.get('hashtags', {}).get('all_30', [])
                    predict_post_performance(caption, input_data['platform'], hashtags)

        # Aur posts banane hain?
        more = input("\n➕ Aur posts banane hain? (haan/nahi): ").strip().lower()
        if more not in ['haan', 'ha', 'y', 'yes', 'h']:
            break

    print("\n🎉 Social Media Posts ready hain bhai!")

print("✅ Master Social Media Agent ready!")

