#@title Meeting Summarizer Input
def get_meeting_input():
    """Meeting details lo"""

    print("="*60)
    print("📋 MK-AI MEETING SUMMARIZER")
    print("="*60)

    print("\n📝 Input Type:")
    print("   1 → Meeting notes paste karo")
    print("   2 → Audio transcript paste karo")
    print("   3 → Meeting description type karo")
    print("   4 → Document/File upload")

    input_type = input("\nChoice (1-4): ").strip()

    meeting_text = ""

    if input_type in ['1', '2', '3']:
        print("\n📝 Meeting content paste karo (phir 'DONE' likho):")
        lines = []
        while True:
            line = input()
            if line.strip().upper() == 'DONE':
                break
            lines.append(line)
        meeting_text = '\n'.join(lines)

    elif input_type == '4':
        from google.colab import files
        print("\n📂 File upload karo:")
        uploaded = files.upload()
        if uploaded:
            filename = list(uploaded.keys())[0]
            filepath = f"/content/{filename}"
            with open(filepath, 'r', encoding='utf-8', errors='ignore') as f:
                meeting_text = f.read()
            print(f"✅ File loaded: {filename}")

    # Meeting details
    meeting_name = input("\n📋 Meeting name/title: ").strip()
    meeting_date = input("📅 Meeting date (DD/MM/YYYY): ").strip()
    attendees = input("👥 Attendees (comma separated): ").strip()

    print("\n🎯 Meeting Type:")
    print("   1 → Team standup")
    print("   2 → Project review")
    print("   3 → Client meeting")
    print("   4 → Strategy meeting")
    print("   5 → Interview")
    print("   6 → General")

    meeting_type_map = {
        '1': 'Team standup',
        '2': 'Project review',
        '3': 'Client meeting',
        '4': 'Strategy meeting',
        '5': 'Interview',
        '6': 'General meeting'
    }
    meeting_type = meeting_type_map.get(
        input("\nChoice (1-6): ").strip(), 'General meeting')

    # Language
    print("\n🌐 Summary Language:")
    print("   1 → Hinglish")
    print("   2 → English")
    print("   3 → Hindi")

    lang_map = {'1': 'Hinglish', '2': 'English', '3': 'Hindi'}
    language = lang_map.get(input("\nChoice (1-3): ").strip(), 'English')

    return {
        'text': meeting_text,
        'name': meeting_name,
        'date': meeting_date,
        'attendees': attendees,
        'type': meeting_type,
        'language': language
    }

print("✅ Meeting input handler ready!")

#@title AI Meeting Summarizer
def summarize_meeting(meeting_data):
    """Groq se meeting summarize karwao"""

    print("\n🤔 AI meeting summarize kar raha hai...")

    lang_rule = {
        'Hinglish': 'Write in Hinglish (Hindi+English Roman mix).',
        'English': 'Write in English only.',
        'Hindi': 'Write in Hindi (Devanagari script).'
    }.get(meeting_data['language'], 'Write in English.')

    prompt = f"""Summarize this {meeting_data['type']} meeting:

Meeting: {meeting_data['name']}
Date: {meeting_data['date']}
Attendees: {meeting_data['attendees']}
Type: {meeting_data['type']}

Meeting Content:
{meeting_data['text'][:5000]}

Language: {lang_rule}

Return ONLY valid JSON:
{{
  "meeting_title": "Meeting title",
  "executive_summary": "2-3 sentence overview",
  "key_discussions": [
    {{
      "topic": "Discussion topic",
      "summary": "What was discussed",
      "outcome": "Decision or conclusion reached"
    }}
  ],
  "decisions_made": [
    {{
      "decision": "Decision made",
      "decided_by": "Who decided",
      "impact": "Impact of this decision"
    }}
  ],
  "action_items": [
    {{
      "task": "Task description",
      "assigned_to": "Person name",
      "deadline": "Deadline",
      "priority": "High/Medium/Low"
    }}
  ],
  "follow_ups": [
    {{
      "item": "Follow up item",
      "responsible": "Who is responsible",
      "due_date": "When"
    }}
  ],
  "blockers": ["Blocker 1", "Blocker 2"],
  "next_meeting": {{
    "suggested_date": "When to meet next",
    "agenda": ["Agenda item 1", "Agenda item 2"]
  }},
  "sentiment": "Positive/Neutral/Negative",
  "meeting_effectiveness": 75,
  "key_quotes": ["Important quote 1", "Important quote 2"],
  "risks_identified": ["Risk 1", "Risk 2"],
  "opportunities": ["Opportunity 1", "Opportunity 2"]
}}"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert meeting facilitator and summarizer. Create comprehensive meeting summaries. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=3000,
        temperature=0.4
    )

    result = response.choices[0].message.content.strip()

    import json, re
    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            summary = json.loads(json_match.group())
            print("✅ Meeting summarized!")
            return summary
    except Exception as e:
        print(f"⚠️ Error: {e}")

    return {}

print("✅ AI meeting summarizer ready!")

#@title Meeting Summary PDF Builder
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.colors import HexColor, white
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, HRFlowable, PageBreak
from reportlab.lib.units import cm
from reportlab.lib.enums import TA_CENTER, TA_LEFT, TA_JUSTIFY
from datetime import datetime

def build_meeting_pdf(summary, meeting_data, save_path=None):
    """Meeting summary PDF banao"""

    name = meeting_data.get('name', 'Meeting')
    if not save_path:
        save_path = f'/content/{name[:20].replace(" ", "_")}_Summary_MK-AI.pdf'

    theme = {
        'primary': '#1A237E',
        'accent': '#1976D2',
        'light': '#E3F2FD',
        'green': '#1B5E20',
        'orange': '#E65100',
        'red': '#C62828',
        'purple': '#4A148C'
    }

    doc = SimpleDocTemplate(
        save_path, pagesize=A4,
        rightMargin=2*cm, leftMargin=2*cm,
        topMargin=2*cm, bottomMargin=2*cm
    )

    story = []

    # Styles
    title_style = ParagraphStyle('Title',
        fontSize=24, fontName='Helvetica-Bold',
        textColor=HexColor(theme['primary']),
        alignment=TA_CENTER, spaceAfter=6)

    subtitle_style = ParagraphStyle('Sub',
        fontSize=11, fontName='Helvetica',
        textColor=HexColor(theme['accent']),
        alignment=TA_CENTER, spaceAfter=4)

    section_style = ParagraphStyle('Section',
        fontSize=12, fontName='Helvetica-Bold',
        textColor=white)

    body_style = ParagraphStyle('Body',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor('#212121'),
        spaceAfter=4, leading=16)

    bullet_style = ParagraphStyle('Bullet',
        fontSize=10, fontName='Helvetica',
        textColor=HexColor('#212121'),
        leftIndent=15, spaceAfter=3)

    def add_section(title, color=None):
        c = color or theme['primary']
        data = [[Paragraph(f'<b>{title}</b>', section_style)]]
        t = Table(data, colWidths=[17*cm], rowHeights=[0.65*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(c)),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.15*cm))

    def add_box(content, bg='#E3F2FD', border='#1976D2'):
        box = [[Paragraph(content, body_style)]]
        t = Table(box, colWidths=[17*cm])
        t.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,-1), HexColor(bg)),
            ('LEFTPADDING', (0,0), (-1,-1), 10),
            ('TOPPADDING', (0,0), (-1,-1), 8),
            ('BOTTOMPADDING', (0,0), (-1,-1), 8),
            ('BOX', (0,0), (-1,-1), 0.5, HexColor(border)),
        ]))
        story.append(t)
        story.append(Spacer(1, 0.2*cm))

    # ===== HEADER =====
    story.append(Paragraph("📋 Meeting Summary", title_style))
    story.append(Paragraph(
        f"{meeting_data.get('name', 'Meeting')} | {meeting_data.get('date', '')}",
        subtitle_style))
    story.append(HRFlowable(width="100%", thickness=3,
                            color=HexColor(theme['primary'])))
    story.append(Spacer(1, 0.2*cm))

    # ===== STATS =====
    score = summary.get('meeting_effectiveness', 0)
    sentiment = summary.get('sentiment', 'Neutral')
    sentiment_color = theme['green'] if sentiment == 'Positive' else theme['orange'] if sentiment == 'Neutral' else theme['red']

    attendees_list = meeting_data.get('attendees', '').split(',')

    stats_data = [[
        Paragraph(f'<font color="white"><b>📅 Date</b><br/>{meeting_data.get("date", "")}</font>',
                 ParagraphStyle('s', fontSize=10, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>👥 Attendees</b><br/>{len(attendees_list)}</font>',
                 ParagraphStyle('s', fontSize=10, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>⚡ Effectiveness</b><br/>{score}/100</font>',
                 ParagraphStyle('s', fontSize=10, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>😊 Sentiment</b><br/>{sentiment}</font>',
                 ParagraphStyle('s', fontSize=10, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
        Paragraph(f'<font color="white"><b>🏷️ Type</b><br/>{meeting_data.get("type", "")[:15]}</font>',
                 ParagraphStyle('s', fontSize=10, textColor=white,
                               fontName='Helvetica-Bold', alignment=TA_CENTER)),
    ]]

    stats_table = Table(stats_data, colWidths=[3.4*cm]*5, rowHeights=[1.2*cm])
    stats_table.setStyle(TableStyle([
        ('BACKGROUND', (0,0), (0,-1), HexColor(theme['accent'])),
        ('BACKGROUND', (1,0), (1,-1), HexColor(theme['primary'])),
        ('BACKGROUND', (2,0), (2,-1), HexColor(theme['green'])),
        ('BACKGROUND', (3,0), (3,-1), HexColor(sentiment_color)),
        ('BACKGROUND', (4,0), (4,-1), HexColor(theme['purple'])),
        ('ALIGN', (0,0), (-1,-1), 'CENTER'),
        ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
    ]))
    story.append(stats_table)
    story.append(Spacer(1, 0.3*cm))

    # ===== ATTENDEES =====
    if meeting_data.get('attendees'):
        add_section('👥 ATTENDEES')
        attendees_text = meeting_data['attendees']
        story.append(Paragraph(f"📋 {attendees_text}", body_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== EXECUTIVE SUMMARY =====
    if summary.get('executive_summary'):
        add_section('📝 EXECUTIVE SUMMARY')
        add_box(summary['executive_summary'])

    # ===== KEY DISCUSSIONS =====
    discussions = summary.get('key_discussions', [])
    if discussions:
        add_section('💬 KEY DISCUSSIONS', theme['accent'])

        for i, disc in enumerate(discussions, 1):
            disc_data = [[
                Paragraph(f'<font color="white"><b>{i}. {disc.get("topic", "")}</b></font>',
                         ParagraphStyle('dh', fontSize=11, textColor=white,
                                       fontName='Helvetica-Bold'))
            ]]
            disc_header = Table(disc_data, colWidths=[17*cm], rowHeights=[0.6*cm])
            disc_header.setStyle(TableStyle([
                ('BACKGROUND', (0,0), (-1,-1), HexColor(theme['accent'])),
                ('LEFTPADDING', (0,0), (-1,-1), 10),
                ('VALIGN', (0,0), (-1,-1), 'MIDDLE'),
            ]))
            story.append(disc_header)

            if disc.get('summary'):
                story.append(Paragraph(
                    f"<b>Discussion:</b> {disc['summary']}", body_style))
            if disc.get('outcome'):
                story.append(Paragraph(
                    f"<b>Outcome:</b> {disc['outcome']}", body_style))
            story.append(Spacer(1, 0.15*cm))

    # ===== DECISIONS MADE =====
    decisions = summary.get('decisions_made', [])
    if decisions:
        add_section('✅ DECISIONS MADE', theme['green'])

        dec_data = [[
            Paragraph('<b>Decision</b>', ParagraphStyle('dh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Decided By</b>', ParagraphStyle('dh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Impact</b>', ParagraphStyle('dh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
        ]]

        for dec in decisions:
            dec_data.append([
                Paragraph(dec.get('decision', ''), body_style),
                Paragraph(dec.get('decided_by', ''), body_style),
                Paragraph(dec.get('impact', ''), body_style),
            ])

        dec_table = Table(dec_data, colWidths=[7*cm, 4*cm, 6*cm])
        dec_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), HexColor(theme['green'])),
            ('BACKGROUND', (0,1), (-1,-1), HexColor('#E8F5E9')),
            ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['green'])),
            ('LEFTPADDING', (0,0), (-1,-1), 8),
            ('TOPPADDING', (0,0), (-1,-1), 5),
            ('BOTTOMPADDING', (0,0), (-1,-1), 5),
            ('VALIGN', (0,0), (-1,-1), 'TOP'),
        ]))
        story.append(dec_table)
        story.append(Spacer(1, 0.3*cm))

    # ===== ACTION ITEMS =====
    actions = summary.get('action_items', [])
    if actions:
        story.append(PageBreak())
        add_section('🎯 ACTION ITEMS', theme['orange'])

        action_data = [[
            Paragraph('<b>Task</b>', ParagraphStyle('ah', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Assigned To</b>', ParagraphStyle('ah', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Deadline</b>', ParagraphStyle('ah', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Priority</b>', ParagraphStyle('ah', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
        ]]

        for action in actions:
            priority = action.get('priority', 'Medium')
            priority_color = theme['red'] if priority == 'High' else theme['orange'] if priority == 'Medium' else theme['green']

            action_data.append([
                Paragraph(action.get('task', ''), body_style),
                Paragraph(action.get('assigned_to', ''), body_style),
                Paragraph(action.get('deadline', ''), body_style),
                Paragraph(
                    f'<font color="{priority_color}"><b>{priority}</b></font>',
                    body_style),
            ])

        action_table = Table(action_data,
                            colWidths=[7*cm, 3.5*cm, 3.5*cm, 3*cm])
        action_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), HexColor(theme['orange'])),
            ('BACKGROUND', (0,1), (-1,-1), HexColor('#FBE9E7')),
            ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['orange'])),
            ('LEFTPADDING', (0,0), (-1,-1), 8),
            ('TOPPADDING', (0,0), (-1,-1), 5),
            ('BOTTOMPADDING', (0,0), (-1,-1), 5),
            ('VALIGN', (0,0), (-1,-1), 'TOP'),
        ]))
        story.append(action_table)
        story.append(Spacer(1, 0.3*cm))

    # ===== FOLLOW UPS =====
    follow_ups = summary.get('follow_ups', [])
    if follow_ups:
        add_section('🔄 FOLLOW UPS', theme['purple'])

        fu_data = [[
            Paragraph('<b>Item</b>', ParagraphStyle('fh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Responsible</b>', ParagraphStyle('fh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
            Paragraph('<b>Due Date</b>', ParagraphStyle('fh', fontSize=10,
                fontName='Helvetica-Bold', textColor=white)),
        ]]

        for fu in follow_ups:
            fu_data.append([
                Paragraph(fu.get('item', ''), body_style),
                Paragraph(fu.get('responsible', ''), body_style),
                Paragraph(fu.get('due_date', ''), body_style),
            ])

        fu_table = Table(fu_data, colWidths=[9*cm, 4*cm, 4*cm])
        fu_table.setStyle(TableStyle([
            ('BACKGROUND', (0,0), (-1,0), HexColor(theme['purple'])),
            ('BACKGROUND', (0,1), (-1,-1), HexColor('#F3E5F5')),
            ('GRID', (0,0), (-1,-1), 0.3, HexColor(theme['purple'])),
            ('LEFTPADDING', (0,0), (-1,-1), 8),
            ('TOPPADDING', (0,0), (-1,-1), 5),
            ('BOTTOMPADDING', (0,0), (-1,-1), 5),
        ]))
        story.append(fu_table)
        story.append(Spacer(1, 0.3*cm))

    # ===== BLOCKERS =====
    blockers = summary.get('blockers', [])
    if blockers:
        add_section('🚧 BLOCKERS', theme['red'])
        for blocker in blockers:
            story.append(Paragraph(f"⛔ {blocker}", bullet_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== RISKS =====
    risks = summary.get('risks_identified', [])
    if risks:
        add_section('⚠️ RISKS IDENTIFIED', theme['red'])
        for risk in risks:
            story.append(Paragraph(f"⚠️ {risk}", bullet_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== OPPORTUNITIES =====
    opportunities = summary.get('opportunities', [])
    if opportunities:
        add_section('🌟 OPPORTUNITIES', theme['green'])
        for opp in opportunities:
            story.append(Paragraph(f"✨ {opp}", bullet_style))
        story.append(Spacer(1, 0.2*cm))

    # ===== KEY QUOTES =====
    quotes = summary.get('key_quotes', [])
    if quotes:
        add_section('💬 KEY QUOTES', theme['accent'])
        for quote in quotes:
            add_box(f'"{quote}"', '#E3F2FD', theme['accent'])

    # ===== NEXT MEETING =====
    next_meeting = summary.get('next_meeting', {})
    if next_meeting:
        add_section('📅 NEXT MEETING', theme['green'])

        if next_meeting.get('suggested_date'):
            story.append(Paragraph(
                f"<b>Suggested Date:</b> {next_meeting['suggested_date']}",
                body_style))

        agenda = next_meeting.get('agenda', [])
        if agenda:
            story.append(Paragraph('<b>Agenda:</b>', body_style))
            for item in agenda:
                story.append(Paragraph(f"📌 {item}", bullet_style))

        story.append(Spacer(1, 0.2*cm))

    # ===== FOOTER =====
    story.append(HRFlowable(width="100%", thickness=1,
                            color=HexColor(theme['primary'])))
    story.append(Paragraph(
        f'Generated by MK-AI | Made by Mushab Khan | {datetime.now().strftime("%B %d, %Y")}',
        ParagraphStyle('footer', fontSize=8, fontName='Helvetica',
                      textColor=HexColor(theme['accent']),
                      alignment=TA_CENTER)))

    doc.build(story)
    print(f"✅ Meeting Summary PDF saved: {save_path}")
    return save_path

print("✅ Meeting PDF builder ready!")

#@title Meeting Email Summary Generator
def generate_meeting_email(summary, meeting_data):
    """Meeting ke baad email summary generate karo"""

    print("📧 Meeting summary email generate ho raha hai...")

    action_items = summary.get('action_items', [])
    decisions = summary.get('decisions_made', [])
    next_meeting = summary.get('next_meeting', {})

    action_text = '\n'.join([
        f"- {a.get('task', '')} → {a.get('assigned_to', '')} by {a.get('deadline', '')}"
        for a in action_items[:5]
    ])

    decision_text = '\n'.join([
        f"- {d.get('decision', '')}"
        for d in decisions[:5]
    ])

    prompt = f"""Write a professional post-meeting email summary:

Meeting: {meeting_data.get('name', '')}
Date: {meeting_data.get('date', '')}
Attendees: {meeting_data.get('attendees', '')}

Executive Summary: {summary.get('executive_summary', '')}

Key Decisions:
{decision_text}

Action Items:
{action_text}

Next Meeting: {next_meeting.get('suggested_date', 'TBD')}

Write a concise, professional email that:
1. Thanks attendees
2. Summarizes key decisions
3. Lists action items clearly
4. Mentions next steps
5. Professional closing

Return JSON only:
{{
  "subject": "Email subject",
  "body": "Complete email body"
}}"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "Expert email writer. Return JSON only."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=1000,
        temperature=0.5
    )

    import json, re
    result = response.choices[0].message.content.strip()

    try:
        email_data = json.loads(re.search(r'\{.*\}', result, re.DOTALL).group())

        print("\n📧 MEETING SUMMARY EMAIL:")
        print("="*60)
        print(f"SUBJECT: {email_data.get('subject', '')}")
        print(f"\nBODY:\n{email_data.get('body', '')}")
        print("="*60)

        return email_data
    except:
        print("⚠️ Email generate nahi hua")
        return {}

print("✅ Email generator ready!")

#@title Master Meeting Summarizer
from google.colab import files

def master_meeting_summarizer():
    """Full Meeting Summarizer Agent"""

    print("🚀 MK-AI Meeting Summarizer Starting...\n")

    # Input lo
    meeting_data = get_meeting_input()

    if not meeting_data.get('text'):
        print("❌ Meeting content nahi diya!")
        return

    # Summarize karo
    summary = summarize_meeting(meeting_data)

    if not summary:
        print("❌ Summary generate nahi hui!")
        return

    # Display karo
    print("\n" + "="*60)
    print("📋 MEETING SUMMARY")
    print("="*60)
    print(f"\n📝 {summary.get('executive_summary', '')}")
    print(f"\n⚡ Effectiveness: {summary.get('meeting_effectiveness', 0)}/100")
    print(f"😊 Sentiment: {summary.get('sentiment', '')}")

    actions = summary.get('action_items', [])
    if actions:
        print(f"\n🎯 Action Items ({len(actions)}):")
        for action in actions[:3]:
            print(f"   → {action.get('task', '')} | {action.get('assigned_to', '')} | {action.get('deadline', '')}")

    decisions = summary.get('decisions_made', [])
    if decisions:
        print(f"\n✅ Decisions ({len(decisions)}):")
        for dec in decisions[:3]:
            print(f"   → {dec.get('decision', '')}")

    # Export options
    print("\n📦 Export Options:")
    print("   1 → PDF banao")
    print("   2 → Email summary generate karo")
    print("   3 → Text file save karo")
    print("   4 → Sab karo")
    print("   5 → Skip")

    export_choice = input("\nChoice (1-5): ").strip()

    name = meeting_data.get('name', 'Meeting')

    if export_choice in ['1', '4']:
        print("📄 PDF bana raha hai...")
        save_path = f'/content/{name[:20].replace(" ", "_")}_Summary_MK-AI.pdf'
        build_meeting_pdf(summary, meeting_data, save_path)
        files.download(save_path)
        print("✅ PDF download ho gaya!")

    if export_choice in ['2', '4']:
        email_data = generate_meeting_email(summary, meeting_data)
        if email_data:
            email_path = f'/content/{name[:20].replace(" ", "_")}_Email_MK-AI.txt'
            import json
            with open(email_path, 'w', encoding='utf-8') as f:
                f.write(f"SUBJECT: {email_data.get('subject', '')}\n\n")
                f.write(email_data.get('body', ''))
            files.download(email_path)
            print("✅ Email file download ho gayi!")

    if export_choice in ['3', '4']:
        text_path = f'/content/{name[:20].replace(" ", "_")}_Notes_MK-AI.txt'
        import json
        with open(text_path, 'w', encoding='utf-8') as f:
            f.write(f"Meeting: {meeting_data.get('name', '')}\n")
            f.write(f"Date: {meeting_data.get('date', '')}\n")
            f.write(f"Attendees: {meeting_data.get('attendees', '')}\n\n")
            f.write(json.dumps(summary, indent=2, ensure_ascii=False))
        files.download(text_path)
        print("✅ Text file download ho gayi!")

    print("\n🎉 Meeting Summary ready hai bhai!")
    return summary

print("✅ Master Meeting Summarizer ready!")

