#@title Magic Formula Engine
def detect_intent(user_input):
    """User ka intent detect karo"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": """Detect the intent of user input.
Return JSON only:
{
  "intent": "email/code/image/essay/analysis/story/summary/translation/qa/other",
  "platform": "chatgpt/claude/gemini/midjourney/llama/general",
  "complexity": "beginner/intermediate/expert",
  "language_style": "formal/casual/technical/creative",
  "output_type": "text/code/image/list/table/json",
  "emotional_tone": "neutral/urgent/friendly/professional/empathetic"
}"""},
            {"role": "user", "content": user_input}
        ],
        max_tokens=200,
        temperature=0.1
    )

    try:
        return json.loads(re.search(r'\{.*\}',
            response.choices[0].message.content,
            re.DOTALL).group())
    except:
        return {
            "intent": "other",
            "platform": "general",
            "complexity": "intermediate",
            "language_style": "formal",
            "output_type": "text",
            "emotional_tone": "neutral"
        }

def apply_magic_formula(user_input, intent_data, options={}):
    """Advanced Magic Formula apply karo"""

    platform = options.get('platform', intent_data.get('platform', 'general'))
    complexity = options.get('complexity', intent_data.get('complexity', 'intermediate'))
    tone = options.get('tone', intent_data.get('emotional_tone', 'neutral'))
    style = options.get('style', intent_data.get('language_style', 'formal'))

    # Platform specific DNA
    platform_dna = {
        'chatgpt': """
- Use clear structured format
- Be explicit about output format
- Include step-by-step if needed
- GPT responds well to numbered lists""",
        'claude': """
- Provide rich context and background
- Claude loves detailed instructions
- Include examples when possible
- Specify thinking process required""",
        'gemini': """
- Include concrete examples
- Gemini responds well to comparisons
- Use clear formatting markers
- Specify multimodal needs if any""",
        'midjourney': """
- Use visual descriptors: lighting, style, mood
- Include art style references
- Specify aspect ratio and quality
- Use :: for weighted terms""",
        'llama': """
- Be concise and direct
- Llama works well with clear instructions
- Include output format explicitly
- Specify language if non-English""",
        'general': "Standard prompt format."
    }

    prompt = f"""You are the world's best prompt engineer.
Create a PERFECT prompt using Advanced Magic Formula.

User Request: {user_input}
Platform: {platform}
Complexity: {complexity}
Tone: {tone}
Style: {style}
Platform DNA: {platform_dna.get(platform, platform_dna['general'])}

Return ONLY valid JSON:
{{
  "prompt_v1": {{
    "persona": "Act as [specific expert role with years of experience]",
    "objective": "Your task is to [clear specific objective]",
    "context": "Background context: [relevant context]",
    "data": "Working with: [specific data/information]",
    "format": "Format your response as: [specific format]",
    "constraints": "Important rules: [specific constraints]",
    "examples": "Example of good output: [example if helpful]",
    "output_type": "Final output should be: [output specification]",
    "full_prompt": "Complete optimized prompt combining all elements"
  }},
  "prompt_v2": {{
    "full_prompt": "Alternative version with different approach"
  }},
  "prompt_v3": {{
    "full_prompt": "Expert level version for advanced users"
  }},
  "negative_prompt": "DO NOT: [what to avoid]",
  "anti_hallucination": "Only use verified information. If unsure, say 'I don't know'.",
  "score": 92,
  "score_breakdown": {{
    "clarity": 90,
    "specificity": 95,
    "context": 88,
    "output_format": 94
  }},
  "improvements": ["Improvement 1", "Improvement 2"],
  "tips": ["Tip for this platform", "General tip"],
  "estimated_tokens": 150,
  "difficulty": "{complexity}"
}}"""

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are the world's best prompt engineer. Create perfect prompts. Return only valid JSON."},
            {"role": "user", "content": prompt}
        ],
        max_tokens=3000,
        temperature=0.6
    )

    result = response.choices[0].message.content.strip()

    try:
        json_match = re.search(r'\{.*\}', result, re.DOTALL)
        if json_match:
            return json.loads(json_match.group())
    except Exception as e:
        print(f"⚠️ Error: {e}")

    return {}

print("✅ Magic Formula Engine ready!")

