#@title Prompt Library
def save_to_library(prompt_data, name, category):
    """Prompt library mein save karo"""

    entry = {
        "id": len(PROMPT_LIBRARY) + 1,
        "name": name,
        "category": category,
        "prompt": prompt_data,
        "saved_at": datetime.now().strftime("%Y-%m-%d %H:%M"),
        "uses": 0
    }

    PROMPT_LIBRARY.append(entry)
    print(f"✅ Saved to library: {name}")
    return entry

def view_library():
    """Library dekhao"""

    if not PROMPT_LIBRARY:
        print("📚 Library khali hai!")
        return

    print("\n" + "="*60)
    print("📚 PROMPT LIBRARY")
    print("="*60)

    categories = {}
    for item in PROMPT_LIBRARY:
        cat = item.get('category', 'General')
        if cat not in categories:
            categories[cat] = []
        categories[cat].append(item)

    for cat, items in categories.items():
        print(f"\n📁 {cat}:")
        for item in items:
            print(f"   {item['id']}. {item['name']} | Saved: {item['saved_at']}")

def use_from_library(prompt_id):
    """Library se prompt use karo"""

    for item in PROMPT_LIBRARY:
        if item['id'] == prompt_id:
            item['uses'] += 1
            print(f"\n📋 Prompt: {item['name']}")
            prompt_data = item.get('prompt', {})
            if isinstance(prompt_data, dict):
                full = prompt_data.get('prompt_v1', {}).get('full_prompt', '')
            else:
                full = str(prompt_data)
            print(f"\n{full}")
            return full

    print("❌ Prompt not found!")
    return None

def export_library():
    """Library export karo"""

    if not PROMPT_LIBRARY:
        print("📚 Library khali hai!")
        return

    save_path = '/content/Prompt_Library_MK-AI.txt'
    with open(save_path, 'w', encoding='utf-8') as f:
        f.write("MK-AI PROMPT LIBRARY\n")
        f.write(f"Exported: {datetime.now().strftime('%B %d, %Y')}\n")
        f.write("="*60 + "\n\n")

        for item in PROMPT_LIBRARY:
            f.write(f"[{item['id']}] {item['name']}\n")
            f.write(f"Category: {item['category']}\n")
            f.write(f"Saved: {item['saved_at']}\n")

            prompt_data = item.get('prompt', {})
            if isinstance(prompt_data, dict):
                full = prompt_data.get('prompt_v1', {}).get('full_prompt', '')
            else:
                full = str(prompt_data)

            f.write(f"Prompt:\n{full}\n")
            f.write("-"*40 + "\n\n")

    from google.colab import files
    files.download(save_path)
    print("✅ Library exported!")

print("✅ Prompt library ready!")

#@title Master Prompt Engineer Agent
def prompt_engineer_agent():
    """Full Prompt Engineer Agent"""

    print("="*60)
    print("🧠 MK-AI PROMPT ENGINEER")
    print("="*60)

    while True:
        print("\n🎯 Kya karna hai?")
        print("   1 → Naya prompt banao (Magic Formula)")
        print("   2 → Existing prompt improve karo")
        print("   3 → Prompt debug karo")
        print("   4 → Batch prompts banao (10 at once)")
        print("   5 → Secret formula reveal karo")
        print("   6 → Prompt chain banao")
        print("   7 → Viral prompts fetch karo")
        print("   8 → Prompt score karo")
        print("   9 → Library dekhao")
        print("   10 → Library export karo")
        print("   0 → Exit")

        choice = input("\nChoice: ").strip()

        if choice == '0':
            break

        elif choice == '1':
            print("\n💬 Simple mein batao kya chahiye:")
            user_input = input("Tumhara idea: ").strip()

            # Platform choose
            print("\n🤖 Platform:")
            print("   1→ChatGPT  2→Claude  3→Gemini")
            print("   4→Midjourney  5→Llama  6→General")
            platform_map = {
                '1': 'chatgpt', '2': 'claude', '3': 'gemini',
                '4': 'midjourney', '5': 'llama', '6': 'general'
            }
            platform = platform_map.get(input("Choice: ").strip(), 'general')

            # Complexity
            print("\n📊 Complexity:")
            print("   1→Beginner  2→Intermediate  3→Expert")
            comp_map = {'1': 'beginner', '2': 'intermediate', '3': 'expert'}
            complexity = comp_map.get(input("Choice: ").strip(), 'intermediate')

            # Tone
            print("\n🎭 Tone:")
            print("   1→Neutral  2→Urgent  3→Friendly")
            print("   4→Professional  5→Empathetic")
            tone_map = {
                '1': 'neutral', '2': 'urgent', '3': 'friendly',
                '4': 'professional', '5': 'empathetic'
            }
            tone = tone_map.get(input("Choice: ").strip(), 'neutral')

            # Intent detect
            print("\n🔍 Intent detect ho raha hai...")
            intent = detect_intent(user_input)

            # Magic Formula apply
            print("✨ Magic Formula apply ho raha hai...")
            result = apply_magic_formula(user_input, intent, {
                'platform': platform,
                'complexity': complexity,
                'tone': tone
            })

            if result:
                print("\n" + "="*60)
                print("✨ MAGIC FORMULA RESULT")
                print("="*60)

                v1 = result.get('prompt_v1', {})
                print(f"\n🎯 ADVANCED FORMULA:")
                print(f"   PERSONA: {v1.get('persona', '')}")
                print(f"   OBJECTIVE: {v1.get('objective', '')}")
                print(f"   CONTEXT: {v1.get('context', '')}")
                print(f"   DATA: {v1.get('data', '')}")
                print(f"   FORMAT: {v1.get('format', '')}")
                print(f"   CONSTRAINTS: {v1.get('constraints', '')}")
                print(f"   OUTPUT: {v1.get('output_type', '')}")

                print(f"\n📝 VERSION 1 (Full Prompt):")
                print(f"{v1.get('full_prompt', '')}")

                v2 = result.get('prompt_v2', {})
                if v2:
                    print(f"\n📝 VERSION 2 (Alternative):")
                    print(f"{v2.get('full_prompt', '')}")

                v3 = result.get('prompt_v3', {})
                if v3:
                    print(f"\n📝 VERSION 3 (Expert):")
                    print(f"{v3.get('full_prompt', '')}")

                if result.get('negative_prompt'):
                    print(f"\n❌ NEGATIVE PROMPT:")
                    print(f"{result['negative_prompt']}")

                if result.get('anti_hallucination'):
                    print(f"\n🛡️ ANTI-HALLUCINATION:")
                    print(f"{result['anti_hallucination']}")

                score = result.get('score', 0)
                print(f"\n📊 PROMPT SCORE: {score}/100")

                score_breakdown = result.get('score_breakdown', {})
                if score_breakdown:
                    print(f"   Clarity: {score_breakdown.get('clarity', 0)}/100")
                    print(f"   Specificity: {score_breakdown.get('specificity', 0)}/100")
                    print(f"   Context: {score_breakdown.get('context', 0)}/100")
                    print(f"   Format: {score_breakdown.get('output_format', 0)}/100")

                tips = result.get('tips', [])
                if tips:
                    print(f"\n💡 TIPS:")
                    for tip in tips:
                        print(f"   → {tip}")

                # Test karo
                test = input("\n🧪 Groq se test karein? (haan/nahi): ").strip().lower()
                if test in ['haan', 'ha', 'y', 'yes', 'h']:
                    full_prompt = v1.get('full_prompt', '')
                    if full_prompt:
                        print("\n⏳ Testing...")
                        test_response = groq_client.chat.completions.create(
                            model="llama-3.3-70b-versatile",
                            messages=[{"role": "user", "content": full_prompt}],
                            max_tokens=500,
                            temperature=0.7
                        )
                        print(f"\n🤖 Test Result:\n{test_response.choices[0].message.content}")

                # Save karo
                save = input("\n💾 Library mein save karein? (haan/nahi): ").strip().lower()
                if save in ['haan', 'ha', 'y', 'yes', 'h']:
                    name = input("Prompt ka naam: ").strip()
                    category = input("Category (e.g. Email/Code/Creative): ").strip()
                    save_to_library(result, name, category)

        elif choice == '2':
            print("\n📝 Existing prompt paste karo (phir 'DONE'):")
            lines = []
            while True:
                line = input()
                if line.strip().upper() == 'DONE':
                    break
                lines.append(line)
            prompt_text = '\n'.join(lines)
            goal = input("Improvement goal (e.g. more specific): ").strip()

            print("🔧 Improving...")
            improved = improve_prompt(prompt_text, goal)

            if improved:
                print(f"\n✅ IMPROVED PROMPT:")
                print(f"{improved.get('improved_prompt', '')}")
                print(f"\n📈 Score: {improved.get('score_before', 0)} → {improved.get('score_after', 0)}")
                changes = improved.get('changes_made', [])
                if changes:
                    print(f"\n🔧 Changes:")
                    for change in changes:
                        print(f"   → {change}")

        elif choice == '3':
            print("\n📝 Buggy prompt paste karo (phir 'DONE'):")
            lines = []
            while True:
                line = input()
                if line.strip().upper() == 'DONE':
                    break
                lines.append(line)
            prompt_text = '\n'.join(lines)
            bad_output = input("Bad output mila tha? (optional): ").strip()

            print("🔍 Debugging...")
            debug = debug_prompt(prompt_text, bad_output)

            if debug:
                print(f"\n🐛 PROBLEMS:")
                for prob in debug.get('problems', []):
                    print(f"   ❌ {prob}")
                print(f"\n🔑 ROOT CAUSE: {debug.get('root_cause', '')}")
                print(f"\n✅ FIXED PROMPT:\n{debug.get('fixed_prompt', '')}")

        elif choice == '4':
            topic = input("\n📌 Topic kya hai?: ").strip()
            count = int(input("Kitne prompts? (max 10): ").strip() or "5")
            count = min(count, 10)

            print(f"⚡ {count} prompts generate ho rahe hain...")
            batch = generate_batch_prompts(topic, count)

            prompts = batch.get('prompts', [])
            print(f"\n📋 {len(prompts)} PROMPTS:")
            for p in prompts:
                print(f"\n{p.get('number', '')}. {p.get('approach', '')}")
                print(f"   Best for: {p.get('best_for', '')}")
                print(f"   {p.get('prompt', '')[:150]}...")

        elif choice == '5':
            print("\n🤖 Konsa AI?")
            print("   1→ChatGPT  2→Claude  3→Gemini")
            print("   4→Midjourney  5→Llama")
            ai_map = {
                '1': 'ChatGPT', '2': 'Claude', '3': 'Gemini',
                '4': 'Midjourney', '5': 'Llama'
            }
            ai_name = ai_map.get(input("Choice: ").strip(), 'ChatGPT')
            task = input("Task type (e.g. writing/coding/image): ").strip()

            print(f"🔍 {ai_name} ka secret formula reveal ho raha hai...")
            formula = reveal_secret_formula(ai_name, task)

            if formula:
                print(f"\n🔐 SECRET FORMULA: {ai_name} + {task}")
                print(f"\n📋 Formula:\n{formula.get('secret_formula', '')}")
                print(f"\n⚡ Power Words: {', '.join(formula.get('power_words', []))}")
                print(f"\n❌ Avoid Words: {', '.join(formula.get('avoid_words', []))}")
                print(f"\n📝 Example:\n{formula.get('example_prompt', '')}")
                tips = formula.get('pro_tips', [])
                if tips:
                    print(f"\n💡 Pro Tips:")
                    for tip in tips:
                        print(f"   → {tip}")

        elif choice == '6':
            print("\n📋 Tasks list karo (comma separated):")
            tasks_input = input("Tasks: ").strip()
            tasks = [t.strip() for t in tasks_input.split(',')]

            print("🔗 Chain bana raha hai...")
            chain = chain_prompts(tasks)

            chain_steps = chain.get('chain', [])
            print(f"\n⛓️ PROMPT CHAIN ({len(chain_steps)} steps):")
            print(f"Description: {chain.get('workflow_description', '')}")
            print(f"Time: {chain.get('estimated_time', '')}")

            for step in chain_steps:
                print(f"\nStep {step.get('step', '')}: {step.get('task', '')}")
                print(f"   Prompt: {step.get('prompt', '')[:100]}...")
                print(f"   Output: {step.get('output', '')}")

        elif choice == '7':
            category = input("\n📌 Category (e.g. writing/coding/business): ").strip()
            viral = get_viral_prompts(category)

            prompts = viral.get('viral_prompts', [])
            print(f"\n🔥 {len(prompts)} VIRAL PROMPTS:")
            for p in prompts:
                print(f"\n📌 {p.get('title', '')}")
                print(f"   Platform: {p.get('platform', '')}")
                print(f"   Use: {p.get('use_case', '')}")
                print(f"   {p.get('prompt', '')[:150]}...")

        elif choice == '8':
            print("\n📝 Prompt paste karo (phir 'DONE'):")
            lines = []
            while True:
                line = input()
                if line.strip().upper() == 'DONE':
                    break
                lines.append(line)
            prompt_text = '\n'.join(lines)

            print("📊 Scoring...")
            score_result = score_prompt(prompt_text)

            if score_result:
                print(f"\n📊 PROMPT SCORE: {score_result.get('overall_score', 0)}/100")
                print(f"   Clarity: {score_result.get('clarity', 0)}/100")
                print(f"   Specificity: {score_result.get('specificity', 0)}/100")
                print(f"   Context: {score_result.get('context', 0)}/100")
                print(f"   Format: {score_result.get('format', 0)}/100")

                strengths = score_result.get('strengths', [])
                if strengths:
                    print(f"\n✅ Strengths:")
                    for s in strengths:
                        print(f"   → {s}")

                weaknesses = score_result.get('weaknesses', [])
                if weaknesses:
                    print(f"\n❌ Weaknesses:")
                    for w in weaknesses:
                        print(f"   → {w}")

                if score_result.get('improved_version'):
                    print(f"\n✨ Improved Version:\n{score_result['improved_version']}")

        elif choice == '9':
            view_library()

        elif choice == '10':
            export_library()

        print("\n" + "="*60)

