import requests
from PIL import Image
import io, os, json, re
from IPython.display import display as ipy_display, Image as IPyImage
from google.colab import files
print("✅ Image generation libraries ready!")

#@title Image Prompt Enhancer
def enhance_image_prompt(simple_prompt, style='realistic'):
    """Simple prompt ko professional image prompt mein convert karo"""

    style_guides = {
        'realistic': 'photorealistic, 8k uhd, high detail, professional photography, natural lighting',
        'anime': 'anime style, manga art, vibrant colors, detailed, Studio Ghibli inspired',
        'oil_painting': 'oil painting, classical art style, rich textures, museum quality',
        'digital_art': 'digital art, concept art, artstation trending, highly detailed',
        'sketch': 'pencil sketch, hand drawn, detailed linework, artistic',
        '3d_render': '3D render, octane render, cinema 4d, photorealistic, studio lighting',
        'photography': 'professional photography, DSLR, bokeh, golden hour lighting, sharp focus',
        'watercolor': 'watercolor painting, soft colors, artistic, flowing',
        'cartoon': 'cartoon style, vibrant, flat design, comic book art',
        'cyberpunk': 'cyberpunk, neon lights, futuristic, blade runner style, dark atmosphere'
    }

    style_suffix = style_guides.get(style, style_guides['realistic'])

    response = groq_client.chat.completions.create(
        model="llama-3.3-70b-versatile",
        messages=[
            {"role": "system", "content": "You are an expert at writing Stable Diffusion image prompts. Create detailed, descriptive prompts."},
            {"role": "user", "content": f"""Enhance this image prompt:
Simple: {simple_prompt}
Style: {style}

Return JSON only:
{{
  "enhanced_prompt": "Detailed prompt with visual descriptors, lighting, composition, style",
  "negative_prompt": "blur, deformed, ugly, bad anatomy, watermark, text",
  "style_tags": ["tag1", "tag2", "tag3"],
  "mood": "Mood of the image",
  "composition": "How image should be composed"
}}

Add these style elements: {style_suffix}"""}
        ],
        max_tokens=500,
        temperature=0.7
    )

    try:
        result = json.loads(re.search(r'\{.*\}',
            response.choices[0].message.content,
            re.DOTALL).group())
        return result
    except:
        return {
            "enhanced_prompt": f"{simple_prompt}, {style_suffix}",
            "negative_prompt": "blur, deformed, ugly, bad anatomy, watermark",
            "style_tags": [style],
            "mood": "Creative",
            "composition": "Centered"
        }

print("✅ Prompt enhancer ready!")

#@title Pollinations AI Image Generator
import urllib.parse
import time

def generate_image_pollinations(prompt, negative_prompt="",
                                 width=1024, height=1024,
                                 model='flux', seed=None):
    """Pollinations AI se image generate karo — FREE"""

    print(f"🎨 Image generate ho rahi hai...")
    print(f"   Prompt: {prompt[:80]}...")

    # URL encode karo
    encoded_prompt = urllib.parse.quote(prompt)

    # Seed
    if not seed:
        import random
        seed = random.randint(1, 99999)

    # Models available: flux, flux-realism, flux-anime,
    #                   flux-3d, any-dark, turbo
    url = f"https://image.pollinations.ai/prompt/{encoded_prompt}?width={width}&height={height}&model={model}&seed={seed}&nologo=true"

    try:
        response = requests.get(url, timeout=60)

        if response.status_code == 200:
            img = Image.open(io.BytesIO(response.content))
            print(f"✅ Image ready! Size: {img.size}")
            return img, response.content, url
        else:
            print(f"❌ Error: {response.status_code}")
            return None, None, None

    except Exception as e:
        print(f"❌ Error: {e}")
        return None, None, None

def generate_batch_images(prompt, styles=['realistic', 'anime', 'digital_art', 'oil_painting']):
    """Ek prompt se 4 different style images banao"""

    print(f"\n🎨 Batch generation: 4 images...")

    model_map = {
        'realistic': 'flux-realism',
        'anime': 'flux-anime',
        'digital_art': 'flux',
        'oil_painting': 'flux',
        '3d_render': 'flux-3d',
        'dark': 'any-dark',
        'fast': 'turbo'
    }

    results = []
    for style in styles[:4]:
        print(f"\n   Generating {style}...")
        model = model_map.get(style, 'flux')
        img, content, url = generate_image_pollinations(
            prompt, model=model)
        if img:
            results.append({
                'style': style,
                'image': img,
                'content': content,
                'url': url
            })
        time.sleep(1)

    return results

print("✅ Pollinations generator ready!")

#@title Hugging Face Image Generator
import requests as req

HF_TOKEN = ""  # Optional — free tier bhi kaam karta hai

def generate_image_hf(prompt, negative_prompt="blur, bad quality",
                       model="stabilityai/stable-diffusion-xl-base-1.0"):
    """Hugging Face se image generate karo"""

    print(f"🤗 HuggingFace image generate ho rahi hai...")

    API_URL = f"https://api-inference.huggingface.co/models/{model}"

    headers = {}
    if HF_TOKEN:
        headers["Authorization"] = f"Bearer {HF_TOKEN}"

    payload = {
        "inputs": prompt,
        "parameters": {
            "negative_prompt": negative_prompt,
            "num_inference_steps": 30,
            "guidance_scale": 7.5
        }
    }

    try:
        response = req.post(API_URL, headers=headers,
                           json=payload, timeout=120)

        if response.status_code == 200:
            img = Image.open(io.BytesIO(response.content))
            print(f"✅ HF Image ready!")
            return img, response.content
        elif response.status_code == 503:
            print("⏳ Model loading hai, 30 seconds wait karo...")
            time.sleep(30)
            return generate_image_hf(prompt, negative_prompt, model)
        else:
            print(f"❌ HF Error: {response.status_code}")
            return None, None

    except Exception as e:
        print(f"❌ Error: {e}")
        return None, None

print("✅ HuggingFace generator ready!")

#@title Image Display + Save
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def display_image(img, title="MK-AI Generated Image"):
    """Image display karo Colab mein"""

    if img is None:
        print("❌ Image nahi hai!")
        return

    plt.figure(figsize=(10, 10))
    plt.imshow(img)
    plt.title(title, fontsize=14, fontweight='bold')
    plt.axis('off')
    plt.tight_layout()
    plt.savefig('/content/temp_display.png',
                bbox_inches='tight', dpi=150)
    plt.close()
    ipy_display(IPyImage('/content/temp_display.png'))

def display_batch_images(results):
    """Batch images display karo"""

    if not results:
        print("❌ Koi image nahi!")
        return

    n = len(results)
    fig, axes = plt.subplots(1, n, figsize=(5*n, 5))

    if n == 1:
        axes = [axes]

    for ax, result in zip(axes, results):
        ax.imshow(result['image'])
        ax.set_title(result['style'].replace('_', ' ').title(),
                    fontsize=12, fontweight='bold')
        ax.axis('off')

    plt.suptitle('MK-AI Image Generation',
                fontsize=16, fontweight='bold')
    plt.tight_layout()
    plt.savefig('/content/batch_display.png',
                bbox_inches='tight', dpi=150)
    plt.close()
    ipy_display(IPyImage('/content/batch_display.png'))

def save_image(img_content, filename=None):
    """Image save + download karo"""

    if not filename:
        filename = f'MK-AI_Image_{datetime.now().strftime("%Y%m%d_%H%M%S")}.png'

    save_path = f'/content/{filename}'
    with open(save_path, 'wb') as f:
        f.write(img_content)

    files.download(save_path)
    print(f"✅ Image downloaded: {filename}")

    # Drive mein bhi save karo
    drive_path = f'/content/drive/MyDrive/MK-AI-Images/{filename}'
    try:
        os.makedirs('/content/drive/MyDrive/MK-AI-Images/', exist_ok=True)
        with open(drive_path, 'wb') as f:
            f.write(img_content)
        print(f"✅ Drive mein bhi saved!")
    except:
        pass

print("✅ Display + Save ready!")

