SAVE_DIR = "/content/MK-AI-Images"
os.makedirs(SAVE_DIR, exist_ok=True)


# ──────────────────────────────────────────────────────────────────
def _yn(question: str) -> bool:
    """Simple haan/nahi helper."""
    ans = input(f"{question} (haan/nahi): ").strip().lower()
    return ans in ['haan', 'ha', 'h', 'y', 'yes', '1']


def _save(content: bytes, style: str, prefix="MK-AI") -> str:
    filename = f"{prefix}_{style}_{datetime.now().strftime('%H%M%S')}.png"
    filepath = os.path.join(SAVE_DIR, filename)
    with open(filepath, "wb") as f:
        f.write(content)
    print(f"   💾 Saved → {filepath}")
    return filepath


